      //   （跟 .task-preview 踩过的坑一模一样，见下面那段注释）。
      const refPanelEl = refHost.querySelector('.ref-panel.show');
      if (refPanelEl && hitRect(x, y, refPanelEl, 0, PAD_Y)) return true;
