// ═══════════════════════════════════════════════════════════
//  任务区 —— 数据驱动版
//  任务不是常驻的: 由正式业务调度接口添加, 10~20 秒后自动消失。
//  入场: 从主卡下方"分离"进入(Apple 语言) → 新任务加在堆叠顶部
//  出场: 向下滑出
// ═══════════════════════════════════════════════════════════
const PER = 4;              // 预览一行最多几张
const MAX_SHOTS = 16;       // 单个任务最多几张图
// ⭐⭐⭐ 2026-10-08（docs/170 §十四 · 用户拍板）：启动时【一次性】清掉历史遗留的插帧文件。
//
//  背景：插帧帧以前会落盘（10-05 那版「省下次重算」），实测攒了
//    3348 个 tween_* 文件 / 22.80 GB。用户 10-08 拍板不再存硬盘，
//    所以这些遗留文件这辈子不会再被用到 —— 清掉把空间还给他。
//
//  ⚠ 只清一次：localStorage 记个标记。每次启动都扫一遍几千个文件的目录，
//    会让开机变慢，而这件事第二次做时已经无事可做。
//  ⚠ 清了要【告诉用户】：「清理了 N 个插帧缓存文件、释放 X GB」——
//    悄悄删掉几个 G 是个很坏的体验（用户会以为软件在偷他的东西）。
//  ⚠ 删的是【插帧帧文件】，绝不碰成品/底版/原图（Rust 那边白名单式判定保证）。
//  ⚠ 失败不报错、不打断启动：它只是清垃圾，清不动不该挡着用户用软件。
async function purgeLegacyTweenFilesOnce(){
  const FLAG = 'tween.legacyPurged.v1';
  try{ if(window.localStorage && localStorage.getItem(FLAG)) return; }catch(_){ return; }
  const cache = window.uiwin && window.uiwin.cache;
  if(!cache || typeof cache.purgeTweenFiles !== 'function' || typeof cache.list !== 'function'){
    // ⚠ 接口不在（测试环境 / 老客户端）⇒ 不打标记，下次启动还会再试
    return;
  }
  let removed = 0, bytes = 0;
  try{
    const listing = await cache.list();
    const runs = (listing && listing.runs) || [];
    for(const run of runs){
      if(!run || !run.project || !run.runId) continue;
      // 一轮一轮地清；Rust 那边每次有上限（默认 400），避免长时间占着缓存
      for(let guard = 0; guard < 50; guard++){
        const res = await cache.purgeTweenFiles({
          namespaceId: String((run.meta && run.meta.namespaceId) || ''),
          project: run.project, runId: run.runId, batch: 400,
        });
        if(!res || res.ok !== true) break;
        removed += Number(res.removed) || 0;
        bytes += Number(res.bytes) || 0;
        if(!res.remaining) break;      // 这一条清干净了
      }
    }
  }catch(e){
    // ⚠ 不报错、不打断启动；也不打标记（下次启动再试）
    return;
  }
  try{ if(window.localStorage) localStorage.setItem(FLAG, '1'); }catch(_){}
  if(removed > 0){
    const gb = (bytes / 1073741824).toFixed(2);
    // ⚠ 必须说：用户有权知道删了什么、释放了多少
    if(typeof UI !== 'undefined' && UI.toast){
      UI.toast('已清理 ' + removed + ' 个插帧缓存文件 · 释放 ' + gb + ' GB', 'info', 4200);
    } else if(typeof log === 'function'){
      log('插帧缓存清理：' + removed + ' 个文件 · ' + gb + ' GB');
    }
  }
}
const tasksEl = document.getElementById('tasks');

let taskList = [];          // [{ id, label, icon, shots:[{done}], pct, status, sub, timer }]
let browserTaskLockController=null;
function refreshBrowserTaskLock(){
  if(!window.V7BrowserPreferences||!window.uiwin?.browser||typeof taskList==='undefined')return;
  try{
    if(!browserTaskLockController)browserTaskLockController=V7BrowserPreferences.createTaskLock({onChange:state=>{try{const request=window.uiwin.browser.taskLock(!!state.locked);if(request&&typeof request.catch==='function')request.catch(()=>{});}catch(_){}}});
    const preferences=window.V7BrowserBookmarks?.read?.()||V7BrowserPreferences.defaults();
    const count=taskList.filter(task=>task&&!aiTaskIsTerminal(task)).length;
    browserTaskLockController.update({idleLock:preferences.idleLock,taskCount:count});
  }catch(error){try{browserTaskLockController?.update({idleLock:true,taskCount:null});}catch(_){};if(window.ERR)ERR.report('BROWSER_PREFERENCES_FAILED',{message:String(error.message||error)});}
}
if(window.V7CommunityPresence)window.V7CommunityPresence.configure({hasPendingGeneration:()=>taskList.some(task=>task&&task.kind==='generation'&&!aiTaskIsTerminal(task))});
let tcur = 0;               // 当前显示的任务下标
let taskSeq = 0;            // 自增 id

// 随机任务类型池(与主卡的五个区块呼应)
// 2026-10-22（docs/263 §1.5）：图标一律用 ICON 的矢量名，不再用 emoji
//   （emoji 各系统长得不一样、不跟主题色、会把行高撑歪）。
const TASK_TYPES = [
  { label: '修图·调色', icon: 'palette' }, { label: '修图·裁剪', icon: 'scissors' },
  { label: '修图·抠图', icon: 'broom' }, { label: '修图·精修', icon: 'sliders' },
  { label: '特效·光效', icon: 'bulb' }, { label: '特效·氛围', icon: 'fog' },
  { label: '特效·风格', icon: 'film' }, { label: '合成·拼接', icon: 'thread' },
  { label: '合成·蒙版', icon: 'mask' }, { label: '合成·多重曝光', icon: 'image' },
  { label: '上课·演示', icon: 'chart' }, { label: '上课·讲义', icon: 'note' }
];
const SIZES = ['1K', '2K', '4K'];

// 生成任务统一标准：所有生成请求都必须先创建任务卡，再进入提交/执行阶段。
// 任务卡是唯一的用户可见进度载体，状态只允许 queued/submitting/running/done/failed/cancelled。
const GENERATION_TASK_STANDARD = Object.freeze({
  version: 'v7-generation-task-1',
  states: Object.freeze(['queued','submitting','running','done','failed','cancelled']),
  required: Object.freeze(['provider','model','size','aspectRatio','batch','prompt']),
  errorShape: Object.freeze(['code','level','stage','message','raw'])
});

// 占位缩略图
function placeholderSVG(hue){
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" width="84" height="84"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${hue},70%,55%)"/><stop offset="1" stop-color="hsl(${hue+40},60%,40%)"/></linearGradient></defs><rect width="84" height="84" fill="url(#g)"/><text x="42" y="48" font-size="16" fill="rgba(255,255,255,.7)" text-anchor="middle">IMG</text></svg>`);
}
function escapeHtml(value){
  return String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({
    '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'
  })[ch]);
}

// ── 建一个虚拟任务(随机类型 / 随机张数 / 随机存活时长) ──
function makeVirtualTask(){
  const t = TASK_TYPES[Math.floor(Math.random() * TASK_TYPES.length)];
  const n = 1 + Math.floor(Math.random() * MAX_SHOTS);       // 1~16 张
  const doneCount = Math.floor(Math.random() * (n + 1));      // 已完成几张
  const pct = Math.round(doneCount / n * 100);
  const allDone = doneCount === n;
  // 任务卡背景 = "准备计算的图"(生成流程喂进来的源图)。虚拟任务用占位图模拟。
  const srcHue = Math.floor(Math.random() * 360);
  const sourceImg = placeholderSVG(srcHue);
  return {
    id: ++taskSeq,
    label: t.label,
    icon: allDone ? 'check' : 'hourglass',
    shots: Array.from({ length: n }, (_, i) => ({ done: i < doneCount })),
    pct,
    status: allDone ? 'done' : 'running',
    sub: allDone
      ? `${SIZES[Math.floor(Math.random()*3)]} ×${n} · ${(1 + Math.random()*8).toFixed(1)}s`
      : `进行中 ${doneCount}/${n} · 预计 ${Math.ceil(Math.random()*20)}s`,
    page: 0,
    sourceImg,
    life: 10000 + Math.random() * 10000    // 10~20 秒后自动消失
  };
}

// 任务卡背景(输入图)的唯一登记入口。
// ⚠ 必须过图片管家: 直接把完整 base64 当 CSS 背景 = 21MB 字符串 + 整图解码提主题色,
//   正是 docs/21 要根治的东西; 而且不登记就没有 imgId, 缓存判定"没有输入图",
//   重启后卡片背景会变回占位渐变。
// ⚠ 会被调用两次(建卡时 / 抓到图后), 已经登记过就不重复做。
const sourceImageRegistering = new Map();
let sourceImageEpoch = 0;
function registerTaskSourceImage(taskId, base64, mime){
  if(!base64 || !window.IMG) return;
  const key = String(taskId);
  const find = ()=>taskList.find(t=>String(t.id)===key||String(t.taskId||'')===key);
  const existing = find(), previous = sourceImageRegistering.get(key);
  if(existing && existing.sourceImgId) return;
  if(previous && previous.epoch===sourceImageEpoch && (!previous.task || previous.task===existing)) return previous.pending;
  const operation = {epoch:sourceImageEpoch,task:existing};
  sourceImageRegistering.set(key,operation);
  // makeGenerationTask registers before addTask; bind identity after that synchronous insertion.
  operation.pending = Promise.resolve().then(async()=>{
    if(operation.epoch!==sourceImageEpoch) return;
    const task=operation.task||find(); operation.task=task;
    if(!task || find()!==task || task.sourceImgId) return;
    const imgId=await window.IMG.putFromBase64(base64,mime||'image/png');
    try{
      if(operation.epoch!==sourceImageEpoch || find()!==task || task.sourceImgId) return;
      updateTask(taskId,{sourceImg:window.IMG.thumb(imgId),sourceImgId:imgId});
      // The input thumbnail can finish registering after a terminal task was saved.
      if(!task.restoredFromCache && typeof aiTaskIsTerminal==='function' && aiTaskIsTerminal(task)
        && typeof cachePersistTask==='function') cachePersistTask(task);
    }finally{
      if(operation.epoch!==sourceImageEpoch || find()!==task || task.sourceImgId!==imgId) window.IMG.release(imgId);
    }
  })
    .catch(e=>{ ERR.report('SOURCE_IMAGE_REGISTER_FAILED',{message:String(e&&e.message||e)}); })
    .finally(()=>{ if(sourceImageRegistering.get(key)===operation) sourceImageRegistering.delete(key); });
  return operation.pending;
}
function makeGenerationTask(payload){
  const total=Math.max(1, Math.min(MAX_SHOTS, Number(payload&&payload.batch)||1));
  // 主图始终显示用户可见的正常原图；抗截断后的 inputImageBase64 只作为 Banana 内部输入。
  const sourceBase64=payload&&(payload.sourceImageBase64||payload.inputImageBase64);
  // 生成任务必须保存自己的 Photoshop 来源快照。不要让任务卡在后续抓取/切换文档后
  // 退回读取全局 aiRuntime.capture，否则完成传回会误贴到另一份文档/选区。
  const captureSnapshot=payload&&payload.captureSnapshot ? aiCaptureSnapshot(payload.captureSnapshot) : null;
  const taskId=++taskSeq;
  // 任务卡背景先给占位渐变，缩略图做好了再淡入(updateTask 里本来就有交叉淡入)。
  // ⚠ 以前这里直接把源图的完整 base64 当 CSS 背景挂上去：一张 4K 图 21MB 字符串，
  //   还要跑一次正则清洗、再整图解码去提主题色 —— 全是给一个 300px 宽的卡片背景干的。
  const source=placeholderSVG((taskId*53)%360);
  // ⚠ 建卡时来源快照多半还是 null(真正的抓取在这之后)，所以这里常常登记不上；
  //   aiGenerateNow 拿到快照后会再调一次同一个函数补上。两条路共用一个入口。
  registerTaskSourceImage(taskId, sourceBase64, payload&&payload.inputMime);
  const provider=String(payload&&payload.provider||'Banana');
  const model=String(payload&&payload.model||'未选模型');
  // ⭐ 记录与恢复卡记账用（2026-09-30）。这两个字段只给记录卡算钱/分类用，不参与请求。
  //   ⚠ provider 不够用：V7 只有 aji/momo/other 三种，grs 是 provider='other'
  //     配 connectionSlot='grs'（见 provider-connections.js）。少存 connectionSlot，
  //     记录卡就会把 grs 和自定义服务商混成一笔，价格全错。
  //   computeSource 区分「自己的 key」和「平台积分」—— 后者未必按本地价目表算。
  //   两个都可能缺（老记录/其它入口建的任务），记录卡会退回「以账单为准」兜底。
  const workflowMode=!!String(payload&&payload.workflowPresetId||'')||!!(payload&&payload.workflow);
  // ⭐ 2026-10-16（用户：「使用千问模式下的话，生成任务卡片的右下角还是会显示Banana的渠道」）：
  //   改走千问的单，卡上写「云端 · 千问 2.1」；记账的通道 / 算力来源也按千问记（connectionSlot='qwen'，
  //   记录卡 records-core 认它 →「以账单为准」，不再按阿吉价目表白算一笔钱）。
  //   ⚠ provider / model 原样留着（重新生成要拿它们重发；千问模式还开着就照样改道）。
  const qwenTask=aiWillQwen(payload);
  const computeSource=qwenTask?V7QwenMode.source():String(payload&&payload.computeSource||(workflowMode?settingsRuntime.workflowSource:settingsRuntime.imageComputeSource)||'own');
  const connectionSlot=qwenTask?'qwen':String((aiRuntime&&aiRuntime.connectionSlot)||provider);
  const channelLabel=qwenTask?aiQwenChannelLabel():'';
  return {
    id:taskId, kind:'generation', taskId:String(payload&&payload.taskId||''), antiMode:Math.max(0,Math.min(2,Number(payload&&payload.antiMode)||0)), standard:GENERATION_TASK_STANDARD.version,
    computeSource, connectionSlot, channelLabel,
    // ⭐⭐ 标题【永远显示预设名】（2026-09-13 用户定案）。
    //   优先级：预设名 > 张数·渠道·模型。
    //   理由：任务栏里叠着七八个任务时，"aji · AJbanana3"每一张都长一样，
    //   分不出谁是谁；而"甜美偶像风格面部精修"一眼就知道这是哪一批。
    //   ⚠ 没选预设（手打提示词）时显示【自定义提示词】，**不退回渠道·模型** ——
    //     那两样已经在底栏右边了，标题位再放一遍等于浪费最显眼的位置。
    //
    // 📌 留的口子：以后要接本地微型 LLM，给手打的提示词自动起个名
    //    （比如"甜美偶像风·大眼"），就替换下面这个 taskTitleOf 的兜底分支，
    //    别的地方一个字都不用动 —— 标题的唯一来源就是这里。
    label:taskTitleOf(payload),
    presetTitle:String(payload&&payload.presetTitle||''),
    presetId:String(payload&&payload.presetId||''),presetVersion:String(payload&&payload.presetVersion||''),protocol:payload&&payload.protocol,
    icon:'hourglass', shots:Array.from({length:total},()=>({done:false})),
    pct:0, status:'queued', sub:'准备提交 · '+String(payload&&payload.size||'2K')+' · '+String(payload&&payload.aspectRatio||'Auto')+' · '+total+' 张',
    page:0, sourceImg:source, sourceImgId:'', errorInfo:null, life:0, startedAt:Date.now(),
    captureSnapshot,
    outputs:[], errors:[],
    sourceDocId:captureSnapshot&&captureSnapshot.docId,
    sourceDocName:captureSnapshot&&captureSnapshot.docName,
    sourceSelection:captureSnapshot&&captureSnapshot.selection,
    sourceImageBase64:captureSnapshot&&captureSnapshot.sourceImageBase64,
    inputImageBase64:captureSnapshot&&captureSnapshot.inputImageBase64,
    provider,model,size:payload.size,aspectRatio:payload.aspectRatio,batch:total,prompt:payload.prompt,
    workflow:aiClonePlain(payload.workflow||null),workflowParameters:aiClonePlain(payload.workflowParameters||{}),workflowPresetId:String(payload.workflowPresetId||''),
    // ⭐ Phase F：这单是在"校色引擎没开"的条件下发的 —— 任务卡上给一行非阻断提示
    //   （说明为什么以后切不了底版），不挡生成。
    noMatchEngine:!!(aiRuntime&&aiRuntime.noMatchEngineHint),
    cancelRequested:false,returnState:'idle'
  };
}

// ═══ 抠像任务卡（2026-09-14 下半场）═════════════════════════
//  ⚠ 为什么抠像也要建任务卡：docs/20 写死的规矩 ——
//    "任务卡是用户看到状态的唯一入口"。原来抠像只往日志里写几行字，
//    用户点完看不见任何东西，以为没反应（这就是他报的"没有进入到任务栏"）。
//
//  ⚠ 和生成任务【共用同一套渲染和更新函数】，只有 kind 不一样：
//    进度条、缩略图、报错卡、✕ 收起 全是现成的。
//    唯一要注意的是那些只对生成成立的东西（张数·渠道·模型、传回/提升纹理按钮）
//    都已经按 kind 关掉了 —— 加新的任务种类时照着这条检查一遍。
function makeMattingTask(payload){
  const taskId=++taskSeq;
  const source=placeholderSVG((taskId*53)%360);
  return {
    id:taskId, kind:'matting', taskId:String(payload&&payload.taskId||''),
    // 标题就是那条预设的名字 —— 和生成任务卡同一条规矩（预设名 > 一切）
    label:String(payload&&payload.label||'抠像'),
    presetTitle:String(payload&&payload.label||''),
    icon:'hourglass',
    // 抠像一次就是一张，进度条只有一格
    shots:[{done:false}],
    pct:0, status:'queued', sub:'准备开始 · 等 Photoshop 选区',
    page:0, sourceImg:source, sourceImgId:'', errorInfo:null, life:0, startedAt:Date.now(),
    outputs:[], errors:[],
    // 报错卡的现场信息（见 updateGenerationTask 里按 kind 分流的那段）
    mattingTierName:'', mattingSize:'',
    sourceDocId:null, sourceDocName:'', sourceSelection:null,
    cancelRequested:false, returnState:'idle'
  };
}

function taskErrorInfo(error, stage, code){
  const raw=error&&typeof error==='object' ? error : {message:String(error||'未知错误')};
  const message=String(raw.message||raw.error||error||'未知错误');
  return {code:String(code||raw.code||'TASK_FAILED'),level:'error',stage:String(stage||'unknown'),message,raw};
}

function taskIsDone(status){return status==='done'||status==='success'||status==='completed';}
// ⭐ 2026-10-19（docs/250 第 20 条，用户定）：整单都失败的生成任务给一个「重跑」——原来的提示词、原图、区域原样再发一次，新任务顶掉这张卡。
//   只给「算的时候失败」的：抓图 / 检查参数 / 准备（参考图、前置动作、GRS 取 key）那几步失败的不给 —— 要么没有原图，要么重跑还是一样失败。
//   ⚠ 失败在哪一步记在 errorInfo.stage；重启恢复回来的任务 errorInfo 是空的，看 meta 存的 failedStage（cacheMetaFromTask）。
//   ⚠ 「请求成功、但一张图都没回来」那条路不写 errorInfo（stage 为空）—— 那就是算的时候失败，给。
//   ⚠ 重启恢复回来的工作流任务：工作流本体不进 meta，要靠预设库里还在的同一条预设，不在了就不给。
function taskWasWorkflow(task){
  return !!(task&&(task.workflow||/^(comfyui|forge|runninghub|rh)$/i.test(String(task.provider||''))));
}
function taskRerunEligible(task){
  if(!task||task.kind!=='generation'||task.status!=='failed'||task._rerunning)return false;
  if(task.migration&&task.migration.returnBlocked)return false;
  if((task.shots||[]).some(s=>s&&s.done)||(task.outputs||[]).length)return false;
  const stage=String(task.errorInfo&&task.errorInfo.stage||task.failedStage||'');
  if(['capture','validate','prepare'].indexOf(stage)>=0)return false;
  const snap=task.captureSnapshot;
  if(!snap)return false;
  if(!(snap.inputImageBase64||snap.imageBase64)&&!(task.sourceImgId&&window.IMG&&window.IMG.has(task.sourceImgId)))return false;
  if(!task._rerun&&taskWasWorkflow(task)){
    const preset=window.PRESETS&&typeof PRESETS.presetById==='function'?PRESETS.presetById(task.workflowPresetId):null;
    if(!(preset&&(preset.workflow||preset.forgeWorkflow)))return false;
  }
  return true;
}
// ⭐ 任务卡的操作行（2026-09-13 用户定案）。放在进度和状态文字【下面】单独一行，
//   不挤头部 —— 卡片只有 300px 宽，头部塞不下。
//
// 两个按钮，出现条件都跟着"现在能干什么"走：
//   · 提前结束 —— 还在跑时才有。把【已完成的先传回】，剩下的继续后台算
//   · 传回     —— 有【已完成但还没传回】的图时才有，括号里是张数
//
// ⚠ "提升纹理"（替换/增益）那两个按钮【不在这里】，在缩略图上，
//   而且只在那一张【已经传回 PS】之后才显示 —— 没传回就没有图层可嵌，
//   点了必然撞到"找不到图层"那道阀。这是用户 2026-09-13 指出的，从源头堵住。
function taskActionsHtml(task){
  if(task&&task.kind==='dlss')return '<div class="t-acts"><button class="t-act primary" data-dlss-task type="button">打开 DLSS 任务</button></div>';
  if(!task || !['generation','glow'].includes(task.kind)) return '';
  const running = !aiTaskIsTerminal(task);
  const pending = taskPendingTransfer(task);
  // ⭐⭐ 2026-10-05（docs/143 §五）：任务级「小眼睛」—— 整个任务共用一个开关，
  //   管的是【这一批所有图显示哪一版】：校色版（默认）↔ 底版（掰正了没校色）。
  //
  //   ⚠⚠ 用户拍板：小眼睛是【任务级】的（"整个任务卡一个"），
  //     但存储上仍然是【每张图各存一份 base】—— 这两件事不矛盾：
  //     就像一个总闸控制全屋灯，但每个房间都要有灯泡。
  //   ⚠ 为什么放在 t-acts 这一行、而且【不看 running/pending】：
  //     这一行以前只在"没跑完 / 还有图没传回"时出现，跑完传完就整行收掉。
  //     而切版本恰恰是【跑完之后】才做的事 —— 跟着那两个条件走等于永远看不见它。
  //   ⚠ 老任务（没有 base_N.png）→ 置灰 + 点了弹"缺少文件"，不做迁移（用户拍板）。
  // ⭐⭐ 2026-10-08（docs/170 §4.4 / §4.3 不变量 6、10）：四态版本。
  //   ⚠ 原来这里是 taskColorVersion(task) —— 那个只认 'base'/其余两态，
  //     四态之后必须用 shotCurrentVersion（会把 'colormatched' 归一成自动方式那种）。
  const liveShot = (task.shots||[]).find(s=>s&&s.done) || (task.shots||[])[0] || null;
  const version = shotCurrentVersion(task, liveShot);
  const versionLabel = COLOR_VERSION_LABEL[version] || version;
  const hasBase = taskHasAnyBase(task);
  // 不变量 10：被覆盖过的老单子如实说，别把它叫做"混合"。
  const versionNote = colorVersionNote(task, liveShot);
  const eyeTitle = !hasBase
    ? '这一单缓存里没有底版（老任务或者档 1 算的）—— 缺文件，没法切'
    : (versionNote ? (versionNote + ' —— 点一下选看哪一版')
       : ('现在显示【' + versionLabel + '】—— 点一下选看哪一版（底版 / 全局 / 精准 / 混合，没算过的选了才算）'))
    ;
  // ⚠⚠ 这里【不能加 disabled 属性】：用户拍板"没有底版的老任务，点了要弹窗明说缺少文件"。
  //   被 disabled 的按钮【根本不触发 click】，那条弹窗永远走不到 ——
  //   用户只会看到一个点不动的按钮，以为软件坏了（正好是用户要避免的那种体验）。
  //   ⇒ 视觉上压淡用 .off 类表达，行为上让 click 走进去、由 toggleTaskColorVersion 弹说明。
  // ⚠ 按钮上只放 4 个字的版本名：卡面格子窄（docs/170 §4.8 同样的约束）。
  // ⚠ 用 if/else 而不是三元 —— 三元的分支里【不能夹注释】（注释不产生值，冒号会悬空）。
  let eye = '';
  if(task.kind==='generation'){
    // ⚠ 老任务没底版时：视觉上压淡用 .off，但【不加 disabled】——
    //   被 disabled 的按钮根本不触发 click，那条"缺少文件"的弹窗就永远走不到。
    // ⭐ 2026-10-19（docs/251 第 7 条）：.on 改成「显示的不是生成时那一版」才亮。
    //   以前默认校色，「看底版」就是切走了；默认不校色以后底版就是生成时那张，照老规则每张卡都会亮，意思反了。
    const eyeCls = 't-act t-eye' + (version!==shotAutoVersion(task, liveShot)?' on':'') + (hasBase?'':' off') + (task._colorSwitch?' busy':'');
    // ⚠ 被覆盖的老单子（不变量 10）：按钮上加一个 "?" 记号，
    //   让用户不用悬停也知道有情况。
    const mark = versionNote ? ' ?' : '';
    // ⭐ 2026-10-19（docs/251 第 7 条④）：正在切 / 现算时显示「全局 2/6」（进度记在 task._colorSwitch，重画也不会冲掉）
    const sw = task._colorSwitch;
    const eyeText = sw ? ((COLOR_VERSION_LABEL[sw.version]||sw.version) + ' ' + sw.done + '/' + sw.total) : (versionLabel + mark);
    eye = '<button class="' + eyeCls + '" data-task-eye type="button" aria-haspopup="menu"'
        + ' title="' + escapeHtml(eyeTitle) + '">'
        + escapeHtml(eyeText) + '</button>';
  }
  const rerun = taskRerunEligible(task);
  // ⭐ 10-25（用户定）：「传回」右边加「分割」—— 抠出 AI 新加的东西，带蒙版传回（segment-panel.js，docs/289）。有出好的图就一直在
  const seg = task.kind==='generation' && !!(window.V7SegmentPanel && V7SegmentPanel.eligible(task));
  if(!running && !pending && !eye && !rerun && !seg) return '';
  let h='<div class="t-acts">';
  if(running && task.kind==='generation'){
    h+='<button class="t-act" data-task-finish type="button"'
      +' title="把已经出好的图先传回 Photoshop，剩下的继续在后台算，算完了这里会出现「传回」按钮">提前结束</button>';
  }
  if(pending){
    h+='<button class="t-act primary" data-task-send type="button"'
      +' title="把已经出好、还没传回的图贴进 Photoshop">传回 '+pending+'</button>';
  }
  if(seg){
    h+='<button class="t-act" data-task-segment type="button"'
      +' title="只抠出 AI 新加的东西：调好后回传，图层照常贴、外加一个蒙版（已经传回过的就给那个图层换上蒙版）">分割</button>';
  }
  if(rerun){
    h+='<button class="t-act primary" data-task-rerun type="button"'
      +' title="用这单原来的提示词、原图和区域原样再算一次（不用重新框选）；新任务会顶掉这张卡，失败记录在「记录与恢复」里还留着">重跑</button>';
  }
  h+=eye;
  return h+'</div>';
}

// ── ⭐⭐ 版本切换（docs/143 §五）─────────────────────────────
// 现在显示哪一版。默认校色版。存在 task 上（不是 shot 上）—— 用户拍板"整个任务卡一个"。
function taskColorVersion(task){
  return (task && task.colorVersion==='base') ? 'base' : 'colormatched';
}
// 这一单有没有【任何一张】底版。⚠ "任何一张"是对的口径：
//   整个任务共用一个开关，只要有一张能切，开关就该是能点的
//   （切的时候每张各自处理：有 base 的换、没有的保持原样）。
//   ⚠ 判据用 taskColorVersionAvailable（含"磁盘上有、内存里已释放"那种）——
//     只认内存里的 id 会把"刚生成完就切"误判成"没有底版"（见 versionImgFor 的注释）。
// ⭐⭐ 2026-10-08（docs/170 §4.3 不变量 10）：这一单的校色版是不是【已经被覆盖】？
//
//  背景（实测）：切过底版的老单子里，27 张有 24 张 output_N.png 与 base_N.png 字节完全相同
//   —— 因为旧代码写 output 用的是 shot.imgId，切底版时它变成了底版。
//   （那个 bug 已在本版修掉：写 output 改用 autoImgId）
//
//  ⚠⚠ 判据只能用在【没有版本表的老任务】上：
//     新任务选了"不校色"时 output 本来就等于底版；
//     混合判据阀门全关时结果也可能与底版逐字节相同。
//     拿"字节相同"去判新任务 ⇒ 会把正常单子误标成"被覆盖过"，
//     那又是一种静默不一致。
//
//  ⚠ 文案【不能断言原因】：老任务分不清是"被覆盖过"还是"当时就没校"。
//     所以只说"两个文件完全一样"，把两种可能都写出来。
//
//  返回：'' = 不表示任何异常；否则是要显示给用户的那句话。
function colorVersionNote(task, shot){
  if(!task || !shot) return '';
  // ① 有 autoVersion（新任务）：以记录为准，不做字节比对
  if(shot.autoVersion){
    // ⭐ 2026-10-19（docs/251 第 7 条①）：默认不校色以后「自动方式就是不校色」是常态，不再挂「?」提示
    return '';
  }
  // ② 老任务：只有【确定两个文件都在磁盘上且字节相同】才提示
  //    ⚠ 这里不真去读文件（读两张 4K PNG 太贵，切一次版本卡一下）。
  //      用便宜的信号：没记过 colorImgId 又没有 versions 表 ⇒ 很可能就是被覆盖的那批。
  if(shot.versions) return '';                 // 有版本表 ⇒ 不是老数据
  if(!shot.baseImgId && !shot.baseSaved) return '';   // 没底版 ⇒ 谈不上覆盖
  if(shot.colorImgId && shot.colorImgId !== shot.baseImgId) return '';   // 两个 id 不同 ⇒ 没被覆盖
  return '这一单的校色版和底版完全一样（可能被覆盖过，也可能当时就没校）';
}
function taskHasAnyBase(task){
  return taskColorVersionAvailable(task);
}
// 切版本。三件事（docs/143 §5.2），一件都不能少：
//   ① 换 shot.imgId：colormatched → 用校色那张；base → 用底版
//   ② 作废该批的 tween 帧（否则滚强度看到的是旧版本插出来的帧 —— 静默错误）
//   ③ 清掉 shot.tweenStrength（端点变了，旧的强度百分比不再对应同一张图）
//
// ⚠⚠ 为什么要动 shot.imgId 而不是另外记一个"当前显示 id"：
//   传回（aiTransfer）、记录卡、缩略图【全都读 shot.imgId】。
//   另外记一个字段 = 这三处各要改一次、漏一处就是"传回的图和看到的不一样"
//   这种最难受的静默错误。换个字段名不如换掉那个唯一的真源。
// ⚠ 换之前先把【原来的那张】记下来（shot.colorImgId / shot.baseImgId），
//   不然切过去就切不回来了。
// 把某一版的图【拿到手】，拿不到就从磁盘拉回来。
//
// ⚠⚠ 为什么要这个（2026-10-05 我自己埋的雷，写探针时才发现）：
//   cacheSaveTask 写完 base_N.png 就把 shot.baseImgId 从内存【释放】了
//   （跟 raw 一样 —— 一批 18 张 4K 全留在内存就是几百 MB）。
//   于是【同一场会话里】生成完马上点小眼睛，内存里的 baseImgId 已经没了 →
//   taskHasAnyBase 返回 false → 按钮是灰的、点了弹"缺少文件"，
//   而磁盘上 base_1.png 明明在。用户会说"刚生成完就切不了，重启一下又能切了"。
//
//   ⇒ 换版本时按需从磁盘拉一份回来（跟 cacheRestoreOne 恢复老任务时同一套做法：
//     putFromCache 的第三个参数是【懒加载】，不点开大图就不读磁盘）。
// ⚠ 读不到就是真没有（老任务）→ 返回 ''，由调用方决定怎么提示。
// ══════════════════════════════════════════════════════════
//  ⭐⭐ 2026-10-08（docs/170 §4.3 不变量 2/5/6）：校色的【版本表】
//
//  为什么要它：用户要能在 底版 / 全局 / 精准 / 混合 之间切换对比。
//  每种版本各存各的文件；【自动方式那一种就是 output_N.png，不重复存】。
//
//  ⚠ 三个必须守住的语义（施工和测试都按这几条来）：
//   ① output_N.png = 【生成时自动方式】的结果，生成后【永不被切换改写】
//      （记录卡 / 历史 / 传回都读它。这条以前被破坏过：切底版会把底版写进去）
//   ② shot.imgId     = 【当前显示】的那张（切版本改它）
//      shot.autoImgId = 【自动方式】那张的 id（切版本绝不碰它）
//   ③ shot.versions  = 每个版本各自的图片 id，按需惰性填
//      shot.autoVersion = 生成时用的那种（跳过校色则为 'base'）
//
//  ⚠ 兼容旧值（不变量 6）：task.colorVersion 的 'colormatched' 视为 autoVersion，
//     'base' 不变。老任务没有 versions 表，按需惰性补。
// ══════════════════════════════════════════════════════════
// 四态的顺序 = 轮换顺序（不变量之外的界面约定，见 §4.4）
const COLOR_VERSIONS = ['base','global','precise','hybrid'];
// 版本的中文名（界面文案，别再各写一份）
const COLOR_VERSION_LABEL = { base:'底版', global:'全局', precise:'精准', hybrid:'混合' };
// 这个版本对应磁盘上哪个文件名。
//   ⚠ 自动方式那一种【不单独存】——它就是 output_N.png（不变量 2），
//     所以这里返回 null，由调用方回落到 output。
function colorVersionFile(version, index, autoVersion){
  const n = index + 1;
  // ⚠ 先认「自动方式那一种」：2026-10-19（docs/251 第 7 条③）默认不校色以后，自动方式常常【就是底版】——
  //   那时底版就是 output_N.png，不另存 base_N.png（两份一模一样白占地方）。
  if(version === autoVersion) return 'output_' + n + '.png';
  if(version === 'base') return 'base_' + n + '.png';
  return null;   // 非自动方式的校色版本：文件名见 colorVersionExtraFile
}
// 非自动方式那些版本的文件名（按需算出来才会存）
function colorVersionExtraFile(version, index){
  return 'color_' + version + '_' + (index + 1) + '.png';
}
// 这一张的自动方式是哪种。⚠ 老任务没有 autoVersion 字段 ⇒ 回落到 'hybrid'
//   （10-05 起主链路只有混合；旧存档里没这个字段的，实际也是混合算的）。
function shotAutoVersion(task, shot){
  const v = shot && shot.autoVersion;
  if(v && COLOR_VERSIONS.indexOf(v) >= 0) return v;
  return 'hybrid';
}
// 当前显示的是哪一种版本。
//   ⚠ 兼容旧值（不变量 6）：'base' → base；其余（含 'colormatched' / undefined）→ 自动方式那种。
function shotCurrentVersion(task, shot){
  if(task && task.colorVersion === 'base') return 'base';
  const v = task && task.colorVersion;
  if(v && v !== 'colormatched' && COLOR_VERSIONS.indexOf(v) >= 0) return v;
  return shotAutoVersion(task, shot);
}
async function versionImgFor(task, shot, which){
  if(!task || !shot) return '';
  // ⭐⭐ 2026-10-17 夜重写（用户：「在任务卡片里面点击切换校色之后，预览图没有实时的变化，传回的内容好像有时候也不会出现变化」）。
  //   老版本两个坑，都是静默的：
  //   ① 只有两个「抽屉」：底版 baseImgId、校色版 colorImgId。要全局 / 精准时也先翻 colorImgId ——
  //      那里放的是【生成时自动用的那一种】（一般是混合）⇒ 切到全局 / 精准拿到的其实是混合：图不变、传回也是混合，
  //      真正去算全局 / 精准的那一步永远不会走到。
  //   ② 从磁盘拿某一版时，缩略图直接借【当前那张】的、原图只记「怎么读」不先确认文件在不在 ⇒
  //      切了版本小图和大预览都不变；文件根本没有（还没算过）也算「切成功」，看大图 / 传回时才读不到。
  //   现在：每一版各认各的 —— 版本表里有就用；老抽屉只认【底版】和【自动那一种】；
  //   从磁盘拿之前先把原图读出来（读不到 = 这一版还没有 ⇒ 返回 ''，调用方去现算），顺手用它现做真缩略图。
  const want = which==='color' ? shotAutoVersion(task, shot) : which;
  const autoV = shotAutoVersion(task, shot);
  const remember = id => { if(!shot.versions) shot.versions = {}; shot.versions[want] = id; return id; };
  if(shot.versions && shot.versions[want] && window.IMG.has(shot.versions[want])) return shot.versions[want];
  // 老数据（没有版本表）：底版 → baseImgId；自动那一种 → autoImgId / colorImgId。别的版本不许借这两个抽屉。
  // ⭐ 2026-10-19：自动那一种是底版（默认不校色）时，底版就是成品那张（autoImgId），不在 baseImgId 抽屉里
  const legacy = want===autoV ? (shot.autoImgId || shot.colorImgId || (want==='base' ? shot.baseImgId : '')) : (want==='base' ? shot.baseImgId : '');
  if(legacy && window.IMG.has(legacy)) return remember(legacy);
  // 磁盘里找：base → base_N.png ／ 自动那一种 → output_N.png ／ 其余 → color_<版本>_N.png
  const project = task.cacheProject, runId = task.cacheRunId;
  if(!project || !runId || !window.uiwin || !window.uiwin.cache) return '';
  const idx = (task.shots||[]).indexOf(shot);
  if(idx < 0) return '';
  const name = colorVersionFile(want, idx, autoV) || colorVersionExtraFile(want, idx);
  let bytes = null;
  try{ bytes = await window.uiwin.cache.readFile(project, runId, name); }catch(_){ bytes = null; }
  if(!bytes || !bytes.length) return '';   // 磁盘上没有这一版（还没算过）⇒ 调用方去现算，不装作有
  const full = (bytes instanceof Uint8Array) ? bytes : new Uint8Array(bytes);
  // 用这一版自己的原图现做缩略图（只解码一次，原图不留在内存里）；万一做不出来，才退回借 thumb_N.jpg（只对自动那一种才对得上）
  let thumbBytes = null;
  try{ if(window.IMG.thumbFromBytes) thumbBytes = await window.IMG.thumbFromBytes(full, 'image/png'); }catch(_){ thumbBytes = null; }
  if((!thumbBytes || !thumbBytes.length) && want===autoV){
    try{ const b = await window.uiwin.cache.readFile(project, runId, 'thumb_'+(idx+1)+'.jpg'); if(b && b.length) thumbBytes = (b instanceof Uint8Array) ? b : new Uint8Array(b); }catch(_){}
  }
  if(!thumbBytes || !thumbBytes.length) return '';   // 一张对得上的缩略图都没有 ⇒ 宁可不切，也不给错图
  try{
    const id = window.IMG.putFromCache(thumbBytes, 'image/png', function(){ return window.uiwin.cache.readFile(project, runId, name); });
    // ⚠ 自动那一种是底版时，读回来的是 output_N.png ⇒ 记进 colorImgId（自动那一格），【不】记进 baseImgId ——
    //   记进 baseImgId 的话 cacheSaveTask 会把它当底版另写一份 base_N.png、写完还把它释放掉（正在显示的图就没了）
    if(want==='base' && autoV!=='base') shot.baseImgId = id;
    else if(want===autoV) shot.colorImgId = id;
    return remember(id);
  }catch(_){ return ''; }
}
// 这一单某一版【磁盘上到底有没有】—— 不读内容，只看元数据和已登记的 id。
// ⚠ 为什么不直接 readFile 试探：那是同步 I/O，切版本时逐张探会很卡。
//   有 id（内存或磁盘拉回的）就算有；老任务两个都没有 → 没有。
function taskColorVersionAvailable(task){
  const shots=(task&&task.shots)||[];
  for(const s of shots){
    if(!s || !s.done) continue;
    if((s.baseImgId && window.IMG.has(s.baseImgId)) || (s.baseSaved && task.cacheProject && task.cacheRunId)) return true;
    // ⭐ 2026-10-19（docs/251 第 7 条③）：自动方式就是底版（默认不校色）⇒ 成品就是底版，有成品就有底版
    if(s.autoVersion==='base' && ((s.autoImgId && window.IMG.has(s.autoImgId)) || (s.imgId && window.IMG.has(s.imgId)) || (task.cacheProject && task.cacheRunId))) return true;
  }
  return false;
}
// ══════════════════════════════════════════════════════════
//  ⭐⭐⭐ 2026-10-08（docs/170 §4.4 / §4.6 第 2 步）：按需重算一个版本
//
//  什么时候用：用户切到一个【还没算过】的校色方式（比如一直用混合，
//    今天想看看全局）—— 这时磁盘上没有 color_global_N.png，要现算。
//
//  ⚠ 三条铁律（写错了就是静默错误）：
//    ① 输入必须是【底版】（对齐后、校色前），不是 output。
//       拿 output 当输入 = 在已经校过色的图上再校一遍（二次校色，颜色会跑偏）。
//    ② 算出来的是【非自动方式】的版本 ⇒ 存 color_<版本>_<n>.png，
//       【绝不覆盖 output_N.png】（docs/170 §4.3 不变量 1/8）。
//    ③ 中途切了账号 / 命名空间要安全中止（沿用 cacheSaveTask 的 assertNamespace 做法），
//       不然会写到别人的缓存目录里。
//
//  返回：新算出来的图片 id；算不了就返回 ''（调用方如实说，不装作切了）。
// ⭐⭐ 第 2 步：现算时把进度写在小眼睛按钮上（例：「全局 2/6」）。
//
//  ⚠ 为什么只改按钮文字、不重画整张卡：
//    重画会把正在算的那一批打断（按钮 DOM 被换掉、引用失效）。
//  ⚠ 找不到按钮就静默跳过：进度显示失败不该影响算图。
function setEyeProgress(taskId, version, done, total){
  const el = tasksEl && tasksEl.querySelector('.task[data-task="'+taskId+'"]');
  if(!el) return;
  const btn = el.querySelector('[data-task-eye]');
  if(!btn) return;
  const label = COLOR_VERSION_LABEL[version] || version;
  btn.textContent = label + ' ' + done + '/' + total;
  btn.classList.add('busy');
}
async function recomputeColorVersion(task, shot, version, onProgress){
  if(!task || !shot) return '';
  const idx = (task.shots||[]).indexOf(shot);
  if(idx < 0) return '';
  // ① 原图（ref）：优先内存里的 sourceImageBase64；
  //   ⭐ 2026-10-19（docs/251 第 7 条⑤）：重启恢复回来的任务内存里没有它 ⇒ 从缓存 input.png 读（sourceImgId）。
  //   原来只认内存那份，重启后一切版本就报「这一单没留下原图」—— 默认不校色以后「过后再切」会变多，这条必须通。
  let refB64 = String(task.sourceImageBase64 || '');
  if(!refB64 && task.sourceImgId && window.IMG && window.IMG.has(task.sourceImgId)){
    try{ refB64 = String(await window.IMG.base64(task.sourceImgId) || ''); }catch(_){ refB64 = ''; }
  }
  if(!refB64 || !window.MATCHENGINE){
    if(window.ERR) ERR.report('COLOR_RECOMPUTE_NO_REF',{severity:'L2',stage:'color',
      message:'这一单没留下原图，算不了别的校色方式（老任务只能看已经算过的那一种）。'});
    return '';
  }
  // ② 底版（src）：对齐后、校色前那张。
  //   ⚠ 底版可能已被 release（cacheSaveTask 写完就释放内存）⇒ 用 versionImgFor 从磁盘拉。
  const baseId = await versionImgFor(task, shot, 'base');
  if(!baseId){
    if(window.ERR) ERR.report('COLOR_BASE_MISSING',{severity:'L2',stage:'color',
      message:'这一单没有底版，算不了别的校色方式（底版只有引擎档 / 新版本生成的才有）。'});
    return '';
  }
  let baseCanvas = null;
  try{
    const bytes = new Uint8Array(await window.IMG.fullBytes(baseId));
    const blob = new Blob([bytes], {type:'image/png'});
    const bmp = await createImageBitmap(blob);
    baseCanvas = document.createElement('canvas');
    baseCanvas.width = bmp.width; baseCanvas.height = bmp.height;
    baseCanvas.getContext('2d').drawImage(bmp,0,0);
    if(bmp.close) bmp.close();
  }catch(e){
    if(window.ERR) ERR.report('COLOR_RECOMPUTE_DECODE_FAILED',{severity:'L2',stage:'color',
      message:'底版读不出来，算不了别的校色方式：'+String(e&&e.message||e)});
    return '';
  }
  // ③ 走【真实那条路】：aiColorMatchCanvas 会做尺寸对齐、比例差、引擎/档 1 分发，
  //   ⚠ 不自己另写一套 —— 两套必然漂移（这是本项目的老坑）。
  //   ⚠ 但 method 要换成【目标方式】，不能跟着设置走：settingsRuntime.colorMatchMode
  //     决定的是"生成时自动用哪种"，这里要的是"用户此刻想看哪种"。
  //   ⭐ 2026-10-17 夜：直接点名（options.mode），不再临时改全局设置再改回 ——
  //     改全局那几秒跟生成卡的下拉框、正在出的新图、存设置都会打架（用户报「是否会打架」）。
  let out = null;
  out = await aiColorMatchCanvas(baseCanvas, baseCanvas.width, baseCanvas.height, refB64,
                                 typeof colorMatchLog === 'function' ? colorMatchLog : null,
                                 { mode: version, job: { kind:'color-version', priority:0, taskId:String(task.taskId||task.id), shot:idx, label:COLOR_VERSION_LABEL[version]||version } });
  if(!out){ return ''; }
  // ④ 登记成图片 id
  let newId = '';
  try{ newId = await window.IMG.putFromCanvas(out, 'image/png'); }catch(_){ newId = ''; }
  if(!newId) return '';
  if(!shot.versions) shot.versions = {};
  shot.versions[version] = newId;
  // ⑤ 立刻落盘成 color_<版本>_<n>.png
  //   ⚠ 非自动方式【不写 output】—— output 永远是生成时自动方式的结果（不变量 1）。
  try{
    const project = task.cacheProject, runId = task.cacheRunId;
    if(project && runId && window.uiwin && window.uiwin.cache){
      const bytes = new Uint8Array(await window.IMG.fullBytes(newId));
      await window.uiwin.cache.writeFile(project, runId,
        colorVersionExtraFile(version, idx), bytes);
      shot.versionSaved = shot.versionSaved || {};
      shot.versionSaved[version] = true;
    }
  }catch(e){
    // ⚠ 写盘失败不算失败（图已经在内存里、能用），但要如实记一笔 ——
    //   不然后果是"切过去看着正常、重启后这一版没了"，用户以为软件吃了他的图。
    if(window.ERR) ERR.report('COLOR_VERSION_SAVE_FAILED',{severity:'L2',stage:'color',
      message:'新算的'+COLOR_VERSION_LABEL[version]+'版没能存进缓存（这次仍能看，重启后会没）：'
              +String(e&&e.message||e)});
  }
  if(typeof onProgress === 'function') onProgress();
  return newId;
}
async function toggleTaskColorVersion(taskId){
  const task=taskById(taskId);
  if(!task) return;
  // ⭐⭐ 2026-10-08（docs/170 §4.4）：四态轮换 底版 → 全局 → 精准 → 混合 → 底版。
  //   ⚠ 顺序固定，不许按"可用性"重排 —— 用户要的是"每点一下换一种"，
  //     顺序会记在肌肉记忆里。不可用的自动跳过（下面那个循环）。
  //   ⚠ 兼容旧值：'colormatched' 先归一成"自动方式那种"（不变量 6）。
  const fromVersion = shotCurrentVersion(task, (task.shots||[]).find(s=>s&&s.done) || (task.shots||[])[0]);
  const startIdx = Math.max(0, COLOR_VERSIONS.indexOf(fromVersion));
  // ⚠ 先只做"能切到已有版本"；拿不到的那些当"不可用"跳过。
  //   "按需重算"在施工第 2 步 —— 这里绝不能卡在拿不到的那一种上出不来。
  let to = fromVersion;
  for(let step=1; step<=COLOR_VERSIONS.length; step++){
    const cand = COLOR_VERSIONS[(startIdx+step) % COLOR_VERSIONS.length];
    if(cand === fromVersion) continue;                 // 绕回自己了，别再试
    if(cand === 'base'){ if(taskHasAnyBase(task)){ to = cand; break; } continue; }
    // 校色版本：
    //   ① 先看有没有（内存 / 磁盘都算）—— versionImgFor 自己会查两处
    //   ② 没有就【现算】（docs/170 §4.4：第一次切到没算过的版本要能出来）
    //   ⚠ 算得出来才算「可用」；算不出来就跳过这一种（不装作切了）
    const probe = (task.shots||[]).find(s=>s&&s.done);
    if(probe && await versionImgFor(task, probe, cand)){ to = cand; break; }
    if(probe && await recomputeColorVersion(task, probe, cand)){ to = cand; break; }
  }
  if(to === fromVersion){
    // 一个都切不了：如实说，别装作切了（静默失效是本项目最忌的形态）。
    if(window.ERR) ERR.report('COLOR_VERSION_UNAVAILABLE',{severity:'L2',stage:'color',
      message:'这一单目前只有【'+COLOR_VERSION_LABEL[fromVersion]+'】可看；其它版本还没算（要用加速引擎算，或等按需重算做好）。'});
    return;
  }
  if(to==='base' && !taskHasAnyBase(task)){
    // ⚠ 用户拍板：老任务不做迁移，点了【明说缺少文件】。
    //   不说的话用户只会看到按钮点不动 / 图没变，以为软件坏了。
    if(window.ERR) ERR.report('COLOR_BASE_MISSING',{severity:'L2',stage:'color',
      message:'这一单没有底版文件（老任务，或者档 1 算的图——底版只有引擎档才有）。'});
    return;
  }
  return applyTaskColorVersion(task, to, fromVersion);
}
// ⭐ 2026-10-19（docs/251 第 7 条④，测试用户：「点一下下拉弹窗，然后去选择之后开始算，节省切换时间」）：
//   小眼睛改成菜单（openColorVersionMenu），选哪版切哪版；老的「按顺序换下一种」（上面 toggleTaskColorVersion）也走这一段。
//   ⚠ 改选就停（用户 10-19 定「停掉没算完的、算好的留着、改算新选的」）：每次切换领一个号（task._colorSwitchSeq），
//     用户中途又选了别的 ⇒ 这一轮在下一张之前停下；正在算的那一张算完照样存进 shot.versions（算好的留着），
//     只是不再把它换上显示 —— 显示交给新的那一轮。
async function switchTaskColorVersion(taskId, to){
  const task=taskById(taskId);
  if(!task || COLOR_VERSIONS.indexOf(to)<0) return false;
  const fromVersion = shotCurrentVersion(task, (task.shots||[]).find(s=>s&&s.done) || (task.shots||[])[0]);
  // 正在看的就是这一版、也没有别的在算 ⇒ 什么都不做（有别的在算时选回当前这版 = 取消那一轮）
  if(to===fromVersion && !task._colorSwitch) return true;
  if(to==='base' && !taskHasAnyBase(task)){
    if(window.ERR) ERR.report('COLOR_BASE_MISSING',{severity:'L2',stage:'color',
      message:'这一单没有底版文件（老任务，或者档 1 算的图——底版只有引擎档才有）。'});
    return false;
  }
  return applyTaskColorVersion(task, to, fromVersion);
}
// ⭐ 2026-10-19（docs/251 第 7 条④）：小眼睛的菜单 —— 四项「底版（不校色）/ 全局 / 精准 / 混合」，每项后面标状态。
//   ⚠ 新的全窗口浮层（挂在 body 上）必须在 overUI 登记，不然鼠标一过去就穿透给 PS（项目里栽过四次）：见 overUI 里 colorMenuHit。
//   ⚠ 样子沿用下拉框的 .uisel-panel / .uisel-item（跟着主题色走），不另起一套。
let colorMenu=null;
function colorMenuClose(){
  if(!colorMenu) return;
  const m=colorMenu; colorMenu=null;
  m.panel.remove();
  document.removeEventListener('mousedown', m.onOutside, true);
  document.removeEventListener('keydown', m.onKey, true);
  window.removeEventListener('resize', colorMenuClose);
  window.removeEventListener('wheel', m.onWheel, true);
}
function colorMenuHit(x, y){
  if(!colorMenu || !colorMenu.panel.isConnected) return false;
  const r=colorMenu.panel.getBoundingClientRect();
  return x>=r.left-4 && x<=r.right+4 && y>=r.top-4 && y<=r.bottom+4;
}
// 这一版现在有没有（不用现算）—— 只看第一张，够菜单上写个状态
function colorVersionReady(task, version){
  const s=(task.shots||[]).find(x=>x&&x.done);
  if(!s) return false;
  if(version===shotAutoVersion(task, s)) return true;
  if(version==='base') return taskHasAnyBase(task);
  if(s.versions && s.versions[version] && window.IMG.has(s.versions[version])) return true;
  return !!(s.versionSaved && s.versionSaved[version]);
}
function openColorVersionMenu(taskId, anchor){
  const task=taskList.find(t=>t.id===taskId);
  if(!task || !anchor) return;
  if(colorMenu && colorMenu.taskId===taskId){ colorMenuClose(); return; }   // 再点一下小眼睛 = 收起
  colorMenuClose();
  const names={base:'底版（不校色）', global:'全局校色', precise:'精准校色', hybrid:'混合校色'};
  const first=(task.shots||[]).find(s=>s&&s.done)||(task.shots||[])[0];
  const current=shotCurrentVersion(task, first), sw=task._colorSwitch;
  const panel=document.createElement('div');
  panel.className='uisel-panel color-menu'; panel.setAttribute('role','menu'); panel.setAttribute('aria-label','选看哪一版');
  panel.innerHTML=COLOR_VERSIONS.map(v=>{
    const on = sw ? sw.version===v : v===current;
    const state = sw&&sw.version===v ? ('正在算 '+sw.done+'/'+sw.total) : (!sw&&v===current ? '正在看' : (colorVersionReady(task, v) ? '已算好' : '选了再算'));
    return '<button type="button" role="menuitemradio" aria-checked="'+on+'" class="uisel-item cm-row'+(on?' cur':'')+'" data-color-version="'+v+'">'
      +'<span class="cm-name">'+escapeHtml(names[v]||v)+'</span><span class="cm-state">'+escapeHtml(state)+'</span></button>';
  }).join('');
  document.body.appendChild(panel);
  // 贴在小眼睛下面；下面放不下就往上
  const r=anchor.getBoundingClientRect(), w=panel.offsetWidth, h=panel.offsetHeight;
  const below=r.bottom+6+h<=innerHeight-8;
  panel.style.left=Math.max(8, Math.min(innerWidth-w-8, r.left))+'px';
  panel.style.top=(below ? r.bottom+6 : Math.max(8, r.top-6-h))+'px';
  if(!below) panel.classList.add('up');
  const onOutside=e=>{ if(panel.contains(e.target) || anchor.contains(e.target)) return; colorMenuClose(); };
  const onKey=e=>{ if(e.key==='Escape'){ e.preventDefault(); e.stopPropagation(); colorMenuClose(); } };
  const onWheel=e=>{ if(!panel.contains(e.target)) colorMenuClose(); };     // 滚轮翻任务卡时菜单别留在原地
  panel.addEventListener('mousedown', e=>e.stopPropagation());
  panel.addEventListener('click', e=>{
    const b=e.target.closest('[data-color-version]'); if(!b) return;
    e.preventDefault(); e.stopPropagation();
    const v=b.dataset.colorVersion;
    colorMenuClose();
    switchTaskColorVersion(taskId, v);
  });
  document.addEventListener('mousedown', onOutside, true);
  document.addEventListener('keydown', onKey, true);
  window.addEventListener('resize', colorMenuClose);
  window.addEventListener('wheel', onWheel, {capture:true, passive:true});
  colorMenu={panel, taskId, anchor, onOutside, onKey, onWheel};
}
async function applyTaskColorVersion(task, to, fromVersion){
  const token = (task._colorSwitchSeq = (task._colorSwitchSeq||0) + 1);
  const live = () => task._colorSwitchSeq === token;
  const taskId = task.id;
  let swapped=0, skipped=0;
  // ⭐ 第 2 步：现算时的进度用（按钮上显示「全局 2/6」）
  let done = 0, processed = 0;
  const total = (task.shots||[]).filter(s=>s&&s.done).length;
  const fromV = fromVersion;
  // 进度记在任务上（taskActionsHtml 画小眼睛时也认它 —— 别的进度事件把操作行重画了，进度也不会被冲掉）
  task._colorSwitch = {version:to, done:0, total};
  try{ setEyeProgress(taskId, to, 0, total); }catch(_){}
  // ⚠ 逐张 await（versionImgFor 要读磁盘、用那一版的原图现做缩略图，一张零点几秒）。
  //   ⭐ 2026-10-17 夜：每张都在按钮上报进度（以前只有现算时报 —— 读盘做缩略图那一两秒按钮像卡住了）。
  for(const s of (task.shots||[])){
    if(!live()) return false;                     // 改选了：停在这一张之前
    if(!s || !s.done) continue;
    // ⭐ 切走之前把【当前这张】登记进它自己那一版（切回来不用再读盘）
    if(s.imgId && window.IMG.has(s.imgId)){ if(!s.versions) s.versions = {}; if(!s.versions[fromV]) s.versions[fromV] = s.imgId; }
    // ⭐ 按【版本名】取（versionImgFor 已泛化）
    //   ⚠ 它内部会惰性登记进 shot.versions，所以第二次切同一版就不用再查磁盘。
    let want = await versionImgFor(task, s, to);
    if(!want && live()){
      // ⭐ 第 2 步：没算过就现算（docs/170 §4.4）
      //   ⚠ 逐张算、算完一张换一张 —— 界面不能卡死。
      want = await recomputeColorVersion(task, s, to, function(){
        done++;
      });
    }
    // 改选了：这张算好的已经进了 shot.versions（留着），但不换上显示 —— 显示交给新的那一轮
    if(!live()) return false;
    // 第一张就拿不到（没原图 / 没底版 / 算失败，原因已经报过一次）⇒ 整轮作罢，别每张都再报一遍、也别切成半截
    if(!want && !swapped && !skipped){
      task._colorSwitch = null;
      const host=tasksEl.querySelector('.task[data-task="'+taskId+'"]');
      if(host){ host._actsSig=''; syncTaskActions(host, task); }
      return false;
    }
    processed++;
    task._colorSwitch.done = processed;
    try{ setEyeProgress(taskId, to, processed, total); }catch(_){}
    if(want){
      // ⚠ 去的时候先把【现在这张】记下来，回来才有据可依。
      //   colorImgId 只在第一次切走时记 —— 反复切不能把它覆盖成底版那张。
      // ⭐⭐ 2026-10-08（docs/170 §4.3 不变量 8）：
      //   切之前先把 autoImgId 定下来 —— 此处最清楚"切之前 imgId 是什么"。
      //   ⚠ 只在为空时补，【绝不能覆盖已有的】—— 已有值才是真正的生成时自动方式。
      //   ⚠ 老任务没有这个字段：那张的 imgId 此刻还是自动方式那张（还没被切过），
      //     所以此刻补上是对的；补晚了（等切完再补）就会把底版钉成"自动方式"。
      if(!s.autoImgId) s.autoImgId=s.imgId;
      // ⭐ 2026-10-17 夜：「校色版」抽屉只放【自动那一种】—— 当前是全局 / 精准时切去底版，不能把它们当成自动那张记下
      if(to==='base' && !s.colorImgId && fromV===shotAutoVersion(task, s)) s.colorImgId=s.imgId;
      s.imgId=want; swapped++;
    } else skipped++;
  }
  if(!live()) return false;
  task._colorSwitch = null;
  // ⭐ 记当前版本（不变量 6：'base' 保持 'base'，其余记版本名）
  //   ⚠ 旧代码把非 base 一律记成 'colormatched' —— 那分不清是全局还是混合，
  //     四态之后就丢了信息。新代码记真名；读了旧值的走 shotCurrentVersion 归一。
  task.colorVersion = to;
  // ⚠ outputs 也要跟着换 —— 它是"能不能传回 / 传回哪张"的真源之一（见 aiTransfer）。
  //   不换的话切到底版之后点传回，传出去的是校色版（用户看到的是底版）→ 静默不一致。
  (task.outputs||[]).forEach(o=>{
    if(!o) return;
    const s=(task.shots||[])[o.index];
    if(s && s.imgId) o.imgId=s.imgId;
  });
  // ⭐⭐ 2026-10-06 审查补：作废这一批的过渡帧。
  //   ⚠⚠ 上面 toggleTaskColorVersion 的函数头注释（§4841-4842）早就写着切版本要
  //     "② 作废该批的 tween 帧（否则滚强度看到的是旧版本插出来的帧 —— 静默错误）
  //      ③ 清掉 shot.tweenStrength（端点变了，旧的强度百分比不再对应同一张图）"，
  //     **但这两件事在代码里一件都没做** —— V7Tween.purgeTaskFrames 写好了、导出了、
  //     从来没人调（全 ui-pure 搜不到调用点）。
  //   后果两条：① 滚强度看到的是拿【另一个版本】的两个端点插出来的帧；
  //             ② 缓存里 tween_*.png 只增不减（实测 18.84 GB / 3168 个文件）。
  //   ⇒ 切版本时整批作废：内存表清掉 + 磁盘那份标记 json 覆盖成空（读盘有 key 校验兜底）。
  //     ⚠ 不 await —— 它是后台清理，不该让"切个版本"等磁盘写。
  try{
    if(window.V7Tween && typeof V7Tween.purgeTaskFrames==='function') V7Tween.purgeTaskFrames(task);
  }catch(_){}
  // ③ 清掉强度：端点换了，旧的百分比不再对应同一张图（否则滚轮一上去就是错的那张）
  (task.shots||[]).forEach(s=>{ if(s && s.tweenStrength!=null) s.tweenStrength=null; });
  // 缩略图 / 大预览 / 预览条一起重画
  const el=tasksEl.querySelector('.task[data-task="'+task.id+'"]');
  if(el){ el._actsSig=''; syncTaskActions(el, task); buildPreview(el, task); }
  // ⭐ 2026-10-17 夜：大预览框正开着这一单 → 马上按新版本换图（以前要等鼠标再动一下）
  try{ if(window.V7Tween && typeof window.V7Tween.refreshBox==='function') window.V7Tween.refreshBox(task); }catch(_){}
  aiAddLog(to==='base'
    ? ('已切到【底版】：'+swapped+' 张（没校色，掰正过的样子）'+(skipped?(' · '+skipped+' 张没有底版，保持原样'):''))
    : ('已切到【'+(COLOR_VERSION_LABEL[to]||to)+'】校色版：'+swapped+' 张'+(skipped?(' · '+skipped+' 张没切过来'):'')),'info');
  // 记录卡 / 历史那边也刷一次（它们显示的是同一批图）
  try{ if(typeof broadcastRecordsChanged==='function') broadcastRecordsChanged(); }catch(_){}
}

// ⭐⭐ 2026-09-13 新增：让操作行【跟着状态重画】。
//
// ⚠⚠ 这是用户实测的"传回按钮数字不变 / 传完了按钮还在 / 一直能再点一次"的真因：
//   这一行以前只在 renderTaskEl(建卡那一刻) 画过一次，之后 updateTask 只更新
//   图标/名字/百分比/进度条/状态文字，【从来不管这一行】。所以
//     · 任务刚建时 pending=0 → 根本没有「传回」按钮，后面出了图也不会长出来
//     · 传完了 pending 变 0 → 按钮也不会消失，用户再点一次就重复传
//     · 跑完了 → 「提前结束」赖着不走
//
// ⚠ 只有内容【真的变了】才动 DOM（拿 HTML 当签名比一下）——
//   updateTask 每来一个进度事件就调一次，无条件重建会让悬停高亮一直闪。
// ⚠ 事件绑定只在这里做，不要再在 buildPreview 里绑一遍：
//   重建出来的是新元素，两边都绑就是绑两次 → 点一下发两次传回。
// ⚠ 新加子元素记得看 CSS 那行 `.task > .t-sub,.task > .t-acts{z-index:3}` ——
//   不在里面就会被光裁切层(z2)盖住（"看得见位置但看不到、鼠标却能点中"那个坑）。
function syncTaskActions(el, task){
  if(!el || !task) return;
  const html=taskActionsHtml(task);
  if(el._actsSig===html) return;            // 没变化，一个字节都不动
  el._actsSig=html;
  const old=el.querySelector(':scope > .t-acts');
  if(!html){ if(old) old.remove(); return; }
  const box=document.createElement('div');
  box.innerHTML=html;
  const next=box.firstElementChild;
  if(!next) return;
  if(old) old.replaceWith(next);
  else {
    // 位置：状态文字下面。进度条是绝对定位钉在下沿的，插在它前面不影响外观。
    const sub=el.querySelector(':scope > .t-sub'), bar=el.querySelector(':scope > .t-bar');
    if(sub) sub.insertAdjacentElement('afterend',next);
    else if(bar) el.insertBefore(next,bar);
    else el.appendChild(next);
  }
  // ⚠ stopPropagation 必须有：按钮坐在任务卡里，不拦会连带触发任务卡自己的点击和拖拽。
  const finishBtn=next.querySelector('[data-task-finish]');
  const dlssBtn=next.querySelector('[data-dlss-task]');
  if(dlssBtn){dlssBtn.addEventListener('mousedown',e=>e.stopPropagation());dlssBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();V7DLSS.openTask(task);});}
  if(finishBtn){
    finishBtn.addEventListener('mousedown',e=>e.stopPropagation());
    finishBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();aiFinishEarly(task);});
  }
  const sendBtn=next.querySelector('[data-task-send]');
  if(sendBtn){
    sendBtn.addEventListener('mousedown',e=>e.stopPropagation());
    sendBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();aiTransfer(task);});
  }
  // ⭐ 10-25：分割（按 id 取最新那份）
  const segBtn=next.querySelector('[data-task-segment]');
  if(segBtn){
    segBtn.addEventListener('mousedown',e=>e.stopPropagation());
    segBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();taskOpenSegment(taskList.find(t=>t.id===task.id)||task,el);});
  }
  // ⭐ 2026-10-19（docs/250 第 20 条）：失败任务「重跑」。按 id 取最新那份（闭包里的 task 是这次渲染时的快照）。
  const rerunBtn=next.querySelector('[data-task-rerun]');
  if(rerunBtn){
    rerunBtn.addEventListener('mousedown',e=>e.stopPropagation());
    rerunBtn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();aiRerunFailedTask(taskList.find(t=>t.id===task.id)||task);});
  }
  // ⭐⭐ 2026-10-05（docs/143 §五）：小眼睛切版本。
  //   ⚠ 用 taskById 取最新那份 —— 闭包里的 task 是这次渲染时的快照，
  //     而切换会改 imgId / tweenStrength，拿旧快照切会丢一半改动。
  // ⭐ 2026-10-19（docs/251 第 7 条④）：点小眼睛弹菜单选版本（openColorVersionMenu），不再按顺序换下一种。
  const eyeBtn=next.querySelector('[data-task-eye]');
  if(eyeBtn){
    eyeBtn.addEventListener('mousedown',e=>e.stopPropagation());
    eyeBtn.addEventListener('click',e=>{
      e.preventDefault(); e.stopPropagation();
      openColorVersionMenu(task.id, eyeBtn);
    });
  }
}

// ⭐ 10-25：「分割」框的宿主（segment-panel.js 只管界面和算蒙版，传回 / 换蒙版在这边做）。
//   · 这张还没传过 → aiTransfer 照常传，额外带上这张的蒙版（插件那边这一张不加边缘羽化 —— 用户说「羽化要避让」）
//   · 已经传过（psLayerByShot 里有图层号）→ ps.layer.applyMask 给那个图层换上这个蒙版（原来的羽化蒙版被替换掉）
function segmentHost(){
  return {
    loadBlob:imgId=>Promise.resolve(window.IMG.fullBytes(imgId)).then(buf=>new Blob([buf])),
    // ⭐ 10-26（用户：调了强度的图，点分割要继承那个强度）：调过强度就用调好的那一帧（跟「传回」用的是同一个 frameBytesFor），没调过 / 100% 用原图
    loadGen:(task,idx)=>{
      const shot=task.shots[idx],T=window.V7Tween;
      const strength=T&&T.currentStrength?Number(T.currentStrength(task,shot)):1;
      const frame=T&&typeof T.frameBytesFor==='function'?T.frameBytesFor(task,shot.imgId):null;
      return Promise.resolve(frame).then(bytes=>bytes?{blob:new Blob([bytes]),strength}:Promise.resolve(window.IMG.fullBytes(shot.imgId)).then(buf=>({blob:new Blob([buf]),strength:1})));
    },
    // 分割框骑在大预览框上：给这张图打开（或换到）大预览框，交回框元素
    attachBox:(task,taskEl,idx)=>{
      const T=window.V7Tween,shot=task.shots[idx];
      if(!T||typeof T.openShot!=='function'||!shot||!taskEl)return null;
      if(!T.openShot(taskEl,task,shot))return null;
      if(T.cancelPendingHide)T.cancelPendingHide();
      return document.querySelector('.tween-box.show');
    },
    boxShot:task=>window.V7Tween&&V7Tween.boxShotOf?V7Tween.boxShotOf(task):-1,
    keepBox:()=>{if(window.V7Tween&&V7Tween.cancelPendingHide)V7Tween.cancelPendingHide();},
    geometry:taskEl=>window.V7Tween&&V7Tween.geometryForTask?V7Tween.geometryForTask(taskEl):null,
    latestTask:task=>taskList.find(t=>t.id===task.id)||task,
    report:(code,ctx)=>{try{ERR.report(code,ctx);}catch(_){}},
    returnWithMask:(task,idx,mask)=>{
      const layerId=task&&task.psLayerByShot?task.psLayerByShot[idx]:null;
      if(layerId==null){
        return Promise.resolve(aiTransfer(task,[idx],{masks:{[idx]:mask}})).then(r=>{
          if(r&&r.ok){aiAddLog('第 '+(idx+1)+' 张已带分割蒙版传回（这张没加边缘羽化）','success');return r;}
          return {ok:false,error:(r&&r.error)||'传回没完成（看左下角报错卡）'};
        });
      }
      const c=aiCaptureSnapshot(task.captureSnapshot||task,0)||{};
      const docId=task.psDocId!=null?task.psDocId:c.docId;
      if(docId==null||!c.selection)return Promise.resolve({ok:false,error:'这单缺少 Photoshop 来源快照（文档 / 选区），没法给图层换蒙版'});
      return new Promise(resolve=>{
        linkQueue('ps.layer.applyMask',{docId,layerId,maskRle:mask.rle,maskWidth:mask.width,maskHeight:mask.height,selection:aiClonePlain(c.selection)},{
          after:()=>{aiAddLog('第 '+(idx+1)+' 张：PS 里那个图层已换上分割蒙版','success');resolve({ok:true});},
          afterError:result=>{const msg=linkResultMessage(result);try{ERR.report('ADDMASK_RETURN_FAILED',{message:msg,context:{'第几张':idx+1,'图层号':layerId}});}catch(_){}resolve({ok:false,error:msg});}
        }).then(reply=>{if(reply&&reply.ok===false)resolve({ok:false,error:reply.error||'Photoshop 没有回应'});}).catch(error=>resolve({ok:false,error:String(error&&error.message||error)}));
      });
    }
  };
}
function taskOpenSegment(task,el){
  if(!window.V7SegmentPanel){aiAddLog('分割模块没加载起来，重启软件再试','error');return;}
  V7SegmentPanel.setHost(segmentHost());
  // ⭐ 10-26（用户真机报：点开分割「预览图在、缩略图不在」）：鼠标从缩略图条移回任务卡点「分割」时，条按正常规则已经收了。
  //   分割框摆在大预览框的位置，底下应该照样有这一单的缩略图条 ⇒ 打开前主动把条弹出来（跟右滑弹条同一套：先清别的、登记归属）。
  //   分割框开着时整个窗口是工作面，鼠标移动不走收条那条路（v7HoverOverlayOpen），关掉分割框后按正常规则收。
  const pv=el&&el.querySelector('.task-preview');
  if(pv&&!pv.classList.contains('show')){
    try{ if(typeof buildPreview==='function') buildPreview(el,task); }catch(_){}
    clearPreview(); pv.classList.add('show'); window.__pv=pv;   // 不设 pvKeepOpen：关掉分割框后鼠标一离开就按正常规则收，别让条赖着
    if(window.V7Tween&&typeof V7Tween.setBoxOwner==='function') V7Tween.setBoxOwner(el.dataset.task);
  }
  // 鼠标移到「分割」按钮那一下可能已经排了「160ms 后收条」—— 取消掉，不然刚弹出的条转眼就被收（真机实测）
  if(window.V7Tween&&typeof V7Tween.cancelPendingHide==='function') V7Tween.cancelPendingHide();
  // 从哪张开：大预览框正开着这一单的某张就从那张开（V7Tween.boxShotOf），否则第一张出好的；框里有「‹ ›」能换
  const idx=window.V7Tween&&V7Tween.boxShotOf?V7Tween.boxShotOf(task):-1;
  if(!V7SegmentPanel.open(task,el,idx))aiAddLog('这单没有能分割的图（要有出好的图和原图）','warn');
}

// 哪几张"已经出好、但还没传回 PS"。这是【传回】和【提前结束】共用的唯一判据。
//
// ⚠ 判据用 psLayerByShot —— 那张对照表是【传回成功后】写的，最准。
//   不能用 task.status / task.outputs：
//     · status 到终态才变，中途传不了
//     · outputs 是整批跑完才赋值的（就是这个坑让「提前结束」点了没反应）
//   用它还天然支持【分几次传回】：传过的不会再传第二遍，不会重复贴图层。
// ═══ 指哪抠哪：三个候选挑一个（2026-09-14 深夜，用户定的交互）═══
//
// SAM2 每次推理会【同时给三个答案】（比如框住领口 → 整个人 / 上衣 / 领子），
// 各带一个置信度。用户明确要的是"三个都摆出来我自己挑"，而不是替他决定。
// 面板里那个「三个答案怎么办」可以切成"直接用最有把握的"。
//
// ⚠ 和 syncTaskActions 同一套规矩：内容没变就【一个字节都不动 DOM】——
//   updateTask 每来一个进度事件就调一次，无条件重建会让悬停高亮一直闪。
// ⚠ 事件只在这里绑，别处不许再绑一遍：重建出来是新元素，两边都绑 = 点一下跑两次。
function taskPickSig(task){
  if(!task || task.kind!=='sam2') return '';
  if(task.sam2Picked!=null) return '';                 // 已经挑过了 → 收起来
  const c=task.sam2Candidates;
  if(!Array.isArray(c) || !c.length) return '';
  return 'sam2|'+task.id+'|'+c.map(x=>x.index+':'+(x.imgId||'')+':'+(x.iou||0)).join(',');
}
function syncTaskPick(el, task){
  if(!el) return;
  const slot=el.querySelector(':scope > .t-pick');
  if(!slot) return;
  const sig=taskPickSig(task);
  if(el._pickSig===sig) return;
  el._pickSig=sig;
  if(!sig){ slot.classList.remove('on'); slot.textContent=''; return; }

  const cands=task.sam2Candidates;
  slot.textContent='';
  const tip=document.createElement('div');
  tip.className='t-pick-tip';
  tip.textContent='三个答案，点一个：';
  slot.appendChild(tip);
  const row=document.createElement('div');
  row.className='t-pick-row';
  cands.forEach(c=>{
    const b=document.createElement('button');
    b.type='button';
    b.className='t-pick-item'+(c.index===task.sam2Best?' best':'');
    // ⚠ 空候选（一个像素都没选中）也要摆出来占位、但不能点 ——
    //   删掉它会让"三个"变成两个，用户以为程序漏了一个。
    const empty=!c.imgId || !(c.pixels>0);
    if(empty) b.disabled=true;
    const im=document.createElement('img');
    im.className='t-pick-thumb';
    // ⚠ 只挂缩略图，原图绝不进 DOM（铁律 13）
    im.src=(window.IMG && c.imgId) ? window.IMG.thumb(c.imgId) : '';
    im.alt='';
    b.appendChild(im);
    const cap=document.createElement('span');
    cap.className='t-pick-cap';
    // ⚠ 不显示 "iou 0.96" 这种术语 —— 用户看不懂。换成"把握"百分比。
    cap.textContent=empty ? '（空的）' : ('把握 '+Math.round((Number(c.iou)||0)*100)+'%');
    b.appendChild(cap);
    b.title=empty ? '这个答案里什么都没有' : ('把握 '+Math.round((Number(c.iou)||0)*100)+'% · 选中约 '+(c.pixels||0).toLocaleString()+' 个像素');
    // ⚠ stopPropagation 必须有：按钮坐在任务卡里，不拦会连带触发任务卡自己的点击和拖拽。
    b.addEventListener('mousedown',e=>e.stopPropagation());
    b.addEventListener('click',e=>{
      e.preventDefault(); e.stopPropagation();
      if(empty) return;
      applySAM2Candidate(task.id, c.index);
    });
    row.appendChild(b);
  });
  slot.appendChild(row);
  slot.classList.add('on');
}

function taskTransferableOutputs(task){
  if(task?.migration?.returnBlocked)return [];
  const shots = Array.isArray(task&&task.shots) ? task.shots : [];
  const map = (task&&task.psLayerByShot) || {};
  const list=[];
  shots.forEach((s,i)=>{
    if(s && s.imgId && s.restoreState==='done' && map[i]==null)
      list.push({index:i, imgId:s.imgId, restoreState:'done'});
  });
  return list;
}
function taskPendingTransfer(task){ return taskTransferableOutputs(task).length; }

// ⭐ 任务标题的【唯一来源】（2026-09-13）。
//
// 📌 **以后接本地微型 LLM 自动起名，只改这一个函数的兜底分支。**
//    别的地方（任务卡渲染 / 缓存 meta / 生成记录）都读 task.label，不用动。
//    接进来时建议：拿 prompt 前 N 字送小模型 → 返回一个 8~12 字的名字 →
//    失败就仍然回落到"自定义提示词"，**绝不能因为起名失败挡住生成**。
function taskTitleOf(payload){
  const t=String(payload&&payload.presetTitle||'').trim();
  if(t) return t;
  return '自定义提示词';
}

function taskStatusText(task,pct){
  if(taskIsDone(task.status)) return '完成';
  if(task.status==='failed') return '失败';
  if(task.status==='cancelled') return '已取消';
  // ⭐ 转后台的要标出来（2026-09-13）：它【还在跑】，只是前台不等了。
  //   不标的话用户看到一个 40% 不动的任务会以为卡死了。
  if(task.backgrounded) return '后台 '+pct+'%';
  return pct+'%';
}

// 进度色段按任务结果计数排列：成功永远从左侧占位，失败紧随其后，未完成保持透明。
// 不使用图片原始序号，避免第 6 张先返回时在视觉上跳到最右边。
function taskProgressSegments(task){
  const states=taskProgressStates(task), total=Math.max(1,states.length);
  const success=states.filter(s=>s==='done').length, failed=states.filter(s=>s==='error').length;
  const pending=Math.max(0,total-success-failed), pct=n=>((n/total)*100).toFixed(3)+'%';
  return '<span class="t-progress-layer"><i class="t-progress-segment ok" style="width:'+pct(success)+'"><b class="t-progress-sweep"></b><em class="t-progress-tip"></em></i><i class="t-progress-segment err" style="width:'+pct(failed)+'"><b class="t-progress-sweep"></b><em class="t-progress-tip"></em></i><i class="t-progress-segment pending" style="width:'+pct(pending)+'"><b class="t-progress-live" style="width:'+taskLiveWidth(task,pending)+'"></b></i></span>';
}
// ⭐ 2026-10-21：云端排队/采样进度（task.cloudLive = 0~1）画在「还没完成」那段里，只占【下一张】那一格的宽度。
//   一张都没回来时 = 整条跟着走；回来一张后，剩下那段从头再走。
function taskLiveWidth(task,pending){
  const f=Math.max(0,Math.min(1,Number(task&&task.cloudLive)||0));
  return pending>0?((f/pending)*100).toFixed(3)+'%':'0%';
}
// ⭐ 2026-10-22：工作流采样步数（task.cloudSteps，aiCloudProgressPatch 写）—— 画在缩略图沙漏下面
function taskStepsHtml(task){
  const s=task&&task.cloudSteps;
  if(!s||!(s.max>0))return '';
  const v=Math.min(s.max,s.value);
  return '<div class="pv-steps" data-pv-steps><b>'+v+'</b>/'+s.max+' 步<i><b style="width:'+(v/s.max*100).toFixed(1)+'%"></b></i></div>';
}
function taskProgressStates(task){
  const shots=Array.isArray(task&&task.shots)&&task.shots.length ? task.shots : [
    {done:taskIsDone(task&&task.status),error:task&&task.status==='failed'}
  ];
  let success=0, failed=0;
  shots.forEach(shot=>{
    if(shot&&shot.error) failed++;
    else if(shot&&shot.done) success++;
  });
  const pending=Math.max(0,shots.length-success-failed);
  return Array.from({length:success},()=> 'done')
    .concat(Array.from({length:failed},()=> 'error'))
    .concat(Array.from({length:pending},()=> 'pending'));
}
function taskProgressSignature(task){return taskProgressStates(task).join('|');}
function renderTaskProgress(fill,task,animate){
  if(!fill||!task)return;
  let layer=fill.querySelector('.t-progress-layer');
  if(!layer){fill.innerHTML=taskProgressSegments(task);layer=fill.querySelector('.t-progress-layer');}
  const states=taskProgressStates(task),total=Math.max(1,states.length),ok=states.filter(s=>s==='done').length,err=states.filter(s=>s==='error').length,pending=Math.max(0,total-ok-err),pct=n=>((n/total)*100).toFixed(3)+'%';
  const segments={ok:layer&&layer.querySelector('.t-progress-segment.ok'),err:layer&&layer.querySelector('.t-progress-segment.err'),pending:layer&&layer.querySelector('.t-progress-segment.pending')};
  if(segments.ok)segments.ok.style.width=pct(ok);if(segments.err)segments.err.style.width=pct(err);if(segments.pending)segments.pending.style.width=pct(pending);
  const live=segments.pending&&segments.pending.querySelector('.t-progress-live');if(live)live.style.width=taskLiveWidth(task,pending);
  if(animate){
    task._progressAnimQueue=Math.min(3,(task._progressAnimQueue||0)+1);
    if(!task._progressAnimBusy){
      const play=()=>{task._progressAnimBusy=true;[segments.ok,segments.err].forEach(seg=>{if(!seg||seg.offsetWidth<=0)return;seg.classList.remove('step');void seg.offsetWidth;seg.classList.add('step');});setTimeout(()=>{[segments.ok,segments.err].forEach(seg=>{if(seg)seg.classList.remove('step');});task._progressAnimQueue=Math.max(0,(task._progressAnimQueue||0)-1);if(task._progressAnimQueue>0)play();else task._progressAnimBusy=false;},980);};
      play();
    }
  }
}

// ── 渲染单张任务卡的 DOM ──
function renderTaskEl(task){
  const el = document.createElement('div');
  el.className = 'task' + (taskIsDone(task.status) ? ' done' : '') + (task.status === 'failed' ? ' failed' : '') + (task.status === 'running' ? ' running' : '');
  el.dataset.task = task.id;
  const pct = Math.max(0, Math.min(100, Number(task.pct) || 0));
  el.innerHTML =
    '<div class="task-source-layer"></div>' +
    // ⚠ 压暗层：夹在内容(z3)之下、背景之上。叠压越深压得越黑（setTasks 里设 opacity）。
    '<div class="t-dim"></div>' +
    // ⭐⭐ 2026-09-13 重排：**标题行和进度条一起钉在卡片下沿**。
    //   叠压时下面那几张只露出最下面 STEP=34px —— 以前标题在最上面，
    //   一叠压就全被盖住，用户根本看不出下面压着哪些任务。
    //   现在这 34px 里塞的是【最该看到的两样】：标题 + 进度。
    //   ⚠ ✕ 单独绝对定位到右上角，不跟标题挤 —— 它是"移除"，不是常用动作。
    '<button class="t-close" data-task-close type="button" aria-label="从任务栏移除" title="从任务栏移除（缓存保留）">✕</button>' +
    // ⭐⭐ 底栏排版（2026-09-13 用户定案）：标题和次级信息【挤同一行】。
    //   露出带只有 34px，标题(18)+次级(12)+进度条(6)+间距 放不下三行，
    //   所以次级信息缩成小字跟在标题右边。层级靠【字号】拉开：
    //     标题 15px 粗体  >  张数·渠道·模型 10px 压淡  >  进度数字 12px
    // ⚠ 不放 emoji 图标（2026-09-13 用户要求）：它占掉约 22px，
    //   而标题（预设名）正是这一行最该占满的东西 —— 图标本身不传达任何信息。
    //   任务状态已经由右边的百分比和进度条表达了。
    '<div class="t-head">' +
    '<span class="t-name">' + escapeHtml(task.label) + '</span>' +
    (task.kind==='generation'
      ? '<span class="t-meta">'
        + escapeHtml(((task.shots&&task.shots.length)?(task.shots.length+' 张 · '):'')
          + (task.channelLabel||aiTaskChannelText(task)))
        + '</span>'
      : '') +
    '<span class="t-pct">' + taskStatusText(task,pct) + '</span>' +
    // ⚠⚠ 头部【不放操作按钮】（2026-09-13 用户指出）：
    //   卡片只有 300px 宽，头部已经有 图标+名字+百分比+✕。
    //   我一度往这儿塞了两个按钮，把名字挤得只剩几个字 —— 操作按钮统一走下面的 t-acts 行。
    // 关闭 = 只从任务栏收起，硬盘上的缓存保留(以后"生成记录"还能翻到)。
    '</div>' +
    '<div class="t-sub">' + escapeHtml(task.sub) + '</div>' +
    // ⭐ Phase F：校色引擎没开就发出的单 —— 一行非阻断提示（不挡任何操作）
    (task.noMatchEngine ? '<div class="t-engine-note" data-engine-note>校色引擎没开 · 这单不存底版（对齐用快速版）</div>' : '') +
    taskActionsHtml(task) +
    // ⭐ 指哪抠哪的「三个候选挑一个」放这儿（默认 display:none，有候选时才亮）。
    //   ⚠ 内容由 syncTaskPick() 填，不在这里拼 —— 候选图是异步登记到图片管家的，
    //     建卡那一刻还没有。
    '<div class="t-pick" data-pick="' + task.id + '"></div>' +
    // ⭐⭐ 进度条放【最后】，CSS 里绝对定位到卡片最下沿（2026-09-13 用户要求）。
    //   理由：任务卡叠压时，下面那几张只露出【最下面 STEP=34px】。
    //   进度条原来在头部下方，一叠压就被上面那张完全盖住 ——
    //   而"还有几张没跑完"恰恰是叠压状态下最该一眼看到的信息。
    '<div class="t-bar"><div class="t-fill">' + taskProgressSegments(task) + '</div></div>' +
    '<div class="task-preview" data-preview="' + task.id + '"></div>' +
    // 交互反馈光放入独立裁切层; 右侧预览仍在卡片外部自由展开。
    '<div class="task-light-clip">' +
      '<div class="task-edgehint"></div>' +
      '<div class="task-glow"></div>' +
      '<div class="task-bright"></div>' +
    '</div>';
  // 任务卡背景 = 准备计算的图(运行时喂进来的源图)。虚拟任务用 sourceImg。
  // 多层背景: 深色遮罩在前保证文字可读, 源图在后 cover。
  if (task.sourceImg){
    const safeSrc=String(task.sourceImg).replace(/["\\\r\n]/g,'');
    el.style.backgroundImage =
      'linear-gradient(180deg, hsl(var(--card-h, 220 28%) 6% / calc(.62 * var(--ui-bg-opacity,1))), hsl(var(--card-h, 220 28%) 6% / calc(.35 * var(--ui-bg-opacity,1))) 42%, hsl(var(--card-h, 220 28%) 6% / calc(.52 * var(--ui-bg-opacity,1))))';
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
    const layer=el.querySelector('.task-source-layer');
    if(layer) layer.style.backgroundImage='url("'+safeSrc+'")';
    el.classList.add('has-bg');
    // ⚠ 任务卡不在 bg-manager 的 45 张卡体系里(没有 data-bgkey), 所以 applyToCard 不会给它
    //   写 --glow-hsl → 光效只能回落默认橙。这里单独从源图提色, 让任务卡的光也跟图走。
    if (window.BG && window.BG.themeColorFromDataUrl){
      window.BG.themeColorFromDataUrl(safeSrc).then(c=>{
        if (c) el.style.setProperty('--glow-hsl', c.h + ' ' + c.s + '% ' + c.l + '%');
        else el.style.removeProperty('--glow-hsl');   // 纯灰图 → 回落默认橙
      });
      // ⚠ 2026-10-22（方案 C）：这里原来按源图上半部亮度切深字（.on-light）——
      //   字其实在卡片最下面，按上半部判经常判反；而且亮图上深字压在亮图上更糊。现在字永远是浅色 + 自带深描边，不再判亮度。
    }
  }
  return el;
}

// ── 叠压布局(与主卡同一套参数) ──
// 【防越界】任务多了往下叠压会超出窗口底被横切(锐角)。
//   限制最大可见深度 MAX_VISIBLE: 更深的卡统一压到 maxDepth, 不继续往下伸。
const MAX_VISIBLE = 4;              // 最多露出几层(当前+3)
function taskVisibleCount(els){
  if(!els.length) return 0;
  const maxH=Math.max(...els.map(t=>t.offsetHeight||150));
  const top=parseFloat(tasksEl.style.top)||(mainStackMetrics().bottomWithStack+16);
  // 先给当前任务完整卡面留空间，再把剩余高度用于露出底层标题。
  // 即使窗口很矮也保留当前任务；所有任务仍可通过滚轮轮转到顶层。
  const extra=Math.max(0,Math.floor(((window.innerHeight||920)-top-maxH-6)/STEP));
  return Math.min(els.length,MAX_VISIBLE,1+extra);
}
function setTasks(){
  refreshBrowserTaskLock();
  const els = [...tasksEl.querySelectorAll('.task:not(.leaving)')];
  const n = els.length;
  const visible = taskVisibleCount(els);
  tcur=n?((tcur%n)+n)%n:0;
  els.forEach((t, i) => {
    let d = (i - tcur + n) % n;
    const clamped = Math.min(d, visible - 1);          // 超过 visible 层的都压到最大深度
    // ⚠ z-index: 任务卡层级要完全高于报错卡
    //   报错卡最高层 = N-1, 任务卡基准 = N + 10, 确保任务卡最低层也高于报错卡最高层
    const baseZ = N + 10;
    t.style.zIndex = baseZ + (n - d);
    // ⭐⭐ 同主卡（2026-09-13）：**不是透明，是暗**。
    //   opacity 恒为 1（不能看穿，否则标题和背景糊在一起），
    //   靠 .t-dim 那层越往下压得越黑来表达层次。
    t.style.opacity = 1;
    const tdim=t.querySelector('.t-dim');
    if(tdim) tdim.style.opacity = Math.min(0.62, clamped*0.2);
    if (!t.classList.contains('entering')) {
      t.style.transform = 'translate(0, ' + (clamped * STEP) + 'px)';
    }
    // ⚠ 层次感现在全靠阴影：顶层投得最重（它压着下面所有卡），
    //   越深的卡自己投得越轻 —— 它上面已经有别的卡在投影了，再重就糊成一片黑。
    // ⚠⚠ 超过 MAX_VISIBLE 的卡【不投影】（2026-09-14 用户发现）：
    //   它们的位移被压到和最深那张一样，卡身完全叠在同一个位置、被盖得看不见，
    //   但阴影是从卡边缘往外渗的 —— 10 个任务就是 7 份阴影叠在同一圈上，黑成一坨。
    //   卡片有最大叠加数，阴影也得有。
    const buried = d > clamped;                                          // 被压到最大深度之后、完全看不见的
    t.style.boxShadow = buried ? 'none' : clamped > 0
      ? '0 -6px 18px rgba(0,0,0,.42), 0 10px 28px rgba(0,0,0,.22)'   // 上缘加一道内收阴影 = "被压住"
      : '0 18px 50px rgba(0,0,0,.45)';
    // ⚠ 同主卡: 只有顶层(d=0)能交互, 否则叠压在下面露边的任务卡也能点到
    t.style.pointerEvents = (d===0) ? 'auto' : 'none';
    // 2026-10-22（docs/263 第 13 条）：压在下面的不算毛玻璃（样式见 04-tasks.css .stack-under）
    t.classList.toggle('stack-under', d>0);
  });
  if(window.V7FreeMode&&window.V7FreeMode.isActive())window.V7FreeMode.syncSpecialUnit('tasks');
  window.V7FreeMode?.syncEmptyUnits();
  // ⚠⚠ 2026-09-14 修复：任务堆变化时报错堆位置要跟着刷新（报错堆起点要读任务堆高度）
  setErrors();
  stackTrashSync('tasks');   // 2026-10-18 深夜：垃圾桶挪到当前最上面那张卡上
}

// ═══ 报错堆: 独立于任务堆的卡片堆(主卡下方), 多条报错像任务堆一样叠压 ═══
// 报错卡按插入顺序叠压: index 0 = 最上(最新)。确认后消失 → 剩余重排。
// ⚠【动态位置】报错堆起点 = 主卡叠压边界 + 间距。任务堆在报错堆下方，根据报错数量动态错开。
const errorsEl = document.getElementById('errors');
let ecur = 0;                 // 当前报错卡索引(滚轮切换)

// 使用未受折叠动画影响的稳定布局尺寸，避免 getBoundingClientRect() 读到过渡中的压缩矩形。
function mainStackMetrics(){
  const anchor=document.querySelector('.anchor');
  const style=anchor ? getComputedStyle(anchor) : null;
  const left=style ? (parseFloat(style.left)||60) : 60;
  const top=style ? (parseFloat(style.top)||60) : 60;
  const scale=UI_SCALE;
  const height=400*scale;
  const step=STEP*scale;
  return {
    top,
    left,
    bottom:top+height,
    step,
    // 主卡堆与视觉保持一致：深层卡片仍可轮换，但不再为不可见的层预留空间。
    bottomWithStack:top+height + stackVisibleDepth(N)*step
  };
}

// 动态计算报错堆和任务堆的位置
function updateStackPositions(){
  const anchor = document.querySelector('.anchor');
  if(!anchor) return;
  if(window.V7FreeMode&&window.V7FreeMode.isActive()){
    setTasks();
    window.V7FreeMode.applyPositions();
    return;
  }
  const metrics=mainStackMetrics();
  // ⭐⭐ 2026-09-13 换序：主卡 → **任务堆** → **报错堆**（原来是报错堆在上）。
  //
  //   原因（用户反馈）：报错堆在上的话，**弹一张报错卡就把整个任务堆往下推** ——
  //   用户正要点任务卡上的按钮，按钮自己跑了。而报错卡恰恰最容易在
  //   "正在生成、用户盯着任务卡"的时候弹出来。
  //
  //   ⭐ 换序之后：**任务堆的位置只由主卡决定，报错来多少张都不动它**。
  //     代价是报错堆要往下让，可能被挤出窗口 —— 下面 setErrors 里有夹取。
  //
  //   ⚠ 层级关系【不变】：任务卡(z 高) 仍在报错卡(z 低) 上方。这里只动纵向位置。
  const taskHeights=[...tasksEl.querySelectorAll('.task:not(.leaving)')].map(el=>el.offsetHeight||150);
  const taskHeight=taskHeights.length?Math.max(...taskHeights):150;
  // 任务堆锚定在主卡堆之后；报错堆在 setErrors 中根据任务堆实际底部选择下方、上方或侧边。
  tasksEl.style.top = Math.max(8,Math.min(metrics.bottomWithStack+16,(window.innerHeight||1100)-taskHeight-6))+'px';
  tasksEl.style.left = metrics.left + 'px';
  // 拖动主卡或改变窗口大小后，任务露出层数也要重新计算。
  // setTasks 会在任务布局完成后刷新报错堆位置。
  setTasks();
}

// 任务堆往下伸多高（顶层卡高 + 叠压露出的部分）。没有任务卡时是 0。
// ⚠ 和报错堆那边的算法保持一致，改一个要改两个。
function taskStackExtent(){
  const els=[...tasksEl.querySelectorAll('.task')].filter(t=>!t.classList.contains('leaving'));
  const n=els.length;
  if(!n) return 0;
  let maxH=0;
  els.forEach(t=>{ const h=t.offsetHeight||150; if(h>maxH) maxH=h; });   // 150 是兜底
  return maxH + (taskVisibleCount(els) - 1) * STEP;
}
function setErrors(){
  const els = [...errorsEl.querySelectorAll('.error-card')];
  const n = els.length;

  // ── 报错堆起点 = 任务堆底部 + 间距（2026-09-13 换序后）──
  //   ⚠ 任务堆的 top 在 updateStackPositions 里已经定好了，这里【只读不写】。
  //     以前这个函数会反过来改 tasks.style.top，那正是"报错一弹任务卡就跑"的根源。
  const metrics = mainStackMetrics();
  const taskTop = parseFloat(tasksEl.style.top) || (metrics.bottomWithStack + 16);
  const tExtent = taskStackExtent();
  const taskBottom = taskTop + tExtent;
  const gap = 24;
  let errTop = taskBottom + (tExtent ? gap : 0);   // 没有任务卡就紧贴主卡堆
  let errLeft = metrics.left;

  // 报错堆整体避让任务堆与主卡可见堆；不能只看任务卡上方还有多少高度。
  const winW = window.innerWidth || 1020;
  const winH = window.innerHeight || 920;
  const errW = Math.max(300,...els.map(el=>el.offsetWidth||300));
  const errH = Math.max(0,...els.map(el=>el.offsetHeight||100)) || 100;
  const errExtent0 = errH + Math.max(0,Math.min(n,ERR_MAX_VISIBLE)-1)*ERR_STEP;
  // ⭐ 2026-10-22（第二批踩到）：超过 4 条时下面还有一颗「还有 N 条 · 展开」，它也是这个堆的一部分 ——
  //   以前没把它算进高度，按钮直接伸到堆的外面，被底部悬浮条（夏三六）盖住，点不到。
  const moreRoom = n > ERR_MAX_VISIBLE ? 32 : 0;
  const errExtent = errExtent0 + moreRoom;
  // ⭐ 底部悬浮条（夏三六 / 主导航）也是障碍物：它永远压在下面那一片，报错堆不能伸进去。
  const floating = [...document.querySelectorAll('.v7-agent-dock, #v7PrimaryNav.v7-floating-bar, .v7-floating-moving')]
    .filter(el => el.getBoundingClientRect().height > 0)
    .map(el => { const r = el.getBoundingClientRect(); return {left:r.left, top:r.top, right:r.right, bottom:r.bottom}; });
  // ⚠⚠ 2026-10-22 修：maxErrTop 原来只按窗口底部算（winH - 堆高 - 20），
  //   可 10-22 又把悬浮条加进了障碍物 —— 窗口 1100 高时悬浮条从 1004 起，
  //   报错堆放到 854（还在 982 以内）就已经压到它 ⇒ 每一个候选位置都判「放不下」，
  //   最后走兜底分支直接叠在任务卡上（实测：报错卡 576~748 和任务卡 578~762 完全重合）。
  //   现在上限取「窗口底部」和「悬浮条顶边」里更靠上的那个。
  const dockTop = floating.length ? Math.min(...floating.map(r => r.top)) : winH;
  const maxErrTop = Math.min(winH, dockTop - 12) - errExtent - 20;
  const mainW = Math.max(300,...cards.filter(el=>!el.hidden).map(el=>el.offsetWidth||300))*UI_SCALE;
  const mainBounds = {left:metrics.left,top:metrics.top,right:metrics.left+mainW,bottom:metrics.bottomWithStack};
  const taskLeft = parseFloat(tasksEl.style.left) || metrics.left;
  const taskW = Math.max(300,...[...tasksEl.querySelectorAll('.task:not(.leaving)')].map(el=>el.offsetWidth||300));
  const taskBounds = {left:taskLeft,top:taskTop,right:taskLeft+taskW,bottom:taskBottom};
  const obstacles = (tExtent ? [mainBounds,taskBounds] : [mainBounds]).concat(floating);
  const canPlace = ({left,top}) => left>=8 && left+errW<=winW-8 && top>=8 && top<=maxErrTop &&
    obstacles.every(rect=>left+errW<=rect.left || left>=rect.right || top+errExtent<=rect.top || top>=rect.bottom);
  errorsEl.classList.remove('layout-overlap-fallback');
  if (!canPlace({left:errLeft,top:errTop})) {
    // 下方放不下时先找左右侧列；上方/空隙候选也必须避开整块主卡可见堆。
    const sideTop = Math.max(8,Math.min(taskTop,maxErrTop));
    const sideRight = Math.max(...obstacles.map(rect=>rect.right))+32;
    const sideLeft = Math.min(...obstacles.map(rect=>rect.left))-errW-32;
    const dockTop = floating.length ? Math.min(...floating.map(r=>r.top)) : winH;
    const candidates = [
      {left:sideRight,top:sideTop},
      {left:sideLeft,top:sideTop},
      // ⚠ 2026-10-22 修：窗口窄、主卡又被拖到右边时，左边那一整列是空的，
      //   可候选里只有 sideLeft（= 最左边障碍物再往左 = 负坐标，永远过不了 left>=8）。
      //   实测 768 高、主卡 left=660：任务堆占 660~960、主卡堆也占 660~960，
      //   所有候选都判「压住」，只能走兜底叠在任务卡上（报错 576~748 / 任务 578~762 完全重合）。
      //   ⇒ 补最左边一列：贴着窗口左沿放，位置照样要过 canPlace（别的卡在那儿就不去）。
      {left:8,top:sideTop},
      {left:8,top:maxErrTop},
      {left:metrics.left,top:taskTop-errExtent-gap},
      {left:metrics.left,top:metrics.top-errExtent-gap},
      {left:metrics.left,top:metrics.bottomWithStack+gap},
      {left:metrics.left,top:dockTop-errExtent-12},
      {left:metrics.left,top:8},
      {left:metrics.left,top:maxErrTop}
    ];
    const position = candidates.find(canPlace);
    if (position) {
      errLeft = position.left;
      errTop = position.top;
    } else {
      // 窗口连一个独立报错堆都容不下时，保留既有可视区兜底。
      errTop = Math.max(8,Math.min(errTop,maxErrTop));
      errorsEl.classList.add('layout-overlap-fallback');
    }
  }
  if(!(window.V7FreeMode&&window.V7FreeMode.isActive())){
    errorsEl.style.top  = errTop + 'px';
    errorsEl.style.left = errLeft + 'px';
  }

  // ⭐⭐ 2026-10-14【"报错卡消失后参考图卡不往上靠"的根因，实测确认】——
  //   ⚠⚠ 下面第 6021 行有一句 `if(!n){ ...; return; }`：**没有报错卡时直接 return**。
  //     而参考图卡的重排原来只写在【函数末尾】⇒ 报错卡一关完（n===0）就从这儿走了，
  //     末尾那句永远跑不到 ⇒ 参考图卡停在"被推开"的旧位置不动。
  //   实测证据（改之前）：
  //     起点（无报错卡）      #refs transform = translate(0px, 0px)
  //     加一张报错卡          #refs transform = translate(0px, 112px)   ← 让位（对）
  //     关掉报错卡（等 3 秒） #refs transform = translate(0px, 112px)   ← 🔴 停在旧值
  //     手动调 reposition()   → translate(0px, 0px)                     ← 算法本来是好的
  //   用户的感受就是"它不动，我得点它一下它才往上动一下"。
  //   ⇒ 修法：把重排【挪到 return 之前】，保证 n===0 这条早退路径也走得到；
  //     函数末尾那次保留（n>0 时堆内部还有逐张叠压要算）。
  //   ⚠ 只加调用，不改算法 —— reposition() 里已经是"没有报错卡就 translate(0,0)"，
  //     避让算法不重复写第二份（两份必然漂移）。
  const refCardReposition = () => window.V7ReferenceCard?.reposition();

  if(!n){ ecur = 0; window.V7FreeMode?.syncSpecialUnit('errors'); window.V7FreeMode?.syncEmptyUnits(); refCardReposition(); return; }

  // A direct L3 confirmation is a decision surface, not a background notice.
  // Keep it at the visible top while it is waiting for the user's answer;
  // later L1/L2 notices stay in the same legacy stack underneath it.
  const directConfirmation = els.find(el => el.dataset.v7DirectConfirmation === '');
  if(directConfirmation) ecur = els.indexOf(directConfirmation);

  // 修正 ecur 边界
  if(ecur >= n) ecur = n - 1;
  if(ecur < 0) ecur = 0;

  const visible = Math.min(n, ERR_MAX_VISIBLE);
  els.forEach((e, i) => {
    const relIdx = (i - ecur + n) % n;      // 相对当前卡的偏移(0=当前, 1=下一张...)
    const clamped = Math.min(relIdx, visible - 1);
    // ⚠ z-index 层级：报错卡主层和主卡叠压层平齐，报错卡叠压层在主卡叠压层下方
    //   主卡范围 1~N (顶层=N, 最深=1)
    //   报错卡主层 = N-1 (和主卡第2层平齐)
    //   报错卡叠压层 < N-1 (在主卡叠压层下方)
    const baseZ = N - 1;  // 报错卡主层的 z-index
    e.style.zIndex = baseZ - relIdx;
    // ⭐ 同任务堆（2026-09-13）：不透明 + 靠阴影分层。报错卡更要看得清。
    e.style.opacity = 1;
    e.style.transform = 'translate(0, ' + (clamped * ERR_STEP) + 'px)';
    // ⚠ 同任务堆（2026-09-14）：压到最大深度之后看不见的卡不投影，否则阴影叠成一坨黑。
    const buried = relIdx > clamped;
    e.style.boxShadow = buried ? 'none' : clamped > 0
      ? '0 -6px 18px rgba(0,0,0,.42), 0 10px 28px rgba(0,0,0,.22)'
      : '0 18px 50px rgba(0,0,0,.45)';
    e.style.pointerEvents = (relIdx===0) ? 'auto' : 'none';   // 只有当前能点
    // 2026-10-22（docs/263 第 13 条）：压在下面的不算毛玻璃（样式见 04-tasks.css .stack-under）
    e.classList.toggle('stack-under', relIdx>0);

    // 详情层跟着报错卡一起叠压
    const detailEl = e._detailEl;
    if(detailEl){
      detailEl.style.zIndex = baseZ - relIdx + 1;  // 详情层比报错卡高一层
      detailEl.style.transform = 'translate(0, ' + (clamped * ERR_STEP) + 'px)';
      // 只有顶层报错卡的详情层可以显示
      if(relIdx !== 0 && detailEl.classList.contains('show') && e.dataset.v7DirectConfirmation !== ''){
        detailEl.classList.remove('show');
      }
    }
  });
  if(window.V7FreeMode&&window.V7FreeMode.isActive())window.V7FreeMode.syncSpecialUnit('errors');
  // ⭐ 2026-10-22（docs/263 §2「报错堆只露 4 张」）：超过 ERR_MAX_VISIBLE 的那些以前就这么【消失了】——
  //   用户只看到 4 条，以为只有 4 个问题。这里在堆的最下面标一句「还有 N 条」。
  // ⭐ 2026-10-22 第二批（对照台第 4 条，用户拍板「实装」）：它是个按钮，点开列出全部报错的标题 ——
  //   点某一条 = 把它翻到最上面；右边 × = 按这张卡自己的安全方式关掉（_v7clear：要你决定的卡当「取消」）。
  //   ⚠ 位置要放在【最后一张卡的底边下面】：卡高 100，第一版写成 visible*ERR_STEP(=96) 被压在卡底下，看不见。
  {
    const hidden = Math.max(0, n - visible);
    let more = errorsEl.querySelector('.errors-more');
    let list = errorsEl.querySelector('.errors-more-list');
    if (!hidden) { if (more) more.remove(); if (list) list.remove(); errMoreOpen = false; }
    else {
      if (!more) {
        more = document.createElement('button');
        more.type = 'button';
        more.className = 'errors-more';
        more.addEventListener('click', ev => { ev.stopPropagation(); errMoreOpen = !errMoreOpen; setErrors(); });
        errorsEl.appendChild(more);
      }
      const cardH = Math.max(0, ...els.map(el => el.offsetHeight || 100)) || 100;
      const top = (visible - 1) * ERR_STEP + cardH + 6;
      more.style.top = top + 'px';
      more.innerHTML = '还有 ' + hidden + ' 条 · ' + (errMoreOpen ? '收起' : '展开');
      more.setAttribute('aria-expanded', errMoreOpen ? 'true' : 'false');
      if (!errMoreOpen) { if (list) list.remove(); }
      else {
        if (!list) { list = document.createElement('div'); list.className = 'errors-more-list'; list.setAttribute('role', 'list'); errorsEl.appendChild(list); }
        list.style.top = (top + 28) + 'px';
        list.replaceChildren();
        // 从当前最上面那张开始往下列，跟堆里的顺序一致
        for (let k = 0; k < n; k++) {
          const card = els[(ecur + k) % n];
          const row = document.createElement('div');
          row.className = 'errors-more-row' + (k === 0 ? ' is-top' : '');
          row.setAttribute('role', 'listitem');
          const go = document.createElement('button');
          go.type = 'button'; go.className = 'errors-more-go';
          go.textContent = (card.querySelector('.ec-title')?.textContent || '提示').trim();
          go.title = (card.querySelector('.ec-desc')?.textContent || go.textContent).trim();
          go.addEventListener('click', ev => { ev.stopPropagation(); ecur = els.indexOf(card); errMoreOpen = false; setErrors(); });
          const x = document.createElement('button');
          x.type = 'button'; x.className = 'errors-more-x'; x.setAttribute('aria-label', '关掉这条');
          x.innerHTML = window.ICON ? ICON.render('close', 12) : '×';
          x.addEventListener('click', ev => { ev.stopPropagation(); if (typeof card._v7clear === 'function') card._v7clear(); else card.remove(); });
          row.append(go, x);
          list.appendChild(row);
        }
      }
    }
  }
  window.V7FreeMode?.syncEmptyUnits();
  // ⭐ 这里【不再碰任务堆】（2026-09-13）。
  //   以前这段会把 tasks.style.top 推到"报错堆底部 + 24"，
  //   于是每弹一张报错卡，任务卡就往下跳一次 —— 用户正要点的按钮自己跑了。
  //   现在任务堆的位置只由主卡决定（见 updateStackPositions），报错堆往下让。
  // ⭐ 2026-10-13：参考图卡跟在报错堆下面（用户定"报错来了参考图让位"）。
  //   ⚠ 只加这一行调用 —— 避让算法不重复写一份（两份必然漂移）。
  //   ⚠⚠ 2026-10-14：这一句【单独不够】—— 上面 n===0 那条早退路径也必须有（见 6021 行上方注释）。
  refCardReposition();
  stackTrashSync('errors');   // 2026-10-18 深夜：垃圾桶挪到当前最上面那张卡上
}

// 取当前 ecur 对应的报错卡 DOM(报错堆是动态增删的)
function topErrorEl(){
  const els = [...errorsEl.querySelectorAll('.error-card')];
  if(!els.length) return null;
  return els[Math.min(ecur, els.length - 1)];
}

// ⚠ 报错堆在主卡下方、任务堆上方, 高度有限。报错多了报错堆往下伸会和任务堆重叠。
//   简单处理: 报错堆出现/消失时, 任务堆动态上移/下移错开 — 但用户要"两堆互不推挤"。
//   ⚠ 为防重叠, 报错堆叠压深度用更小的步长(报错卡更高, 露边更少), 且最多叠 3 层。
function addErrorCard(o={}){
  // o: { severity:'L1'|'L2'|'L3'|'L4', level:'ok'|'info'|'warn'|'err', title, body,
  //      detail, confirm, cancel, danger, blocking, duration, onConfirm, onCancel }
  if(!errorsEl) return;
  const lv = SEM_ICO[o.level] ? o.level : 'info';
  const severity=resolveErrorSeverity(o);
  const isL1 = severity==='L1';
  // L4 不进入报错堆，直接创建显示器级冻结窗口。
  if(severity==='L4') return openL4Window(o);

  // 报错卡: 显示图标 + 标题 + 简短描述
  const e = document.createElement('div');
  e.className = 'error-card ec-'+severity.toLowerCase();
  e.dataset.severity=severity;
  e.dataset.level=lv;
  let html = '';

  if(isL1){
    // L1 胶囊: 图标 + 文字横排一行
    html += '<div class="ec-header">';
    html += '<span class="ec-ico '+lv+'">'+(window.ICON?ICON.render(SEM_ICO[lv],20):SEM_ICO[lv])+'</span>';
    html += '<span class="ec-title">'+escapeHtml(o.title||o.body||'提示')+'</span>';
    // ⭐ 2026-10-22（docs/263 第 6 条「删除改成能撤销」）：胶囊右边可以带一个操作按钮（「撤销」）。
    //   用 o.action = { label, run }；点了先跑 run 再收卡。见下面 offerUndo()。
    if(o.action && typeof o.action.run==='function'){
      html += '<button type="button" class="ec-action" data-ec-action>'+escapeHtml(o.action.label||'撤销')+'</button>';
    }
    html += '</div>';
  } else {
    // L2/L3/L4: 图标 + 标题在同一行, 描述在下方
    html += '<div class="ec-header">';
    html += '<span class="ec-ico '+lv+'">'+(window.ICON?ICON.render(SEM_ICO[lv],20):SEM_ICO[lv])+'</span>';
    html += '<span class="ec-title">'+escapeHtml(o.title||'提示')+'</span>';
    html += '</div>';
    if(o.body && !o.bodyNode){
      html += '<div class="ec-desc">'+escapeHtml(o.body)+'</div>';
    }
  }
  // 添加光效元素(完全仿照任务卡), 统一放入圆角裁切层
  html += '<div class="error-light-clip">';
  html += '<div class="error-glow"></div>';
  html += '<div class="error-bright"></div>';
  html += '<div class="error-edgehint"></div>';
  html += '</div>';
  e.innerHTML = html;
  // ⭐ 2026-10-15（公告要用）：o.bodyNode = 调用方用 textContent 建好的正文节点（富文本公告）。
  //   ⚠ 只收 DOM 节点、不收 HTML 字符串 —— 公告正文来自公开接口，不许走 innerHTML。
  //   带它的卡用 .ec-rich 变高（最高约 240，超出在卡内滚，见 .error-card.ec-rich 样式）。
  if(!isL1 && o.bodyNode && typeof o.bodyNode==='object' && o.bodyNode.nodeType===1){
    const desc=document.createElement('div');
    desc.className='ec-desc ec-rich-body';
    desc.append(o.bodyNode);
    e.querySelector('.ec-header')?.after(desc);
    e.classList.add('ec-rich');
  }
  // ⭐ 2026-10-15（用户定「公告在报错卡片的最顶层」）：钉顶卡。见下面插入那段。
  if(o.pin==='top') e.dataset.pinTop='';
  if(window.BG && window.BG.applyErrorToCard) window.BG.applyErrorToCard(e, severity);

  // 报错详情层: 独立的弹出层(向右滑动显示)
  let detailEl = null;
  if(!isL1 && (o.detail || o.confirm!==false)){
    detailEl = document.createElement('div');
    detailEl.className = 'error-detail';
    let detailHtml = '';

    // 详细信息
    if(o.detail){
      detailHtml += '<div class="ed-body">'+escapeHtml(o.detail)+'</div>';
    }

    // 按钮行
    if(o.confirm!==false){
      detailHtml += '<div class="ed-btns">';
      // ⭐ 2026-10-14 新增（公告要用）：调用方可以给一组【自己的按钮】。
      //   o.actions = [{ key:'settings', label:'到设置里看完整公告', primary:false }]
      //   ⚠ 跟 confirm/cancel 的区别：这些按钮【按了不关卡片】——
      //     它们只是"去做另一件事"（比如跳到设置卡），用户回来还得能点"我已知晓"。
      //     所以下面绑定时不能走 close()。
      //   ⚠ 老调用方不传 o.actions，行为一个字不变。
      if(Array.isArray(o.actions)){
        o.actions.forEach(a=>{
          if(!a||!a.key||!a.label) return;
          detailHtml += '<button class="ed-btn'+(a.primary?' primary':'')+'" data-custom="'+escapeHtml(a.key)+'">'+escapeHtml(a.label)+'</button>';
        });
      }
      // ⭐ 2026-10-18 深夜（用户定：L2 / L3 报错卡加「反馈这个问题」，自动带上错误码和当时情况）。
      //   只给 ERR.report 出来的【真报错】（带 code、level 是 err / warn）；公告（钉顶）不给；
      //   L3 只给「只是告诉你」的那种 —— 要你做决定的（带 onConfirm / onCancel）不给，免得点了反馈等于替你做了决定。
      const canFeedback=!!(window.V7Feedback&&o.code&&o.pin!=='top'&&(lv==='err'||lv==='warn')
        &&(severity==='L2'||(severity==='L3'&&!o.onConfirm&&!o.onCancel)));
      if(canFeedback) detailHtml += '<button class="ed-btn" data-feedback-error>反馈这个问题</button>';
      // ⭐ 2026-10-22（docs/263 §2「报错卡上没有重试」）：调用方传了 o.retry 就给一个「重试」主按钮。
      //   以前报错卡只有「知道了」—— 提示里写着「稍后再点一次传回」，可那个按钮在另一张卡上。
      //   ⚠ 传了 retry 就不再给「确定」：两个主按钮等于没有主按钮（用户不知道该点哪个）。
      if(typeof o.retry==='function'){
        detailHtml += '<button class="ed-btn primary" data-retry>'+escapeHtml(o.retryLabel||'重试')+'</button>';
      }
      // ⭐ 2026-10-24（V7待办/08「插件需要更新」）：o.persistent = 关不掉的常驻卡 —— 只留自己的按钮，
      //   没有「取消 / 知道了」，垃圾桶一键清也跳过它；由调用方在事情解决后用返回的 close() 收掉。
      if(o.cancel!==false && !o.persistent){
        detailHtml += '<button class="ed-btn" data-a="cancel">'+escapeHtml(o.cancel||'取消')+'</button>';
      }
      if(typeof o.retry!=='function' && !o.persistent){
        detailHtml += '<button class="ed-btn '+(o.danger?'danger':'primary')+'" data-a="confirm">'+escapeHtml(o.confirm||'确定')+'</button>';
      }
      detailHtml += '</div>';
    }

    detailEl.innerHTML = detailHtml;
    e._detailEl = detailEl;  // 关联详情层

    // 绑定按钮事件
    const btns = detailEl.querySelectorAll('[data-a]');
    btns.forEach(btn=>{
      btn.addEventListener('click', ev=>{
        ev.stopPropagation();
        const a = btn.dataset.a;
        try{
          if(a==='confirm' && o.onConfirm) o.onConfirm();
          if(a==='cancel' && o.onCancel) o.onCancel();
        } finally { close(); }
      });
    });
    // ⭐ 自定义按钮（2026-10-14）：按了【不关卡片】—— 只是去做另一件事。
    //   ⚠ 这里刻意不调 close()：公告那张卡上，用户点了"到设置里看完整公告"
    //     跳走再回来，还得能点"我已知晓"；卡片自己没了就等于没确认过。
    detailEl.querySelectorAll('[data-custom]').forEach(btn=>{
      btn.addEventListener('click', ev=>{
        ev.stopPropagation();
        const key = btn.dataset.custom;
        const item = Array.isArray(o.actions) ? o.actions.find(x=>x && x.key===key) : null;
        try{ if(item && typeof item.run==='function') item.run(); }
        catch(error){ if(window.ERR) ERR.report('UI_ACTION_FAILED',{message:String(error&&error.message||error)}); }
      });
    });
    // ⭐ 2026-10-22：重试按钮 —— 先收掉卡片再执行（重试往往会弹新卡，旧卡留着会叠两层），
    //   执行里的异常照「自定义按钮」那套兜住，不能因为重试失败把整个报错堆搞崩。
    const retryBtn=detailEl.querySelector('[data-retry]');
    if(retryBtn) retryBtn.addEventListener('click', ev=>{
      ev.stopPropagation();
      close();
      try{ o.retry(); }
      catch(error){ if(window.ERR) ERR.report('UI_ACTION_FAILED',{message:'重试没发出去：'+String(error&&error.message||error)}); }
    });
    // 「反馈这个问题」：L2 卡留着（跟自定义按钮一样，只是去做另一件事）；L3 卡先收掉 —— 它开着时界面只认它，反馈卡打不开
    const fbBtn=detailEl.querySelector('[data-feedback-error]');
    if(fbBtn) fbBtn.addEventListener('click', ev=>{
      ev.stopPropagation();
      const info={code:o.code,level:severity,title:o.title,body:o.body,detail:o.detail};
      if(severity==='L3') close();
      try{ window.V7Feedback.fromError(info); }
      catch(error){ if(window.ERR) ERR.report('UI_ACTION_FAILED',{message:'打开问题反馈失败：'+String(error&&error.message||error)}); }
    });
  }

  // L4 冻结遮罩用计数管理，多个 L4 同时存在时关闭其中一个不会提前解锁。
  const isBlocking=severity==='L4' || !!o.blocking;
  if(isBlocking){ blockingCount++; syncBlockingLock(); }

  // 入场: 从主卡下分离(跟任务卡进场同款)
  e.style.opacity='0'; e.style.transform='translateY(-46px) scaleY(.86) scaleX(.97)';
  // ⭐ 2026-10-15 钉顶：已经有钉顶卡（启动公告 / 连不上服务器）时，后来的普通卡插在它【下面】，
  //   钉顶卡一直是堆顶那张，直到用户点掉它。新的钉顶卡照常插最上面。
  // ⭐⭐ 2026-10-18 深夜（用户实测界面假死）：报错堆从上到下固定排成 ① 要你决定的卡（L3）② 钉顶的卡（公告）③ 其余。
  //   原来钉顶的公告永远在最上面，新弹的 L3 决定卡插在它下面 —— L3 一出来就把界面冻住、只认它（V7FocusScope），
  //   可它被公告压着点不到，界面就死了（例：公告没点「已知晓」时，Agent 测试连接要「同意」那张卡）。
  if(severity==='L3') e.dataset.decision='';
  const lastOf=sel=>[...errorsEl.querySelectorAll(':scope > .error-card'+sel)].pop();
  const after=severity==='L3'?null:o.pin==='top'?lastOf('[data-decision]'):(lastOf('[data-pin-top]')||lastOf('[data-decision]'));
  const anchor=after?after.nextSibling:errorsEl.firstChild;
  errorsEl.insertBefore(e, anchor);   // 插到堆顶(index 0 = 最上)；有钉顶卡就插在它后面
  if(detailEl){
    errorsEl.insertBefore(detailEl, e);  // 详情层紧挨着插在卡片前面（跟原来插 firstChild 的相对顺序一致）
  }
  // ⭐ 2026-10-06 晚：非模态动作卡可以直接把详情层摊开（引擎离线那种）。
  //   ⚠ 摊开 ≠ 注册：不进 directConfirmations、不触发 V7FocusScope 的背景隔离，
  //     全局鼠标手势（含任务卡右滑）照常可用。L3 注册卡仍由 registerConfirmation 摊开。
  if(detailEl && o.expand){ detailEl.classList.add('show'); window.__errDetail=detailEl; }
  // ⭐⭐ 2026-10-22（P0：用户报「黄色的报错框无法点按」）：
  //   详情层（里面有「重试 / 知道了」）以前【只能】靠鼠标从卡片往右「推进」才弹（07-wheel-routing.js 里的手势）。
  //   触控板 / 没推动 / 卡片被压在别的层下时，用户看到的就是一张写着「点重试」却点不动的卡 —— 界面完全卡死。
  //   ⇒ 卡片本体加【点击展开】：点卡片 = 展开详情（按钮就出来了）；点第二下 = 收起。
  //   ⚠ 只认真正的点击：拖拽（卡片能拖）/ 横向推进手势都不该触发，所以判位移。
  //   ⚠ 只有堆顶那张能点（setErrors 里 pointerEvents 已按 relIdx 设，这里再加一道兜底）。
  if(detailEl){
    let downX=0, downY=0, downT=0;
    e.addEventListener('pointerdown', ev=>{ downX=ev.clientX; downY=ev.clientY; downT=Date.now(); });
    e.addEventListener('click', ev=>{
      if(Math.abs(ev.clientX-downX)>4 || Math.abs(ev.clientY-downY)>4) return;   // 拖着走的不算点击
      if(Date.now()-downT>600) return;                                          // 按住不放的不算
      if(ev.target.closest && ev.target.closest('button,[data-ec-action]')) return;
      if(detailEl.classList.contains('show')){ detailEl.classList.remove('show'); if(window.__errDetail===detailEl) window.__errDetail=null; }
      else { detailEl.classList.add('show'); window.__errDetail=detailEl; }
    });
  }
  ecur = 0;  // 新报错卡插入后, 当前索引归零(显示最新的)
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    e.style.transition='opacity .22s var(--ease-soft), transform .28s var(--ease-out)';
    e.style.opacity='1'; e.style.transform='translateY(0) scale(1)';
    setErrors();   // 立即叠压所有报错卡
    // 动画完成后再次调用，确保高度计算准确
    setTimeout(()=>setErrors(), 300);
  }));

  // 关闭逻辑
  let closed=false;
  // ⚠ 2026-10-22：改成 let —— L1 的自动消失要在 close 外面包一层清计时器（见下面 L1 那段）
  let close=()=>{
    if(closed) return;
    closed=true;
    if(severity==='L3' && window.V7FocusScope?.unregisterConfirmation){
      window.V7FocusScope.unregisterConfirmation(e);
    }
    // L4 清理冻结遮罩
    if(isBlocking){ blockingCount=Math.max(0, blockingCount-1); syncBlockingLock(); }
    // 隐藏详情层
    if(detailEl && detailEl.classList.contains('show')){
      detailEl.classList.remove('show');
    }
    // 卡片出场动画
    e.style.transition='opacity .2s var(--ease-soft), transform .22s var(--ease-out)';
    e.style.opacity='0'; e.style.transform='translateY(16px) scale(.97)';
    setTimeout(()=>{
      e.remove();
      if(detailEl) detailEl.remove();
      setErrors();      // 剩余报错重排, 堆自动上移
    }, 240);
  };

  // L1 自动消失
  // ⭐ 2026-10-22：胶囊上的操作按钮（撤销）
  if(isL1 && o.action && typeof o.action.run==='function'){
    const actBtn=e.querySelector('[data-ec-action]');
    if(actBtn) actBtn.addEventListener('click', ev=>{
      ev.preventDefault(); ev.stopPropagation();
      if(closed) return;
      try{ o.action.run(); }
      catch(error){ console.warn('[提示卡] 操作按钮出错', error); }
      close();
    });
  }
  // ⭐ 2026-10-22（docs/263 §2「提示固定 3 秒」）：以前写死 3000ms，85 处调用都没传时长 ——
  //   28 个字的提示 3 秒读不完就没了。现在按字数算：基础 2 秒 + 每 10 个字 1 秒，上限 8 秒。
  //   调用方显式传了 duration 的照旧听它的（有些提示就是要短）。
  //   ⚠ 悬停暂停：鼠标停在上面就不走，移开后再给 1 秒 —— 用户正在读的时候不能消失。
  if(isL1){
    const textForLength=String(o.title||'')+String(o.body||'');
    const autoMs=Math.min(8000, 2000 + Math.ceil([...textForLength].length/10)*1000);
    const duration=Number.isFinite(Number(o.duration)) && Number(o.duration)>0 ? Number(o.duration) : autoMs;
    let remaining=duration, timer=null, startedAt=0;
    const start=()=>{ startedAt=Date.now(); timer=setTimeout(close, remaining); };
    const pause=()=>{ if(!timer) return; clearTimeout(timer); timer=null; remaining=Math.max(0, remaining-(Date.now()-startedAt)); };
    const resume=()=>{ if(timer) return; start(); };
    start();
    e.addEventListener('mouseenter', pause);
    e.addEventListener('mouseleave', resume);
    // 关闭时清掉计时器，别让它在卡已经移除后再跑一次
    const origClose=close;
    close=()=>{ if(timer){clearTimeout(timer);timer=null;} origClose(); };
  }

  // ⭐ 2026-10-18 深夜：报错卡垃圾桶一键清（clearAllErrorCards）按这张卡的「安全选项」收掉 ——
  //   用户定：L3 要你决定的卡当作「取消」（不替用户做决定）；取消是危险操作的卡（退出软件 / 放弃任务）调用方传 safeClear:'none' 只收不选；
  //   公告传 safeClear:'confirm'（清掉 = 已读，不再弹）。其余只收起。
  if(o.persistent) e.dataset.persistent='';
  e._v7clear=()=>{
    if(closed || o.persistent) return;
    const how=o.safeClear||(severity==='L3'?'cancel':'none');
    try{
      if(how==='confirm'&&o.onConfirm) o.onConfirm();
      else if(how==='cancel'&&o.onCancel) o.onCancel();
    }catch(error){ console.warn('[报错卡] 一键清时回调出错', error); }
    close();
  };
  return { close, el: e, detailEl };
}

// ═══ 删了能撤销（2026-10-22，docs/263 第 6 条，用户在对照台拍板「实装」）════════════
//   以前 63 处删除里 40 处点了直接没、23 处弹确认框（点多了大家闭眼点「确定」）。
//   现在普通删除：先删（立刻生效），底部弹一条「已删除「X」 撤销」，6 秒内点撤销就放回去。
//   ⚠ 只给「放得回去」的删除用（列表里的一条数据）；真删文件 / 清空全部这种回不来的，照旧用确认框。
//   用法：V7Undo.offer('已删除「基础修脸」', () => { 把它放回去 });
function offerUndo(title, undo, opts){
  if(typeof undo!=='function') return null;
  const o=opts||{};
  let done=false;
  const run=()=>{ if(done) return; done=true; undo(); };
  const duration=Number(o.duration)||6000;
  // ⚠ 在模态弹窗里删的（项目日程、布局管理……）要传 host = 弹窗元素：
  //   弹窗开着时 focus-scope 会把弹窗外面全部 inert，底部报错堆里的「撤销」点不到。
  //   ⇒ 这种情况把撤销条挂在弹窗自己底部（sticky）。⚠ host 要选【不会被重画】的那层（别选 innerHTML 会整块换掉的内容区）。
  if(o.host && o.host.isConnected){
    o.host.querySelectorAll(':scope > .v7-undo-inline').forEach(x=>x.remove());
    const bar=document.createElement('div');
    bar.className='v7-undo-inline'; bar.setAttribute('role','status');
    bar.innerHTML='<span>'+escapeHtml(String(title||'已删除'))+'</span><button type="button">'+escapeHtml(o.label||'撤销')+'</button>';
    const timer=setTimeout(()=>bar.remove(), duration);
    bar.querySelector('button').addEventListener('click', ev=>{
      ev.preventDefault(); ev.stopPropagation(); clearTimeout(timer); bar.remove();
      try{ run(); }catch(error){ console.warn('[撤销] 出错', error); }
    });
    o.host.appendChild(bar);
    return { close:()=>{ clearTimeout(timer); bar.remove(); }, el:bar };
  }
  return addErrorCard({
    severity:'L1', level:'info', title:String(title||'已删除'),
    duration,
    action:{ label:o.label||'撤销', run }
  });
}
window.V7Undo={ offer:offerUndo };

// 初始化报错堆和任务堆位置
// ═══ 一键清（2026-10-18 深夜，用户定）══════════════════════════════
//  「报错卡片比较频繁，包括任务卡也是。希望有一个高优先级的、能一键清除所有任务卡片和报错卡片」：
//   · 报错堆最上面那张卡的左上角一个垃圾桶 → 强制清 L1~L3 全部（L4 是单独的全屏窗口，不在这里）。
//     每张按自己的「安全选项」收（addErrorCard 的 e._v7clear）：L3 要你决定的当作「取消」；公告算已读；
//     取消是危险操作的卡（退出软件 / 放弃任务）只收不选。
//   · 任务堆最上面那张卡的左上角同样一个 → 只清【已经结束的】（完成 / 失败 / 取消），还在生成的留着；
//     走跟任务卡 ✕ 同一条路（cacheSetTaskbar(false) + removeTask），图都还在「记录与恢复」里。
//   ⚠ 垃圾桶是一个按钮，每次重排（setErrors / setTasks 末尾）挪到当前最上面那张卡上。
var STACK_TRASH_SVG='<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3"/></svg>';
var stackTrash={errors:null,tasks:null};   // ⚠ var 不用 const：setErrors / setTasks 在加载早期就会被调，const 还没到那一行会直接抛错
function clearAllErrorCards(){
  const cards=[...errorsEl.querySelectorAll(':scope > .error-card')];
  // 先清要你决定的（它们一走，界面立刻解冻），再清别的
  cards.sort((a,b)=>(b.hasAttribute('data-decision')?1:0)-(a.hasAttribute('data-decision')?1:0));
  let n=0;
  // 常驻卡（插件需要更新）一键清也不收 —— 用户定「关不掉，更新完才消失」
  cards.forEach(card=>{ if(card.hasAttribute('data-persistent')) return; if(typeof card._v7clear==='function'){ card._v7clear(); n++; } else { card.remove(); n++; } });
  // 卡片自己的 close 有 240ms 动画；兜底再排一次
  setTimeout(()=>{ errorsEl.querySelectorAll(':scope > .error-detail').forEach(d=>{ if(!d.nextElementSibling||!d.nextElementSibling.classList.contains('error-card'))d.remove(); }); setErrors(); },320);
  return n;
}
function clearFinishedTasks(){
  const done=taskList.filter(t=>t&&aiTaskIsTerminal(t));
  done.forEach(t=>{ try{ cacheSetTaskbar(t,false); }catch(_){} removeTask(t.id); });
  return done.length;
}
function stackTrashSync(kind){
  const host=kind==='errors'?errorsEl:tasksEl;
  if(!host||!stackTrash) return;
  const items=kind==='errors'
    ?[...host.querySelectorAll(':scope > .error-card')].filter(el=>el.style.opacity!=='0')
    :[...host.querySelectorAll(':scope > .task:not(.leaving)')];
  const cur=kind==='errors'?ecur:tcur;
  const top=items[cur]||items[0]||null;
  const want=!!top&&(kind==='errors'||taskList.some(t=>t&&aiTaskIsTerminal(t)));
  let btn=stackTrash[kind];
  if(!want){ if(btn) btn.remove(); return; }
  if(!btn){
    btn=document.createElement('button');
    btn.type='button';btn.className='v7-stack-trash';btn.dataset.stackTrash=kind;btn.innerHTML=STACK_TRASH_SVG;
    btn.title=kind==='errors'?'清掉全部报错卡（要你决定的当作「取消」；公告算已读）':'清掉所有已经结束的任务卡（还在生成的留着；图都在「记录与恢复」里）';
    btn.setAttribute('aria-label',kind==='errors'?'清掉全部报错卡':'清掉已结束的任务卡');
    // ⚠ 吃掉按下 / 点击：不然会连带触发卡片自己的展开、拖动、右滑
    ['pointerdown','mousedown'].forEach(t=>btn.addEventListener(t,ev=>ev.stopPropagation()));
    btn.addEventListener('click',ev=>{
      ev.preventDefault();ev.stopPropagation();
      // ⚠ 不弹「清掉了 N 张」：提示本身也是报错堆里的一张卡，刚清完又冒一张（10-18 深夜实测）
      if(kind==='errors')clearAllErrorCards();else clearFinishedTasks();
    });
    stackTrash[kind]=btn;
  }
  if(btn.parentElement!==top) top.appendChild(btn);
}
updateStackPositions();
// 窗口大小变化时重新计算位置
window.addEventListener('resize', () => {
  updateStackPositions();
});

// ── 添加任务(入场动画 + 成功反馈) ──
function addTask(task){
  taskList.unshift(task);                 // 新任务放数组头 = 堆叠顶部
  const el = renderTaskEl(task);
  tasksEl.insertBefore(el, tasksEl.firstChild);
  tcur = 0;                               // 视图切到新任务
  buildPreview(el, task);
  // ⚠ 必须调一次：renderTaskEl 里那行操作行是【裸 HTML 没有事件】的，
  //   绑定统一在 syncTaskActions 里做（以前绑在 buildPreview 里，重画后就丢了）。
  syncTaskActions(el, task);

  // 入场: 起点在主卡下方(被遮住), 滑出到位
  el.classList.add('entering');
  setTasks();
  el.addEventListener('animationend', function onEnd(){
    el.removeEventListener('animationend', onEnd);
    el.classList.remove('entering');
    el.classList.add('flash');            // 添加成功反馈: 描边闪一下
    setTimeout(() => el.classList.remove('flash'), 620);
    setTasks();                           // 动画结束后接管 transform
  }, { once: true });

  // 到点自动消失
  if(Number(task.life)>0) task.timer = setTimeout(() => removeTask(task.id), task.life);
  // ⚠ 任务栏变了，记录卡里"在不在任务栏"的状态也要跟着变。
  //   （原来是 renderHistoryCardFace → 白扫整个缓存目录，2026-09-30 删掉；
  //     记录卡本来就是事件驱动的，广播一下它自己会重读。）
  // ⭐ 记录与恢复卡（2026-09-30）：点下计算【那一刻】就要出现在记录里，
  //   状态是「生成中」。用户的原话是"点下计算整张画布立刻出现在一级和二级"，
  //   所以这里不能等算完才写 —— cacheSaveTask 本来就是增量写，
  //   算完会再调一次补结果（它靠 task._cachedFiles 跳过已经写过的图）。
  //   ⚠ 只有缓存类任务才记：链路验证那种不进记录。
  //   ⚠ 不 await：写盘慢不该拖住任务卡入场。失败了 cacheSaveTask 自己会记日志。
  if(typeof cacheScheduleRecordsStart==='function') cacheScheduleRecordsStart(task);
  return task;
}

// 点下计算立刻落一条「生成中」记录 + 抓整画布小图。
// 拆出来是为了：① addTask 里不 await 拖慢入场；② 整画布抓图是可选能力，
// 插件没 Reload 时这里要静默退回选区缩略图，不能报错。
function cacheScheduleRecordsStart(task){
  if(!task || !isCachedKindSafe(task.kind)) return;
  if(!cacheAvailable()) return;
  // ⭐ 2026-10-19（docs/251 第七节，用户同意一起修）：从缓存恢复回来的卡（启动恢复 / 记录卡「放回任务栏」）——
  //   盘上本来就有这一单，只把 meta 记成「在任务栏」（「放回任务栏」靠的就是这一下）。
  //   原来这里照新任务那样走：cacheSaveTask 把这单每张图从盘上读出来再原样写回去；
  //   cacheCanvasThumb 还用 PS【现在】的画面盖掉这条记录当时那张整画布小图。
  if(task.restoredFromCache){
    cacheSetTaskbar(task,true).then(broadcastRecordsChanged,broadcastRecordsChanged);
    return;
  }
  // ⚠⚠ 还不知道是哪个 PS 文档时【先不写】（2026-09-30 修，docs/96 缺陷 2）：
  //   多数任务是先建卡、后抓图，建卡那一刻没有文档名/docId。以前照写不误 →
  //   项目名被定成「未保存文档-未知」且再也不改，所有新计算挤进同一个项目，
  //   检查点（抓图后才算项目名）也永远配不上。
  //   现在只挂个标记，等 updateTask 收到文档信息时再补调这里（见 updateTask）。
  //   代价：记录卡里的「生成中」要等抓图完成才出现（用户已同意），任务卡不受影响。
  if(!task.cacheProject && !cacheTaskHasSource(task)){ task._recordsStartPending=true; return; }
  task._recordsStartPending=false;
  // 先算 cacheProject / cacheRunId，再写。⚠ 这两个值原来只在 cacheSaveTask 里算，
  //   不提前算的话这里写的文件夹和算完补写的那次对不上，记录会裂成两条。
  try{
    if(!task.cacheProject) task.cacheProject = cacheScopedProject(cacheProjectName(task));
    if(!task.cacheRunId) task.cacheRunId = cacheStamp(task.startedAt)+'-'+task.id;
  }catch(_){ return; }
  // 整画布小图：异步、不阻塞。写完再广播一次。
  cacheCanvasThumb(task).then(function(){
    broadcastRecordsChanged();
  }, function(){});
  cacheSaveTask(task).then(function(){
    broadcastRecordsChanged();
  }, function(){
    broadcastRecordsChanged();
  });
}
function isCachedKindSafe(kind){
  if(window.V7RecordsCore && typeof V7RecordsCore.isCachedKind==='function') return V7RecordsCore.isCachedKind(kind);
  return ['generation','glow','dlss','matting','segment','sam2'].includes(String(kind||''));
}
// 整画布小图：长边 512 的 JPEG，写成 canvas_thumb.jpg。
// ⚠ 这是【可选】能力 —— PS 插件没 Reload 时没有 ps.doc.canvasThumb 这个动作，
//   退回用任务自己的选区缩略图（就是任务卡背景那张），一样能显示，只是范围小。
// ⚠ 抓图会走 UXP 保护区（executeAsModal），失败绝不冒泡到界面上 ——
//   抓不到小图不该让这次生成失败。
async function cacheCanvasThumb(task){
  if(!task || !task.cacheProject || !task.cacheRunId) return false;
  if(task._canvasThumbWritten) return true;
  const cache = window.uiwin && window.uiwin.cache;
  if(!cache || typeof cache.writeFile!=='function') return false;
  const docId = task.sourceDocId!=null ? task.sourceDocId : (task.captureSnapshot&&task.captureSnapshot.docId);
  if(docId==null) return false;                      // 没有文档来源，无从抓整画布
  // ⚠ 走仓库既有的 linkQueue（全站统一的桥入口），不要另造一个 window.V7UxpBridge ——
  //   那种"看着对、其实没定义"的判断会让整段永远静默 return（本项目最常见的故障形态）。
  let result=null;
  try{
    result = await new Promise((resolve,reject)=>{
      linkQueue('ps.doc.canvasThumb',{docId:String(docId),maxEdge:512},{after:resolve,afterError:reject}).catch(reject);
    });
  }catch(error){
    // 插件没 Reload / 没有这个动作 → 静默退回选区缩略图，不报错。
    logRecordsDiag('整画布小图不可用，已退回选区缩略图：'+String(error&&error.message||error));
    return false;
  }
  const base64 = result && (result.base64||result.data||result.image);
  if(!base64) return false;
  let bytes;
  try{ bytes = base64ToBytes(String(base64)); }
  catch(error){ logRecordsDiag('整画布小图解码失败：'+String(error&&error.message||error)); return false; }
  if(!bytes || !bytes.length) return false;
  try{
    const written = await cache.writeFile(task.cacheProject, task.cacheRunId, 'canvas_thumb.jpg', bytes);
    if(written && written.ok===true){ task._canvasThumbWritten=true; return true; }
    logRecordsDiag('整画布小图写入失败：'+String(written&&written.error||''));
  }catch(error){
    logRecordsDiag('整画布小图写入失败：'+String(error&&error.message||error));
  }
  return false;
}
// ⚠⚠ 2026-10-06 审查修：这里原来还有【第二份】base64ToBytes ——
//   和文件下方那份（带"大图别用 atob 再 split"注释的）同名、同义、同一个 script 块。
//   JS 函数声明会提升，**后声明的那份覆盖前面这份** ⇒ 这一份从写下来那天起就是死代码。
//   ⚠ 同名函数重复定义【不报错、不警告】，只是静默用后一个 —— 加函数前先 grep 名字。
//   ⇒ 已删，只留下方那一份。
// 记录卡靠这个事件刷新自己。没有监听者时它什么都不做 —— 不报错。
function broadcastRecordsChanged(){
  try{ window.dispatchEvent(new CustomEvent('wheelchair:records-changed')); }catch(_){}
}
// 「正在备份检查点…」「正在传回图像…」这类【过程提示】。
// 用现成的 L1 胶囊（addErrorCard，指定时长、返回关闭把手），不另造一套。
// ⚠ 它返回 {close}；调用方拿回执后必须 close，否则胶囊会赖在界面上。
// ⚠ 拿不到报错堆时返回一个空壳 close —— 调用方就不用写判空。
function recordsToast(title,level,durationMs){
  const noop={close:()=>{}};
  try{
    if(typeof addErrorCard!=='function') return noop;
    const handle=addErrorCard({severity:'L1',level:level||'info',title:String(title||''),duration:Number(durationMs)||0});
    return handle&&typeof handle.close==='function'?handle:noop;
  }catch(_){ return noop; }
}
function logRecordsDiag(message){
  try{ if(typeof addLinkLog==='function') addLinkLog({direction:'AI',level:'info',message:'[记录] '+String(message||'')}); }catch(_){}
}

// 原地更新任务卡，不重建主卡或详情滚动容器。
function updateTask(taskId, patch={}){
  const task=taskList.find(t=>String(t.taskId||t.id)===String(taskId)||String(t.id)===String(taskId));
  if(!task) return null;
  const previousProgress=taskProgressSignature(task);
  Object.assign(task,patch||{});
  // 建卡时还不知道文档、推迟了的「生成中」记录：文档信息一到就补写（见 cacheScheduleRecordsStart）。
  //   生成/抠像/分割/指哪抠哪/辉光拿到抓图结果都经过这里，所以挂一处就够。
  if(task._recordsStartPending && cacheTaskHasSource(task)) cacheScheduleRecordsStart(task);
  const progressChanged=previousProgress!==taskProgressSignature(task);
  const el=tasksEl.querySelector('.task[data-task="'+task.id+'"]');
  if(el){
    const pct=Math.max(0,Math.min(100,Number(task.pct)||0));
    el.classList.toggle('done',taskIsDone(task.status));
    el.classList.toggle('failed',task.status==='failed');
    el.classList.toggle('running',task.status==='running');
    const icon=el.querySelector('.t-ic'), name=el.querySelector('.t-name'), out=el.querySelector('.t-pct'), fill=el.querySelector('.t-fill'), sub=el.querySelector('.t-sub');
    // 2026-10-22（docs/263 §1.5）：task.icon 现在是 ICON 的矢量名（hourglass/check/close/stop…），
    //   不再是 emoji。⚠ .t-ic 目前 display:none（2026-09-13 起不显示图标），所以这里只为了保证
    //   「以后要显示时能直接显示正确的图标」+ 不再往 DOM 里塞 emoji 字符。
    if(icon){ if(window.ICON) ICON.set(icon, task.icon||'hourglass', 15); else icon.textContent=''; }
    if(name) name.textContent=task.label||'生成任务';
    if(out) out.textContent=taskStatusText(task,pct);
    if(fill) renderTaskProgress(fill,task,progressChanged);
    // ⭐ 2026-10-19：有云端活在跑时，底栏那行字由状态标注接管（「校色 3/6 · 第 4 张 上传 46%」），跑完交还 task.sub
    if(sub){ const live=(typeof jobView!=='undefined'&&jobView)?jobView.summary(task):''; sub.textContent=live||task.sub||''; sub.classList.toggle('t-sub-live',!!live); }
    if(Object.prototype.hasOwnProperty.call(patch,'sourceImg')){
      if(task.sourceImg){
        const safeSrc=String(task.sourceImg).replace(/["\\\r\n]/g,'');
        el.style.backgroundImage='linear-gradient(180deg, hsl(var(--card-h, 220 28%) 6% / calc(.62 * var(--ui-bg-opacity,1))), hsl(var(--card-h, 220 28%) 6% / calc(.35 * var(--ui-bg-opacity,1))) 42%, hsl(var(--card-h, 220 28%) 6% / calc(.52 * var(--ui-bg-opacity,1))))';
        el.style.backgroundSize='cover';
        el.style.backgroundPosition='center';
        const oldLayer=el.querySelector('.task-source-layer');
        if(oldLayer){
          const nextLayer=document.createElement('div');
          nextLayer.className='task-source-layer task-source-next';
          nextLayer.style.backgroundImage='url("'+safeSrc+'")';
          oldLayer.insertAdjacentElement('afterend',nextLayer);
          requestAnimationFrame(()=>nextLayer.classList.add('reveal'));
          setTimeout(()=>{if(oldLayer.isConnected)oldLayer.remove();if(nextLayer.isConnected)nextLayer.classList.remove('task-source-next','reveal');},430);
        }
        el.classList.add('has-bg');
        // ⚠ 2026-10-22：任务卡不再按亮度翻深字（方案 C，见 04-tasks.css）
        if(window.BG&&window.BG.themeColorFromDataUrl){
          window.BG.themeColorFromDataUrl(safeSrc).then(c=>{
            if(c) el.style.setProperty('--glow-hsl',c.h+' '+c.s+'% '+c.l+'%');
          });
        }
      }
    }
    // ⭐ 2026-09-13：缩略图那排也要在【图层对照表变了】的时候重画 ——
    //   每一格的「传回」按钮是靠 psLayerByShot 判断要不要换成「替换/增益」的，
    //   以前只在 patch.shots 时重画，所以传回成功后那一格还挂着「传回」，能再点一次。
    if(patch.shots || Object.prototype.hasOwnProperty.call(patch,'psLayerByShot')) buildPreview(el,task);
    else if(Object.prototype.hasOwnProperty.call(patch,'cloudSteps')){
      // ⭐ 2026-10-22：采样步数就地改（不重画整排缩略图）；还没有那一格 / 步数刚出现或消失 ⇒ 整排重画一次
      const slot=el.querySelector('[data-pv-steps]'), html=taskStepsHtml(task);
      if(slot&&html){ const box=document.createElement('div'); box.innerHTML=html; slot.replaceWith(box.firstElementChild); }
      else if(!!slot!==!!html) buildPreview(el,task);
    }
    // ⭐ 操作行(提前结束 / 传回 N)跟着状态走。内容没变时它自己会直接返回，不动 DOM。
    syncTaskActions(el,task);
    // ⭐ 指哪抠哪的三候选挑选条（2026-09-14 深夜）。同样是"内容没变就不动 DOM"。
    syncTaskPick(el,task);
  }
  setTasks();
  return task;
}

function updateGenerationTask(taskId, patch={}){
  const next=Object.assign({},patch);
  if(next.status==='done'){
    const previous=taskList.find(t=>String(t.taskId||t.id)===String(taskId)||String(t.id)===String(taskId));
    if(previous&&!previous.completedAt)next.completedAt=Date.now();
  }
  if(next.error && !next.errorInfo) next.errorInfo=taskErrorInfo(next.error,next.stage,next.errorCode);
  if(next.errorInfo && typeof next.errorInfo==='object') next.errorInfo=taskErrorInfo(next.errorInfo,next.errorInfo.stage,next.errorInfo.code);
  if(next.status==='done') next.icon='check';
  // ⚠ 必须在改写 next.sub 之前把真实原因取出来存好。
  //   下面任务卡那行字会被换成短状态，缩略图和报错卡都还要用原文。
  let failReason='';
  if(next.status==='failed'){
    next.icon='close';
    failReason=String(next.error||(next.errorInfo&&next.errorInfo.message)||next.sub||'任务失败');
    // ⭐ 任务卡只说"哪一步黄了"，不说"为什么"(2026-09-11)。
    //   原因一律去报错卡 —— 任务卡那行字只有一行高、还会被截断，
    //   以前把整段报错塞进去，结果是既看不全、又没地方放现场信息。
    //   ⚠ 原文没丢：errorInfo.message 里留着完整的，报错卡和缩略图都从那儿取。
    if(next.sub!==undefined||next.error){
      const st=(window.ERR&&ERR.stageLabel(next.stage||(next.errorInfo&&next.errorInfo.stage)))||'';
      next.sub='失败'+(st?' · '+st:'')+'（详情看报错卡）';
    }
    // 整体请求可能在逐张进度回报前就失败；把所有尚未完成的缩略图同步为错误态，
    // 这样右滑预览不会把失败任务误显示成仍在等待。
    //
    // ⚠⚠⚠ 2026-10-09（docs/189）：这里原来只放过 `shot.error` ——
    //   **已经算完的图（shot.done）也会被改成 done:false + imgId 清空**，
    //   等于"一张图出事，整批已完成的图全丢"。
    //
    //   为什么旧版没暴露：旧版走到这里的条件是"整批一张都没成功"
    //   （main.js 里 `if(!ordered.length) throw`），那时候确实没有已完成的图可毁。
    //   现在 11251 那个 TypeError（已修）让"有 9 张成功"也能走到这，
    //   于是这条【一直存在但爬不出来】的路被踩出来了。
    //
    //   ⇒ 语义应该是：任务失败时【只把还没成功的标失败】，
    //     已经成功的原样保留 —— 用户已经拿到的成果不该被抹掉。
    if(!next.shots){
      const task=taskList.find(t=>String(t.taskId||t.id)===String(taskId)||String(t.id)===String(taskId));
      if(task&&Array.isArray(task.shots)){
        const reason=failReason;
        next.shots=task.shots.map(shot=>(shot&&(shot.error||shot.done))?shot:Object.assign({},shot||{},{done:false,error:reason,errorInfo:taskErrorInfo(reason,'generate','AI_TASK_FAILED'),imgId:''}));
      }
    }
  }
  if(next.status==='cancelled') next.icon='stop';
  const task=updateTask(taskId,next);
  // ⭐ 主链路唯一的报错出口(2026-09-11)。
  //   为什么钉在这里而不是在各个失败点分别弹：主链路的失败点有十几个
  //   (抓取/参数/提交/生成/还原/传回各自都有)，逐个去加必然漏，
  //   而漏掉的那个就又变成"只有一条红字、查不出原因"。
  //   所有失败最终都会流经 updateGenerationTask(status:'failed')，堵这一个口就全覆盖。
  //   ⚠ _errorReported 是必须的：同一个任务会被反复 update，不闸住会弹好几张一样的卡。
  //   ⚠ 从缓存恢复回来的历史任务不弹 —— 那是上次的旧账，不是刚发生的事。
  if(task && window.ERR && !task.restoredFromCache){
    if(next.status==='failed' && !task._errorReported){
      task._errorReported=true;
      const info=task.errorInfo||{};
      ERR.report(next.errorCode||info.code||'AI_TASK_FAILED',{
        message:failReason,
        raw:info.raw&&info.raw.message!==info.message?String(info.raw.message||''):'',
        stage:next.stage||info.stage,
        taskId:String(taskId||''),
        // ⚠ 现场按任务种类给。工具类任务（抠像/人体解析/指哪抠哪）没有
        //   模型/比例/张数/提示词这些东西，照生成那套填会得到一排空行 ——
        //   空行比没有更让人以为"读不到"。
        // ⚠ 三种工具任务的现场是同一套（档位/抓图尺寸/来源文档/选区），
        //   所以用 TOOL_TASK_KINDS 一次包住，别写成三个 || —— 以后再加一种外挂能力
        //   只改那个数组，不用回来这儿补（散落的判断必然漏）。
        context: TOOL_TASK_KINDS.indexOf(task.kind)>=0
          ? {
              '用的档位':task.mattingTierName||'', '抓图尺寸':task.mattingSize||'',
              '来源文档':task.sourceDocName||'',
              '选区':task.sourceSelection?(task.sourceSelection.width+'×'+task.sourceSelection.height):''
            }
          : {
              '模型':task.model||'', '尺寸':task.size||'', '比例':task.aspectRatio||'',
              '张数':task.batch||'', '来源文档':task.sourceDocName||'',
              '提示词':task.prompt?String(task.prompt).slice(0,40)+(String(task.prompt).length>40?'…':''):''
            }
      });
    }
    // 一批里挂了几张但还有成功的 —— 按 2026-09-11 定的尺度走 L1，不打断人。
    if(next.status==='done' && Array.isArray(task.errors) && task.errors.length && !task._partialReported){
      task._partialReported=true;
      const okCount=(task.outputs||[]).length, total=okCount+task.errors.length;
      ERR.report('AI_PARTIAL_FAILED',{
        title:'这批有 '+task.errors.length+' 张没出来（成了 '+okCount+'/'+total+'）',
        message:task.errors.map(x=>x&&x.message).filter(Boolean).slice(0,3).join('；'),
        stage:'generate', taskId:String(taskId||'')
      });
    }
    // ⭐ 遥测：任务终态（2026-10-01）。
    //   挂在这里而不是各处调用点 —— updateGenerationTask 是任务状态的唯一出口，
    //   堵这一个口就全覆盖（跟上面报错出口同一个道理）。
    //   ⚠ _telemetrySent 必须闸住：同一个任务会反复 update，不闸会重复上报。
    //   ⚠ 从缓存恢复的历史任务不报：那是上次的旧账，不是刚发生的事。
    if(!task._telemetrySent && !next.restoredFromCache && window.V7Telemetry &&
       (next.status==='done'||next.status==='failed'||next.status==='cancelled')){
      task._telemetrySent=true;
      try{
        const finalStatus=next.status;
        const started=Number(task.startedAt)||0, ended=Number(task.completedAt)||Date.now();
        const okCount=Array.isArray(task.outputs)?task.outputs.length:0;
        // 结果分三档：全成功 / 部分成功 / 全失败 —— 比布尔值信息量大得多
        let result=finalStatus;
        if(finalStatus==='done'){
          const badCount=Array.isArray(task.errors)?task.errors.length:0;
          result=badCount?(okCount?'partial':'failed'):'success';
        }
        V7Telemetry.task({
          feature:String(task.kind||'generation'),
          provider:String(task.connectionSlot||task.provider||''),
          modelType:String(task.model||''),
          size:String(task.size||task.mattingSize||''),
          aspectRatio:String(task.aspectRatio||''),
          batchSize:Number(task.batch)||0,
          result:result,
          // ⚠ 只报耗时档，不报精确毫秒 —— 精确耗时能指纹化
          elapsedMs:started&&ended>started?(ended-started):0,
          // 错误类别用错误码，不带原文（原文在报错卡里）
          errorCategory:finalStatus==='failed'?String(next.errorCode||(task.errorInfo&&task.errorInfo.code)||''):null
        });
        // 成功了就告诉遥测"上次报的错这次没复现" —— 这是衡量你写的报错方案管不管用的关键信号
        if(result==='success'||result==='partial') V7Telemetry.heal(String(task.kind||'generation'));
      }catch(_){ /* 遥测绝不能影响任务本身 */ }
    }
  }
  // 落盘。从缓存恢复回来的任务不再回写，免得把自己覆盖一遍。
  // ⚠⚠ 2026-09-13 改：不能再用一个布尔值(cacheSaved)把落盘永久闸住。
  //   老写法的后果：「提前结束」时传回成功把任务写成终态、落一次盘、闸门关死，
  //   后台【算完的那几张永远写不进缓存】—— 重载后只剩前半批（用户实测撞到）。
  //   现在按"有图的张数 + 状态"当签名：多出图就补存一次。
  //   cacheSaveTask 内部跳过已经写过的图，所以补存只多一次几 KB 的 meta 写入。
  //
  // ⚠⚠⚠ 2026-10-05 修（用户实测报的「生成中闪退，已完成的图全丢」）：
  //   上面那句"多出图就补存一次"以前【只在终态生效】—— 外面套着 aiTaskIsTerminal。
  //   于是从"发出请求"到"整批跑完"这整段时间里，磁盘上【零写入】：
  //   每张图还原完只是 window.IMG.putFromCanvas 登记进内存管家，
  //   那是纯内存、没有磁盘影子。崩在"第 5 张已出好、第 6 张在算"的瞬间，
  //   前 5 张全没，重启只剩一个 input.png 和一份空 meta。
  //   ⇒ 现在只要这批里【已经落袋了图】就写。签名闸门（张数+状态）保证
  //     它只在张数真的变了时才触发，不会每个进度事件都写一遍。
  //   ⚠ 为什么不用"跑完再写"折中：进度回调本来就是逐张来的，
  //     而崩溃恰恰发生在中途 —— 只在终态写等于没写。
  if(task && !task.restoredFromCache && typeof aiTaskIsTerminal==='function' &&
     (aiTaskIsTerminal(task) || (task.shots||[]).filter(s=>s&&s.imgId).length>0)){
    const sig=(task.shots||[]).filter(s=>s&&s.imgId).length+'/'+String(task.status||'');
    if(task._cacheSig!==sig){
      task._cacheSig=sig;
      // ⭐⭐ 2026-09-30 修：落盘完【必须广播】。
      //   这里原来只写盘、不通知任何人 —— 而记录卡是【事件驱动】的：
      //   它只在收到 wheelchair:records-changed 时重读盘。唯一的发车点是
      //   cacheScheduleRecordsStart（点下计算那一刻）—— 于是卡面永远停在「生成中」，
      //   盘上 meta.json 已经是 status:"done"。（用户实测：关卡再开就好了）
      // ⚠ 成功 / 失败都要广播：写盘失败时 meta 可能已经局部更新，而且“卡面刷不刷”
      //   本来就不应该跟写盘结果绑定。
      const announce=()=>{ if(typeof broadcastRecordsChanged==='function') broadcastRecordsChanged(); };
      cacheSaveTask(task).then(announce,announce);
      // ⭐ 补一次整画布小图：它原来只在【点下计算那一刻】试一次，失败就永远没了。
      //   那一刻最容易失败（插件刚连上 / 还在抢 PS 保护区），而 canvas_thumb.jpg
      //   是记录卡封面的第一顺位 —— 缺了封面就只能退到选区图。
      //   ⚠ 内部自带 _canvasThumbWritten 幂等，已经写过的不会再抢一次 PS。
      //   ⚠ 失败静默：抢不到小图不该让这次生成变成失败。
      if(typeof cacheCanvasThumb==='function'){
        Promise.resolve().then(()=>cacheCanvasThumb(task)).then(ok=>{ if(ok) announce(); },()=>{});
      }
    }
  }
  return task;
}

// ── 移除任务(向下滑出) ──
// ═══ 生成缓存 ═══
// 结构: <缓存根>/<PS项目名>/<每次计算>/{meta.json, input.png, output_N.png, thumb_N.jpg, prompt.txt}
// 目的: 算过的任务重启后还在，测界面不用再花钱调一次真实接口。
//
// ⚠ 缓存根现在写死在项目文件夹下，**正式发布前必须改成用户自选目录**(docs/10)。
const CACHE_META_VERSION = 1;
function cacheAvailable(){ return !!(window.uiwin && window.uiwin.cache); }
function cacheNamespaceId(){
  return window.WHEELCHAIR_STORAGE
    ? window.WHEELCHAIR_STORAGE.namespaceId() : 'legacy';
}
function cacheScopedProject(project){
  const value=String(project||'');
  if(window.WHEELCHAIR_STORAGE && window.WHEELCHAIR_STORAGE.ownsCacheProject(value)) return value;
  return window.WHEELCHAIR_STORAGE
    ? window.WHEELCHAIR_STORAGE.cacheProject(value) : value;
}
function cacheOwnsEntry(entry){
  if(!entry || !entry.meta) return false;
  if(window.WHEELCHAIR_STORAGE && !window.WHEELCHAIR_STORAGE.ownsCacheProject(entry.project)) return false;
  return entry.meta.namespaceId===cacheNamespaceId();
}

// 文件夹名清洗: Windows 非法字符、结尾空格、开头的点都要处理，否则建不出目录。
function cacheSafeSegment(name){
  const cleaned = String(name||'').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').replace(/[\s.]+$/,'').replace(/^\.+/,'').slice(0,80).trim();
  return cleaned || '未命名';
}
// PS 项目名。⚠ 未保存的文档都叫"未标题-1"，必须带上 docId，
//   否则几个不同的未保存项目会全挤进同一个文件夹。
// 任务是否已经知道自己来自哪个 PS 文档（有文档名或 docId）。判断口径与 cacheProjectName 一致。
function cacheTaskHasSource(task){
  const snap = task && task.captureSnapshot;
  const name = String((task && task.sourceDocName) || (snap && snap.docName) || '').trim();
  const id = (task && task.sourceDocId != null) ? task.sourceDocId : (snap && snap.docId);
  return !!name || id != null;
}
function cacheProjectName(task){
  const snap = task && task.captureSnapshot;
  const name = String((task && task.sourceDocName) || (snap && snap.docName) || '').trim();
  const id = (task && task.sourceDocId != null) ? task.sourceDocId : (snap && snap.docId);
  if(name) return cacheSafeSegment(name);
  return cacheSafeSegment('未保存文档-' + (id == null ? '未知' : id));
}
function cacheStamp(ms){
  const d = new Date(Number(ms)||Date.now()), p=n=>String(n).padStart(2,'0');
  return d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'-'+p(d.getHours())+p(d.getMinutes())+p(d.getSeconds());
}
// 传回只需要文档、选区这些小字段。⚠ 绝不把 inputImageBase64/sourceImageBase64 写进
//   meta.json —— 那是几十 MB 的字符串，写进去等于把 docs/21 的教训再犯一遍。
function cacheSlimSnapshot(snap){
  if(!snap) return null;
  return {docId:snap.docId, docName:snap.docName, selection:aiClonePlain(snap.selection),
          antiMode:snap.antiMode, capturedAt:snap.capturedAt, captureId:snap.captureId,
          width:snap.width, height:snap.height, mime:snap.mime};
}
function cacheMetaFromTask(task, project, runId, inTaskbar){
  return {
    version:CACHE_META_VERSION, savedAt:Date.now(), project:project, runId:runId,
    repository:'cache.v1', namespaceId:cacheNamespaceId(),
    projectId:task.productProjectId||undefined,
    migration:task.migration?aiClonePlain(task.migration):undefined,
    inTaskbar:!!inTaskbar,
    taskId:String(task.taskId||''), kind:task.kind, label:task.label, icon:task.icon,
    colorToolRunId:String(task.colorToolRunId||''),preserveGeneratedAppearance:task.preserveGeneratedAppearance===true,
    toolParams:['glow','dlss'].includes(task.kind)?aiClonePlain(task.toolParams):undefined,
    provider:task.provider, model:task.model, size:task.size, aspectRatio:task.aspectRatio,
    // ⭐ 记录与恢复卡（2026-09-30）：算力通道 + 金额快照。
    //   connectionSlot 区分 grs 和自定义服务商（provider 只有 aji/momo/other，不够用）。
    //   cost 在【完成那一刻】写死：以后改价目表不动旧账，这是用户定的规矩。
    //   ⚠ 只在任务真到终态时才写 cost —— 半路的记录卡要显示「生成中」，不是金额。
    computeSource:task.computeSource||undefined,
    connectionSlot:task.connectionSlot||undefined,
    channelLabel:task.channelLabel||undefined,
    cost:(function(){
      if(!window.V7RecordsCore||typeof V7RecordsCore.costSnapshot!=='function') return undefined;
      if(!(taskIsDone(task.status)||task.status==='failed'||task.status==='cancelled')) return undefined;
      try{ return V7RecordsCore.costSnapshot(task); }catch(_){ return undefined; }
    })(),
    batch:task.batch, prompt:task.prompt, antiMode:Number(task.antiMode)||0,
    workflowParameters:aiPersistentParameters(task.workflowParameters,task),workflowPresetId:String(task.workflowPresetId||''),
    presetId:task.presetId,presetTitle:task.presetTitle,presetVersion:task.presetVersion,protocol:task.protocol,
    status:task.status, pct:Number(task.pct)||0, sub:task.sub, startedAt:task.startedAt,
    // ⭐ 2026-10-19（docs/250 第 20 条）：失败在哪一步。重启恢复回来的任务 errorInfo 是空的，「重跑」按钮靠它判断给不给。
    failedStage:task.status==='failed'?(String(task.errorInfo&&task.errorInfo.stage||task.failedStage||'')||undefined):undefined,
    completedAt:task.completedAt||undefined,
    sourceDocId:task.sourceDocId, sourceDocName:task.sourceDocName,
    sourceSelection:task.sourceSelection?aiClonePlain(task.sourceSelection):undefined,
    mattingTierName:task.mattingTierName||undefined, mattingSize:task.mattingSize||undefined,
    captureSnapshot:cacheSlimSnapshot(task.captureSnapshot),
    // Photoshop 图层信息。⚠ 必须存: 重启后恢复的任务要靠它继续做 hover 联动，
    //   否则恢复回来的卡片划上去没反应。图层可能已经不在了，用的时候静默降级。
    psLayerIds:Array.isArray(task.psLayerIds)?task.psLayerIds:[],
    // ⚠ 对照表必须一起存，否则重启后恢复的任务 hover 会错位(或干脆没反应)
    psLayerByShot:task.psLayerByShot||{},
    psGroupId:task.psGroupId!=null?task.psGroupId:null,
    psGroupName:task.psGroupName||'',
    psDocId:task.psDocId!=null?task.psDocId:null,
    // ⭐ 盖印判定基线（2026-09-14）。⚠ 必须存：不存的话重启后恢复的任务没有基线，
    //   「盖印后自动收起」对它就完全不生效（eligible() 会直接排除）。
    //   ⚠ 只在真有基线时才写这个字段 —— 写成空数组会让判定退化成误判制造机。
    stampBaseline:Array.isArray(task.stampBaseline)?task.stampBaseline:undefined,
    hasInput:!!task.sourceImgId,
    // ⭐⭐ 2026-10-05（docs/143 §五）：任务级「显示哪一版」。
    //   ⚠ 必须存进 meta.json：不存的话重启后小眼睛回到默认（校色版），
    //     而用户明明切到了底版 —— 他会以为"切了没用/软件记不住"。
    //   ⚠ 存在任务级（不是每张 shot 上）—— 用户拍板"整个任务卡一个开关"。
    colorVersion:taskColorVersion(task),
    // C01 R4/R9：这一单带了几张参考图（缓存里是 ref_1..N）。恢复回来的任务没有 referenceAssets，沿用上次记的数。
    referenceCount:Array.isArray(task.referenceAssets)?task.referenceAssets.length:(Number(task.referenceCount)||0),
    shots:(task.shots||[]).map((s,i)=>({
      index:i, done:!!(s&&s.done), error:(s&&s.error)||'',
      restoreState:(s&&s.restoreState)||'', hasImage:!!(s&&s.imgId),
      // B01 第 1 步：这一张有没有存校色前的 AI 原图（raw_N.png）。没校色/没对齐的那张没有，读的人别去找。
      hasRaw:!!(s&&s.rawSaved),
      // ⭐⭐ 2026-10-05（docs/143 §二-2.2）：这一张有没有存【底版】base_N.png
      //   （掰正过、没校色）。老任务没有 → 小眼睛置灰、点了弹"缺少文件"。
      //   ⚠ 跟 hasRaw 分开记：两者来源不同（raw 来自 AI 原样，base 来自引擎掰正后），
      //     合成一个字段的话「有 raw 没 base」这种既有任务会被误判成"能切版本"。
      hasBase:!!(s&&s.baseSaved),
      // ⭐ 2026-10-18：生成时实际用的那种校色（切版本靠它认「自动那一种」=output_N.png）。不存的话重启后又全当成混合
      autoVersion:(s&&s.autoVersion)||'',
      // ⭐ 细节补偿的档位和它贴出来的图层 ID（2026-09-12）。
      //   不存的话重启后角标会消失、换档时也删不掉旧的那层 —— 会越叠越多。
      detailTier:(s&&s.detailTier)||'',
      detailLayerId:(s&&s.detailLayerId!=null)?s.detailLayerId:null,
      // ⭐ 2026-10-05：「应用」贴出来的那层（嵌在底座上）。不存的话重启后再点「应用」删不掉旧的，会越叠越多。
      tweenLayerId:(s&&s.tweenLayerId!=null)?s.tweenLayerId:null,
      tweenStrength:(s&&s.tweenStrength!=null)?s.tweenStrength:null
    }))
  };
}

// 把一次计算落盘。
// ⚠⚠ 2026-09-13 改成【可以补存】（用户实测的 bug）：
//   老写法是"只在任务到终态时调一次"，配合 updateGenerationTask 里那个 cacheSaved 布尔闸门。
//   后果：「提前结束」时传回成功会把任务写成终态并落一次盘，闸门一关，
//   后台【算完的那几张永远写不进缓存】—— 重载后只剩前半批。
//   现在允许反复调用，靠 task._cachedFiles 记住"哪些图已经写过"来避免重复 I/O：
//     · 已经写过的原图/缩略图直接跳过（这是几百 MB 的那部分）
//     · meta.json 每次都重写（几 KB，它要带上最新的 shots / 图层对照表）
//   ⚠ 再加一把在途锁：两个写手同时改同一个 meta.json 会互相盖，
//     所以正在写的时候只记一个"待补写"的标记，写完再补一次。
async function cacheSaveTask(task){
  if(!cacheAvailable() || !task || !['generation','glow','dlss','matting','segment','sam2'].includes(task.kind)) return;
  const currentNamespace=()=>typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy';
  const saveNamespace=currentNamespace();
  const saveEpoch=typeof sourceImageEpoch==='number'?sourceImageEpoch:0;
  if(task.storageNamespaceId && task.storageNamespaceId!==saveNamespace) return;
  task.storageNamespaceId=saveNamespace;
  const assertNamespace=()=>{ if(saveNamespace!==currentNamespace() || saveEpoch!==(typeof sourceImageEpoch==='number'?sourceImageEpoch:0)) throw new Error('存储账号已切换，放弃旧任务写入'); };
  if(task._cacheWriting){ task._cacheDirty = true; return; }
  task._cacheWriting = true;
  if(!task._cachedFiles) task._cachedFiles = new Set();
  const written = task._cachedFiles;
  try{
    const persist=async()=>{
    assertNamespace();
    const project = cacheScopedProject(task.cacheProject || cacheProjectName(task));
    task.cacheProject = project;
    const runId = task.cacheRunId || (task.cacheRunId = cacheStamp(task.startedAt)+'-'+task.id);
    const cache = window.uiwin.cache;
    const enc = new TextEncoder();
    // Cache adapters return a result object instead of throwing for filesystem
    // failures. Treat every non-ok result as a real failure so the task does
    // not claim a file was persisted when it was only attempted.
    const writeChecked = async (operation, label) => {
      assertNamespace();
      const result = await operation();
      assertNamespace();
      if(!result || result.ok !== true) {
        const detail = result && result.error ? ': '+String(result.error) : '';
        throw Object.assign(new Error(String(label || '缓存写入失败') + detail),{cacheKind:result&&result.kind||'',cachePath:result&&result.path||''});
      }
      return result;
    };
    // 输入图(任务卡背景那张)。它是"用户看到的正常原图"，不是抗截断偏移后的输入。
    if(task.sourceImgId && window.IMG.has(task.sourceImgId) && !written.has('input:'+task.sourceImgId)){
      const thumb=new Uint8Array(await window.IMG.thumbBytes(task.sourceImgId));
      await writeChecked(()=>cache.writeFile(project, runId, 'input_thumb.jpg', thumb), '输入图缩略图写入失败');
      const full=new Uint8Array(await window.IMG.fullBytes(task.sourceImgId));
      await writeChecked(()=>cache.writeFile(project, runId, 'input.png', full), '输入图写入失败');
      written.add('input:'+task.sourceImgId);
      // ⭐ 2026-10-16：磁盘上有了 ⇒ 内存紧时这张原图可以放掉、要用再读（image-store.js 的 trimFull，治开久了面板卡死）
      window.IMG.attachLoader?.(task.sourceImgId, ()=>cache.readFile(project, runId, 'input.png'));
    }
    // 每张结果: 原图 + 缩略图都写。
    // ⚠ 缩略图必须一起写: 重启时直接读它，不用把每张 4K 原图重新解码一遍(启动会卡死)。
    // ⚠ key 里带 imgId —— 万一同一格换了图(重试)，imgId 会变，就该重新写一遍。
    for(let i=0;i<(task.shots||[]).length;i++){
      assertNamespace();
      const shot = task.shots[i];
      if(!shot) continue;
      // ⭐⭐⭐ 2026-10-08 修 BUG（docs/170 §一-①、§4.3 不变量 8）——
      //   【这是那个丢数据 bug 的正主】
      //
      //   改之前：这里用的是 `shot.imgId`（= 当前显示的那张）。
      //     而 toggleTaskColorVersion() 切到底版时会把 shot.imgId 换成底版那张，
      //     于是"切到底版之后的下一次保存"就把【底版】写进了 output_N.png ——
      //     校色版从磁盘上消失，重启后切回"校色"读到的也是底版。
      //     实测：meta.colorVersion='base' 的 27 张里【24 张】两个文件字节完全相同；
      //           'colormatched' 的 83 张里只有 9 张（7.2%）—— 相关 12 倍。
      //     缩略图判定佐证：那 24 张里 11 张的缩略图与现在的 output 对不上
      //     （缩略图是保存当时从 output 做的）⇒ output 事后被换过。
      //
      //   改之后：写盘一律认 `autoImgId` —— 它是【生成时自动方式那一张】的证件号。
      //     切版本【只改 shot.imgId（显示用），不碰 autoImgId（存档用）】。
      //
      //   ⚠ 取图的 id 和去重 key 里的 id【必须是同一个】（不变量 8）：
      //     只换取图、不换 key 的话，每切一次版本 key 就变一次 ⇒
      //     每次保存都把同一份内容重写一遍（4K 约 8MB/张，白写、磨硬盘）。
      //   ⚠ 兜底 `||shot.imgId`：老任务 / 中间态可能还没有 autoImgId。
      //     有兜底最坏退回旧行为，不会"一张都不写"（静默失效是这个项目最忌的形态）。
      // ⚠ 自愈兜底（docs/170 §4.3 不变量 8）：autoImgId 为空时补上。
      //   走到这里说明还没写过盘、或者是升级前的老任务。
      //   ⚠ 这只是【最后一道保险】—— 真正第一道在 toggleTaskColorVersion 里（切之前就补）。
      if(!shot.autoImgId && shot.imgId) shot.autoImgId = shot.imgId;
      const autoId = shot.autoImgId || shot.imgId;
      if(!autoId || !window.IMG.has(autoId)) continue;
      const key = 'shot:'+i+':'+autoId;
      if(written.has(key)) continue;
      const n = i+1;
      const full=new Uint8Array(await window.IMG.fullBytes(autoId));
      await writeChecked(()=>cache.writeFile(project, runId, 'output_'+n+'.png', full), '第 '+n+' 张结果写入失败');
      window.IMG.attachLoader?.(autoId, ()=>cache.readFile(project, runId, 'output_'+n+'.png'));   // 同上：能从磁盘读回来了，内存紧时可放
      const thumb=new Uint8Array(await window.IMG.thumbBytes(autoId));
      await writeChecked(()=>cache.writeFile(project, runId, 'thumb_'+n+'.jpg', thumb), '第 '+n+' 张缩略图写入失败');
      written.add(key);
    }
    // ⭐ 2026-10-02 B01 第 1 步：校色/对齐之前的 AI 原图 → raw_N.png（只有真改过的那张才有）。
    //   output_N.png 仍然是校色后的（所见即所得，传回 PS、记录卡都照旧读它，一个字不变）。
    //   ⚠ 写完就从内存释放 —— 它只是给事后对比/补校色用的，留在内存里一批 18 张 4K 就是双倍占用。
    //   ⚠ 单独一圈循环、单独的 key（raw:），跟上面的 output 互不影响：
    //     原图写失败不会让结果图被判成没写，反过来也一样。
    for(let i=0;i<(task.shots||[]).length;i++){
      assertNamespace();
      const shot = task.shots[i];
      if(!shot || !shot.rawImgId || !window.IMG.has(shot.rawImgId)) continue;
      const key = 'raw:'+i+':'+shot.rawImgId;
      if(written.has(key)) continue;
      const raw=new Uint8Array(await window.IMG.fullBytes(shot.rawImgId));
      await writeChecked(()=>cache.writeFile(project, runId, 'raw_'+(i+1)+'.png', raw), '第 '+(i+1)+' 张 AI 原图写入失败');
      written.add(key);
      shot.rawSaved=true;
      window.IMG.release(shot.rawImgId);
    }
    // ⭐⭐ 2026-10-05（docs/143 §二-2.2）：底版 → base_N.png。
    //   底版 = 【掰正过、没校色】的那一张（不是 AI 原样，那个是 raw_N.png）。
    //   ⚠ 两个都要留，别合并：
    //     · raw_N.png  = AI 原样（没掰正、没校色）→ 事后复盘"鬼影是校色造的还是 AI 造的"用
    //     · base_N.png = 掰正过、没校色        → 历史卡显示它、小眼睛切到它
    //     前者位置可能是歪的，后者位置是对的 —— 用户看到的"生成出来的样子"是后者。
    //   ⚠ 单独一圈循环 + 单独的 key（base:），跟 output / raw 互不影响：
    //     底版写失败不该让成品被判成没写（反过来也一样）。
    //   ⚠ 语义：output_N.png 【一个字都不改】（记录卡、传回、历史都读它）——
    //     本次只是【加】一个新文件。docs/143 第十一节最后一条。
    for(let i=0;i<(task.shots||[]).length;i++){
      assertNamespace();
      const shot = task.shots[i];
      if(!shot || !shot.baseImgId || !window.IMG.has(shot.baseImgId)) continue;
      const key = 'base:'+i+':'+shot.baseImgId;
      if(written.has(key)) continue;
      const base=new Uint8Array(await window.IMG.fullBytes(shot.baseImgId));
      await writeChecked(()=>cache.writeFile(project, runId, 'base_'+(i+1)+'.png', base), '第 '+(i+1)+' 张底版写入失败');
      written.add(key);
      shot.baseSaved=true;
      window.IMG.release(shot.baseImgId);
    }
    // ⭐⭐⭐ 2026-10-08（docs/170 §4.3 不变量 2 · 第 2 步）：各版本 → color_<版本>_<n>.png
    //   ⚠ 自动方式那一种【不在这里写】—— 它就是 output_N.png（不变量 2：不重复存）。
    //   ⚠ 单独一圈循环 + 单独的 key：某一版写失败不该让别的版被判成没写。
    //   ⚠ 去重 key 里带 imgId：同一版重算之后 id 会变，就该重写一遍（照 shot: 那条的做法）。
    for(let i=0;i<(task.shots||[]).length;i++){
      assertNamespace();
      const shot = task.shots[i];
      if(!shot || !shot.versions) continue;
      const autoV = shotAutoVersion(task, shot);
      for(const ver of COLOR_VERSIONS){
        if(ver === 'base' || ver === autoV) continue;      // base 与自动方式各有自己的文件名
        const vid = shot.versions[ver];
        if(!vid || !window.IMG.has(vid)) continue;
        const vkey = 'ver:'+ver+':'+i+':'+vid;
        if(written.has(vkey)) continue;
        const bytes = new Uint8Array(await window.IMG.fullBytes(vid));
        await writeChecked(
          ()=>cache.writeFile(project, runId, colorVersionExtraFile(ver, i), bytes),
          '第 '+(i+1)+' 张的'+COLOR_VERSION_LABEL[ver]+'版写入失败');
        written.add(vkey);
        if(!shot.versionSaved) shot.versionSaved = {};
        shot.versionSaved[ver] = true;
      }
    }
    // ⭐ 2026-10-02 融合方案-C01 R4（用户 2026-10-01）：「没点计算 → 临时参考图不落盘；点了计算 → 落盘进缓存」。
    //   这一单带走的参考图原样写成 ref_N.<原格式>（原始字节，不重新编码）。
    //   ⚠ 这里是「点了计算」之后才会走到的地方，所以 R2「关软件不留」和 R4 不冲突：
    //     弹窗里加了没生成的图从来不进这里。
    //   ⚠ 张数记进元数据 referenceCount —— R9「历史卡显示带了几张参考图」要用。
    const refAssets=Array.isArray(task.referenceAssets)?task.referenceAssets:[];
    for(let i=0;i<refAssets.length;i++){
      assertNamespace();
      const asset=refAssets[i];
      if(!asset||!(asset.full instanceof Blob))continue;
      const key='ref:'+i+':'+String(asset.assetId||asset.name||'');
      if(written.has(key))continue;
      const ext=/jpe?g/i.test(asset.mime||'')?'jpg':/webp/i.test(asset.mime||'')?'webp':'png';
      // ⚠ 2026-10-18 深夜（线上 459 次 CACHE_WRITE_FAILED）：参考图读不出来（老版本留下的磁盘文件引用、原文件已被挪走）
      //   只跳过这一张 —— 原来是整个存缓存一起失败，提示词、记录都没写成，而且每更新一次就再失败一次。
      let bytes;
      try{ bytes=new Uint8Array(await asset.full.arrayBuffer()); }
      catch(error){ written.add(key); logRecordsDiag('第 '+(i+1)+' 张参考图读不出来（原文件可能被挪走或改过），这张不存进缓存：'+String(error&&error.message||error)); continue; }
      await writeChecked(()=>cache.writeFile(project, runId, 'ref_'+(i+1)+'.'+ext, bytes), '第 '+(i+1)+' 张参考图写入失败');
      written.add(key);
    }
    if(!written.has('prompt')){
      assertNamespace();
      await writeChecked(()=>cache.writeFile(project, runId, 'prompt.txt', enc.encode(String(task.prompt||''))), '提示词写入失败');
      written.add('prompt');
    }
    await writeChecked(()=>cache.writeMeta(project, runId, cacheMetaFromTask(task, project, runId, true)), '缓存元数据写入失败');
    task.cacheSaved = true;
    // 历史中心是可选模块。隔离渲染、恢复模式或旧版页面没有它时，
    // 不能让已经成功写入的缓存被误报成失败。
    if(typeof historyRecordTask==='function') historyRecordTask(task);
    };
    if(typeof checkpointRuntime!=='undefined'&&checkpointRuntime&&checkpointRuntime.withCacheCapacity){
      let incoming=16384+String(task.prompt||'').length*3;
      const images=[];
      if(task.sourceImgId&&!written.has('input:'+task.sourceImgId))images.push(task.sourceImgId);
      (task.shots||[]).forEach((shot,i)=>{if(shot&&shot.imgId&&!written.has('shot:'+i+':'+shot.imgId))images.push(shot.imgId);});
      // B01：校色前原图也要算进容量（不然「先问够不够地方」就漏算了一半）
      (task.shots||[]).forEach((shot,i)=>{if(shot&&shot.rawImgId&&window.IMG.has(shot.rawImgId)&&!written.has('raw:'+i+':'+shot.rawImgId))images.push(shot.rawImgId);});
      // ⭐ 143：底版（base_N.png）也要算 —— 它跟成品同样大小（都是 4K PNG），
      //   漏算的话「先问够不够地方」会少算一倍，"空间不够"永远问不出来。
      (task.shots||[]).forEach((shot,i)=>{if(shot&&shot.baseImgId&&window.IMG.has(shot.baseImgId)&&!written.has('base:'+i+':'+shot.baseImgId))images.push(shot.baseImgId);});
      // C01 R4：这一单带的参考图（原始 Blob，不在图片管家里，按 Blob 大小直接算）
      (Array.isArray(task.referenceAssets)?task.referenceAssets:[]).forEach((asset,i)=>{if(asset&&asset.full instanceof Blob&&!written.has('ref:'+i+':'+String(asset.assetId||asset.name||'')))incoming+=asset.full.size;});
      if(window.IMG.byteSizes)images.forEach(id=>{const bytes=window.IMG.byteSizes(id);incoming+=bytes.fullBytes+bytes.thumbBytes;});
      await checkpointRuntime.withCacheCapacity(incoming,persist);
    }else await persist();
  }catch(e){
    // 缓存失败不能影响生成本身，只记一笔日志。
    if(/^CHECKPOINT_CAPACITY_/.test(e.code||''))ERR.report(e.code,{message:String(e&&e.message||e)});
    else if(ERR.cacheFailure)ERR.cacheFailure('CACHE_WRITE_FAILED',{kind:e&&e.cacheKind,path:e&&e.cachePath,code:e&&e.code,error:String(e&&e.message||e)});
    else ERR.report('CACHE_WRITE_FAILED',{message:String(e&&e.message||e)});
  }finally{
    task._cacheWriting = false;
    if(task._cacheDirty){
      task._cacheDirty = false;
      if(saveNamespace===currentNamespace()&&saveEpoch===(typeof sourceImageEpoch==='number'?sourceImageEpoch:0)) cacheSaveTask(task).catch(()=>{});
    }
  }
}

// 传回 / 编组之后把最新状态写进缓存。两条路分开走：
//   · 从缓存恢复的历史任务 → 只更新 meta（图片本来就在盘上，重写是白花 I/O）
//   · 本次新算的任务 → 走 cacheSaveTask（它自己跳过已经写过的图）
function cachePersistTask(task){
  if(!cacheAvailable() || !task || !['generation','glow','dlss','matting','segment','sam2'].includes(task.kind)) return;
  if(task.restoredFromCache){ cacheSetTaskbar(task, true).catch(()=>{}); return; }
  cacheSaveTask(task).catch(()=>{});
}

// 只更新"是否还在任务栏"，不重写图片。点 X 和恢复时用。
async function cacheSetTaskbar(task, inTaskbar){
  if(!cacheAvailable() || !task || !task.cacheRunId || !task.cacheProject) return;
  const currentNamespace=typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy';
  if(task.storageNamespaceId && task.storageNamespaceId!==currentNamespace) return;
  try{
    const result = await window.uiwin.cache.writeMeta(task.cacheProject, task.cacheRunId,
      cacheMetaFromTask(task, task.cacheProject, task.cacheRunId, inTaskbar));
    if(!result || result.ok!==true) throw new Error(result?.error || '任务栏状态未写入缓存');
  }catch(e){
    // ⚠ 别静默: 写失败的话，点了 X 的任务下次启动还会自己冒出来，
    //   用户会以为"X 按钮坏了"，而真实原因是这里写盘失败。
    ERR.report('TASKBAR_UPDATE_FAILED',{message:String(e&&e.message||e)});
  }
}

// 启动时把上次还留在任务栏里的任务拉回来。
// ⚠ 只读 meta.json + 缩略图，原图【不加载】—— 看大图或传回时才按需从磁盘拉。
//   否则一开机就把几百 MB 原图全读进内存，等于什么都没优化。
async function cacheRestoreTasks(){
  if(!cacheAvailable()) return;
  const startedNamespace=typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy';
  const stillCurrent=()=>startedNamespace===(typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy');
  let list;
  try{
    list = await window.uiwin.cache.list();
    if(!list || list.ok!==true || !Array.isArray(list.runs)) throw new Error(list?.error || '缓存目录返回的数据不完整');
  }catch(e){ if(stillCurrent()) ERR.report('CACHE_RESTORE_FAILED',{message:String(e&&e.message||e),stage:'list'}); return; }
  if(!stillCurrent()) return;
  // ⭐⭐ 2026-10-06（用户实测：记录卡里有任务永远"生成中"）：僵尸清扫。
  //   启动这一刻不可能有任务真在跑 —— 凡是磁盘 meta 里还写着 运行中/排队/准备中 的，
  //   都是"上次没跑完"（进程被杀/崩，没等到终态落盘）。
  //   ⚠ 以前只在内存恢复里归一化（cacheRestoreOne 的 6497-6510），【不回写磁盘】；
  //     而记录卡只读磁盘 meta → 那些任务永远显示"生成中 X/Y"。
  //   ⇒ 这里按【同一套口径】把 meta 归一化并写回：done/failed + "上次没跑完 · 存下了 X/Y 张"。
  //     规则不另立第二套，免得两处口径漂（这是本项目的硬规矩）。
  //   ⚠ 只扫本账号拥有的记录；写失败不挡启动。
  try{
    const isLive = (window.V7RecordsCore && typeof V7RecordsCore.isLiveStatus==='function')
      ? s=>V7RecordsCore.isLiveStatus(String(s||''))
      : s=>['running','queued','pending','preparing'].indexOf(String(s||''))>=0;
    const liveRuns = list.runs.filter(r=>r && r.meta && cacheOwnsEntry(r)
      && Number(r.meta.version)===CACHE_META_VERSION && r.meta.repository==='cache.v1'
      && String(r.meta.kind||'')!=='checkpoint' && isLive(r.meta.status));
    for(const entry of liveRuns){
      const m = entry.meta;
      const shots = Array.isArray(m.shots) ? m.shots : [];
      const okCount = shots.filter(s=>s && (s.hasImage || s.done)).length;
      const next = Object.assign({}, m, {
        status: okCount ? 'done' : 'failed',
        sub: '上次没跑完 · 存下了 ' + okCount + '/' + shots.length + ' 张',
        completedAt: m.completedAt || m.savedAt || Date.now()
      });
      try{ await uiwin.cache.writeMeta(entry.project, entry.runId, next); }catch(_){ /* 写不回不挡启动 */ }
    }
  }catch(_){ /* 清扫失败不挡启动 */ }
  const wanted = list.runs
    .filter(r=>r && r.meta && r.meta.inTaskbar && Number(r.meta.version)===CACHE_META_VERSION && r.meta.repository==='cache.v1' && cacheOwnsEntry(r))
    .sort((a,b)=>Number(a.meta.startedAt||0)-Number(b.meta.startedAt||0));   // 旧的先加，新的最后 → 堆顶是最新
  let restored=0;
  for(const entry of wanted){
    if(!stillCurrent()) return;
    try{ const result=await cacheRestoreOne(entry); if(stillCurrent() && result!==false) restored++; }
    catch(e){ ERR.report('CACHE_RESTORE_FAILED',{message:String(e&&e.message||e)}); }
  }
  if(!stillCurrent()) return;
  if(restored) aiAddLog('已从缓存恢复 '+restored+' 个任务','info');
  // ⭐ 恢复回来的任务如果带着盖印基线，也要参与「盖印后自动收起」。
  //   ⚠ 不在这里叫的话，重启后那些卡就再也不会自动收起了 ——
  //   而 recordStampBaseline 只在【新编组】时才跑，恢复路径根本不经过它。
  //   ⚠ 没有可看的任务时 tick 第一轮就会自己停表，不会空转。
  try{ if(typeof stampWatch!=='undefined') stampWatch.ensure(); }catch(_){ }
  // ⚠ 启动时刷一次记录卡（原来这里是白扫整个缓存目录，现在只广播事件）。
  broadcastRecordsChanged();
}

async function cacheRestoreOne(entry){
  const startedNamespace=typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy';
  const stillCurrent=()=>startedNamespace===(typeof cacheNamespaceId==='function'?cacheNamespaceId():'legacy');
  const m = entry.meta, cache = window.uiwin.cache;
  const project = entry.project, runId = entry.runId;
  const readFull = name => () => cache.readFile(project, runId, name);
  const shots = [];
  let sourceImgId = '';
  let attached=false;
  try{
  for(const s of (m.shots||[])){
    const n = Number(s.index)+1;
    if(s.hasImage){
      const thumb = await cache.readFile(project, runId, 'thumb_'+n+'.jpg');
      if(!stillCurrent()) return false;
      if(thumb && thumb.length){
        // ⭐⭐ 2026-10-05（docs/143 §三）：恢复时把 raw / base 的登记【一起重建】。
        //
        //   ⚠ 以前只重建 output_N.png，raw_N.png 只在磁盘上躺着、内存里没有登记 ——
        //     于是"刚开软件好使、重启后不好使"（本项目最难受的那类 bug）。
        //   ⚠ 为什么要补上 base：小眼睛切版本要【换 shot.imgId】、
        //     底版那一版得能当场读到图。没有登记就只能去读磁盘，
        //     而读磁盘是同步 I/O、在渲染路径里做会卡 —— 所以按一等公民登记。
        //   ⚠ 登记底版用读盘函数（readFull）而不是路径字符串：
        //     IMG.putFromCache(thumb, mime, fullReader) 的第三个参数是【懒加载】——
        //     不点开就不读磁盘。这正是 docs/21 要的那套（原图不进 DOM、按需读）。
        const fullOf=(name)=>readFull(name);
        const rec={done:true, error:'', errorInfo:null, restoreState:'done',
                    detailTier:s.detailTier||'',
                    detailLayerId:(s.detailLayerId!=null)?s.detailLayerId:null,
                    tweenLayerId:(s.tweenLayerId!=null)?s.tweenLayerId:null, tweenStrength:(s.tweenStrength!=null)?s.tweenStrength:null,
                    rawSaved:!!s.hasRaw,   // B01：这张有没有 raw_N.png（不恢复的话，元数据一重写就记成没有）
                    baseSaved:!!s.hasBase, // 143：这张有没有 base_N.png（同上，不恢复就会被误记成没有）
                    // ⭐ 2026-10-18：生成时实际用的那种校色。⚠ 只认四个合法值，乱的 / 老数据（没有）一律空 ⇒ 照老规矩当混合
                    //   ⚠ 四个值就地写死、不引用 COLOR_VERSIONS：这段恢复代码会被测试单独切出来跑（那里没有那个常量），
                    //     引用它 = 整段恢复抛错（全量测试抓到 4 条，记忆「V7 测试按源码切片跑」那个坑）。
                    autoVersion:(['base','global','precise','hybrid'].indexOf(String(s.autoVersion||''))>=0)?String(s.autoVersion):'',
                    imgId:window.IMG.putFromCache(thumb, 'image/png', fullOf('output_'+n+'.png')),
                    // ⭐⭐ 2026-10-08（docs/170 §4.3 不变量 8）：**自动方式那张的证件号**。
                    //   ⚠⚠ 为什么必须有：`output_N.png` 是【生成时自动方式的结果】，切版本【永远不改它】。
                    //     可写 output 的那个循环原来用的是 `shot.imgId`（= 当前显示的那张）——
                    //     于是"切到底版"之后再保存一次，就把**底版写进了 output_N.png**，
                    //     校色版从磁盘上彻底消失。实测：切过底版的 27 张里 24 张两个文件字节相同。
                    //   ⇒ 从这一版起：写 output / thumb 一律用 `autoImgId`，不用 `imgId`。
                    //   ⚠ 恢复出来的这张，盘上的 output_N.png 就是自动方式的结果（它从没被切换改过），
                    //     所以 autoImgId 与 imgId 指向同一张 —— 只 putFromCache 一次，别生成两个 id
                    //     （生成两个会各占一份图，内存白白翻倍）。
                    autoImgId:null};
                    // ⚠ 上一步那个对象字面量结束之后单独赋值：autoImgId 和 imgId 指向同一个 id。
                    rec.autoImgId=rec.imgId;
        // ⚠ raw / base 的 registration 失败【不算恢复失败】—— 它们是"事后能做的事"，
        //   为了它们把整张成品丢掉是本末倒置。所以各自 try 住、拿不到就当没有。
        if(s.hasRaw){
          try{ rec.rawImgId=window.IMG.putFromCache(thumb, 'image/png', fullOf('raw_'+n+'.png')); }catch(_){}
        }
        if(s.hasBase){
          try{ rec.baseImgId=window.IMG.putFromCache(thumb, 'image/png', fullOf('base_'+n+'.png')); }catch(_){}
        }
        shots.push(rec);
        continue;
      }
    }
    shots.push({done:false, error:s.error||'', errorInfo:s.error?taskErrorInfo(s.error,'generate','AI_IMAGE_FAILED'):null,
                imgId:'', restoreState:s.restoreState||'failed'});
  }
  if(m.hasInput){
    const thumb = await cache.readFile(project, runId, 'input_thumb.jpg');
    if(!stillCurrent()) return false;
    if(thumb && thumb.length) sourceImgId = window.IMG.putFromCache(thumb, 'image/png', readFull('input.png'));
  }
  // ⚠⚠ 2026-09-13 新增的归一化：恢复回来的任务【一定不在跑了】——
  //   界面重启过，主进程那边的生成早就断了，不可能再有进度回来。
  //   所以存盘时是什么状态都得归到终态，否则会出现一张"停在 40% 的僵尸卡"：
  //   进度条不动、还挂着「提前结束」按钮、点了什么也不会发生。
  //   ⚠ 这道归一化从这一版起是【必须的】：现在传回成功就会落一次盘，
  //     而「提前结束」时落的那一份，状态正是 running。
  const savedStatus=String(m.status||'done');
  const wasRunning=['done','success','completed','failed','cancelled'].indexOf(savedStatus)<0;
  const okCount=shots.filter(s=>s&&s.imgId).length;
  const restoredStatus=wasRunning?(okCount?'done':'failed'):savedStatus;
  // 上次没跑完的要明说少了几张，不然用户会以为图丢了（图确实没出来，但不是这里丢的）
  const restoredSub=wasRunning
    ? ('上次没跑完 · 存下了 '+okCount+'/'+shots.length+' 张')
    : (m.sub||'');
  const task = {
    id:++taskSeq, kind:['generation','glow','dlss','matting','segment','sam2'].includes(m.kind)?m.kind:'generation', taskId:String(m.taskId||''),
    toolParams:['glow','dlss'].includes(m.kind)?m.toolParams:undefined,
    colorToolRunId:String(m.colorToolRunId||''),preserveGeneratedAppearance:m.preserveGeneratedAppearance===true,
    antiMode:Number(m.antiMode)||0, standard:GENERATION_TASK_STANDARD.version,
    label:m.label||'生成任务', icon:m.icon||'check', shots:shots,
    // ⚠ 状态/文字走上面归一化后的值，不直接用 meta 里的原值（见那段注释）
    pct:wasRunning?100:(Number(m.pct)||0), status:restoredStatus, sub:restoredSub,
    page:0, sourceImg:sourceImgId?window.IMG.thumb(sourceImgId):placeholderSVG((m.startedAt||0)%360),
    sourceImgId:sourceImgId, errorInfo:null, life:0, startedAt:Number(m.startedAt)||Date.now(),
    completedAt:m.completedAt||undefined,
    migration:m.migration?aiClonePlain(m.migration):undefined,
    captureSnapshot:m.migration?.returnBlocked?null:m.captureSnapshot||null,
    productProjectId:m.projectId||'',
    // ⚠ outputs 决定"能不能传回"。恢复的任务必须能传回 —— 这正是缓存最大的价值:
    //   不用重新花钱生成，就能反复测传回。
    outputs:shots.map((s,i)=>({index:i, imgId:s.imgId, restoreState:'done'})).filter(s=>s.imgId),
    errors:[],
    sourceDocId:m.migration?.returnBlocked?null:m.sourceDocId, sourceDocName:m.sourceDocName,
    sourceSelection:m.migration?.returnBlocked?null:(m.sourceSelection||m.captureSnapshot&&m.captureSnapshot.selection),
    mattingTierName:m.mattingTierName||'', mattingSize:m.mattingSize||'',
    // ⭐ 2026-10-05（docs/143 §五）：把用户上次选的"显示哪一版"读回来。
    //   ⚠ 缺省是校色版；老 meta.json 里没这个字段 → 读成 undefined → taskColorVersion
    //     自己会兜成 'colormatched'，不用在这里写 ||'colormatched'（两处写就两处会漂）。
    colorVersion:m.colorVersion==='base'?'base':'colormatched',
    provider:m.provider, model:m.model, size:m.size, aspectRatio:m.aspectRatio, channelLabel:String(m.channelLabel||''),
    // ⚠ 2026-10-19 补：算力通道 / 算力来源 / 完成那一刻写死的金额，原来恢复时没带回来 ——
    //   恢复的任务一点 ✕ 或一传回，元数据整份重写，这三样就丢了（记录卡把 grs 当成自定义服务商、旧账按现在的价目表重算）。
    computeSource:m.computeSource||undefined, connectionSlot:m.connectionSlot||undefined, cost:m.cost||undefined,
    failedStage:String(m.failedStage||''),
    presetId:m.presetId,presetTitle:m.presetTitle,presetVersion:m.presetVersion,protocol:m.protocol,
    batch:Number(m.batch)||shots.length, prompt:m.prompt||'',
    workflowParameters:aiClonePlain(m.workflowParameters||{}),workflowPresetId:String(m.workflowPresetId||''),
    cancelRequested:false, returnState:'idle',
    // 恢复 Photoshop 图层信息，让恢复回来的任务也能做 hover 联动。
    // ⚠ 图层可能已经被删/文档已关，调用时静默降级，不在这里预先校验
    //   (校验要发一轮桥指令，为了一个不一定用到的功能不值当)。
    psLayerIds:Array.isArray(m.psLayerIds)?m.psLayerIds:[],
    psLayerByShot:m.psLayerByShot||{},
    psGroupId:m.psGroupId!=null?m.psGroupId:null,
    psGroupName:m.psGroupName||'',
    psDocId:m.psDocId!=null?m.psDocId:null,
    // ⚠ 2026-10-02：参考图张数（C01 R4）要恢复回来 —— 不恢复的话，恢复的任务一传回、元数据重写，张数就被记成 0。
    referenceCount:Number(m.referenceCount)||0,
    // ⚠ 恢复基线。没有就【不给这个字段】(不是给空数组) —— 见 recordStampBaseline 的注释。
    stampBaseline:Array.isArray(m.stampBaseline)?m.stampBaseline.map(Number):undefined,
    cacheProject:project, cacheRunId:runId, cacheSaved:true, restoredFromCache:true,
    storageNamespaceId:m.namespaceId||cacheNamespaceId()
  };
  addTask(task);
  attached=true;
  return true;
  }finally{
    if(!attached) window.IMG.releaseMany([sourceImgId,...shots.map(s=>s.imgId)].filter(Boolean));
  }
}

// 任务用到的所有图片 id。释放时一个都不能漏。
function taskImageIds(task){
  const ids=[];
  if(!task) return ids;
  if(task.sourceImgId) ids.push(task.sourceImgId);
  (task.shots||[]).forEach(s=>{ if(s&&s.imgId) ids.push(s.imgId); if(s&&s.rawImgId) ids.push(s.rawImgId); });   // rawImgId：B01 校色前原图，正常写完缓存就释放了，这里兜底
  (task.outputs||[]).forEach(o=>{ if(o&&o.imgId) ids.push(o.imgId); });
  return ids.filter((x,i,a)=>a.indexOf(x)===i);   // shots 和 outputs 指的是同一批图, 去重
}
function removeTask(id){
  const idx = taskList.findIndex(t => t.id === id);
  if (idx < 0) return;
  const task = taskList[idx];
  if (task.timer) clearTimeout(task.timer);
  // ⚠ 谁创建谁释放。不 revoke 的 Blob 会一直占着内存，而且它不在 JS 堆里，
  //   用常规内存分析根本看不出来 —— 比 base64 泄漏更难查。见 docs/21 铁律 4。
  if(window.IMG) window.IMG.releaseMany(taskImageIds(task));
  // ⭐⭐⭐ 2026-10-08（docs/170 §10.1 H2）：插帧帧也要一起放掉。
  //   ⚠ 改之前【没有任何地方调 V7Tween.dropTask】——
  //     任务删了，那十几帧（1463×1463 一张 4.61 MB，一组 ≈83 MB）和它们的 blob URL
  //     就一直挂在内存里，一句错都不报。
  //   ⚠ 第 3 步改成"只放内存"之后，这一步变得更要紧：
  //     以前帧还能靠落盘重现，现在【内存里那份就是唯一一份】，
  //     不收就是实打实的泄漏。
  //   ⚠ 收的是【任务对象】（dropTask 要用 task.shots 和 sourceImgId 算键），
  //     传 id 进去推不出端点，等于白收。
  if(window.V7Tween && typeof window.V7Tween.dropTask === 'function'){
    try{ window.V7Tween.dropTask(task); }catch(_){}
  }
  const el = tasksEl.querySelector('.task[data-task="' + id + '"]');
  taskList.splice(idx, 1);

  if (!el) { setTasks(); return; }
  // 离场前先把预览收掉, 免得悬空
  const pv = el.querySelector('.task-preview.show');
  if (pv) pv.classList.remove('show');
  el.classList.add('leaving');
  el.addEventListener('animationend', () => {
    el.remove();
    const n = tasksEl.querySelectorAll('.task').length;
    if (tcur >= n) tcur = Math.max(0, n - 1);
    setTasks();
    // ⚠ 任务从任务栏移除了，记录卡里"在不在任务栏"的状态要跟着变（广播，不再白扫缓存目录）。
    broadcastRecordsChanged();
  }, { once: true });
}

// ⭐ 细节补偿的两个档位。⚠ 必须定义在 buildPreview 【之前】——
//   它在缩略图上画按钮和角标时要读这张表，而 const 有暂时性死区：
//   定义在后面的话，这里一读就抛错，整个脚本从这里死掉，
//   后面所有绑定都不会跑（铁律 17 里那个"窗口不能滚动/折叠/拖拽"就是这么来的）。
//   完整的实现（applyDetailTier 等）在文件靠后的"细节补偿档位"一节。
// ⚠⚠ 2026-10-05（docs/143 §八-4）：【只剩「替换」一档】。
//   「增益」(mode:'gain') 已按用户拍板砍掉 —— 引擎侧那条分支还留着
//   （老缓存里记着 detailTier:'gain' 的图重启后还要能识别），
//   但界面上不再给出这个入口。
//   ⚠ 别把 gain 整个从引擎删掉：删了之后老任务恢复时 detailTier 读成未知值，
//     那个"换档时删掉旧层"的逻辑会找不到层 —— 静默留下一层擦不掉的旧补丁。
const DETAIL_TIERS={
  replace:{label:'替换',title:'细节还原',mode:'replace'}
};

// ── 预览弹层: 整行翻页 ──
// ⭐⭐ 2026-10-09（docs/191，用户要求）：「刚被用户主动收起，短时间内别再自动弹」。
//   用户原话：「点一下这个界面它能开，那咋关呢？总不可能把鼠标移走关吧？
//             那肯定是再点一下再关啊」。
//   ⚠ 为什么光"再点一下收掉"不够：收掉那一刻**鼠标还停在缩略图上**，
//     同一次交互里"悬停就开"立刻又把框弹回来 ⇒ 表现成"点了关不掉"。
//     （真窗口实测：点第 2 下确实收了，归属立刻又变回原样。）
//   ⚠ 所以主动收起要记一个时间戳，下面两处自动弹的路在 1.5 秒内不干活。
//     「1.5 秒」的取法：够长到挡住同一次交互的余波，又短到用户"再点一下又能开"
//     （实测点第 3 下能正常开）。
//   ⚠ 只在【用户主动收起】时记 —— 别在 hideBox 里记，那会把
//     "鼠标移开自动收"也算进去，然后正常的悬停就弹不出来了。
//   ⚠⚠ 而且【点击打开时一定要清掉它】（见下面 hideBoxIfTask 里的说明）——
//     否则"点一下收、再点一下开"会被自己刚设的闸挡住，变成"只能关不能开"。
//     （2026-10-09 实测栽过：点第 1、3 下都没开。）
let boxDeliberatelyClosedAt = 0;
const BOX_REOPEN_SUPPRESS_MS = 1500;
function boxAutoOpenSuppressed(){
  return (Date.now() - boxDeliberatelyClosedAt) < BOX_REOPEN_SUPPRESS_MS;
}
// 点击打开前调它：用户主动要开，闸立刻失效。
// ⚠ 不写成 hideBoxIfTask 内部的行为，是因为那是个"通用收框"函数，
//   以后别的地方调它也会顺手清闸 —— 语义容易看错。这里显式一点。
function clearBoxAutoOpenSuppression(){ boxDeliberatelyClosedAt = 0; }

// ⭐⭐ 2026-10-09（docs/191，用户反馈）：「收起行为会收起我们的任务卡片右滑打开的窗口，
//   我其实只希望收起展开的大图就好了」。
//   ⚠ hideBox() 收完框会通知 onBoxClosed（见文件末尾那个 setBoxClosedHandler），
//     那个回调的本职是"框走了，条也别留着"—— 对"鼠标移开自动收"是对的，
//     但对【用户自己点一下收掉大图】就过了：他只是想收大图，条还要接着用。
//   ⇒ 用这个标记区分两种收起：点它一下收大图时置 true，回调看到就不收条。
//   ⚠ 必须用 try/finally 复位：中间抛错的话标记会一直挂着，
//     表现成"以后框没了条也不收"，很难查。
//   ⚠⚠⚠ 必须挂在 window 上，**不能只用顶层 let**：
//     那个回调在【另一个 <script> 块】里（文件末尾 setBoxClosedHandler 那段），
//     跨块访问顶层 let 不保证有效 —— 2026-10-09 实测栽过：
//     标记写成 let 时，回调里那个 `if(boxCloseImageOnly) return;` 读不到值，
//     表现成"点一下收大图，条也跟着没了"（就是用户报的那个毛病，改完还在）。
//     挂 window 之后跨块一定可见。
//
//   ⚠⚠⚠ 2026-10-09 第二次修（用户报「缩略图卡片有时候收不回去了」）：
//     **这个意图不能是布尔标记、也不能是时间窗，必须是【一次性令牌】。**
//     第一版：布尔标记（置 true → try/finally 复位）—— 实测"点完收大图后移开鼠标，
//             条still 1、永远不收"。
//     第二版：800ms 时间窗 —— 还有洞：**用户点完收大图后若在 800ms 内就移开鼠标，
//             那次"移开"引起的收起也会被当成"只收大图" ⇒ 条又赖住。**
//             这正是"有时候收不回去"（取决于手多快 ⇒ 间歇性）。
//     ⇒ 现在：点击收大图时放一个【一次性令牌】，回调消费掉就没了。
//       "之后那次"（用户真移开鼠标）拿不到令牌，照旧收条。
//       ⚠ 谁先来谁用掉 —— 不会误伤之后任何一次收起。
window.boxCloseImageOnlyToken = false;
// ⚠ 挂 window：那个回调在另一个 <script> 块里，跨块读函数声明/顶层 let 都不保险
//   （同一形状的坑 2026-10-09 栽过一次，见上一段）。
window.boxCloseConsumeImageOnly = function(){
  if (!window.boxCloseImageOnlyToken) return false;
  window.boxCloseImageOnlyToken = false;   // 用掉即失效
  return true;
};

function buildPreview(taskEl, task){
  const pv = taskEl.querySelector('.task-preview');
  if (!pv || !task) return;
  const orderedShots = (task.shots||[]).map((shot,index)=>Object.assign({index},shot||{})).sort((a,b)=>{
    const rank=shot=>shot.error?1:((task.kind==='generation' ? shot.restoreState==='done' : shot.done) && shot.imgId ? 0 : 2);
    return rank(a)-rank(b)||a.index-b.index;
  });
  const total = orderedShots.length;
  const pages = Math.max(1, Math.ceil(total / PER));
  const multiPage = total > PER;        // >4 张才启用预览区滚轮分页
  task.page = Math.max(0, Math.min(pages - 1, Number(task.page) || 0));
  function errorTip(){
    let tip=document.getElementById('pv-error-tip');
    if(!tip){tip=document.createElement('div');tip.id='pv-error-tip';tip.className='pv-error-tip';document.body.appendChild(tip);}
    return tip;
  }

  function draw(dir){
    const oldTip=document.getElementById('pv-error-tip');
    if(oldTip) oldTip.classList.remove('show');
    const start = task.page * PER, slice = orderedShots.slice(start, start + PER);
    // ⚠ 宽度规则: ≤4 张 → 按实际张数(自然宽); >4 张 → 每页补齐到 4 格,
    //   保证右侧点状分页条和预览条宽度稳定。
    let cells = '';
    // 采样步数只画在【下一张还没回来】的那一格（一张一张算，正在算的就是它）
    const nextPending = orderedShots.find(s => !s.error && !((task.kind==='generation' ? s.restoreState==='done' : s.done) && s.imgId));
    const stepsAt = nextPending ? nextPending.index : -1;
    slice.forEach((im, i) => {
      const gi = start + i + 1;
      if (im.error){
        cells += '<div class="pv-cell pv-error" data-shot-index="'+im.index+'" data-error="'+escapeHtml(im.error)+'"><div class="pv-media"><span class="pv-idx">' + gi + '</span>' +
                 '<div class="pv-error-icon">×</div></div></div>';
      } else if ((task.kind==='generation' ? im.restoreState==='done' : im.done) && im.imgId){
        // ⚠ 只挂缩略图，且 DOM 里只放 imgId 不放图片数据。
        //   以前这里 src 和 data-big 各塞一份完整 base64，8 张图每次重绘要拼 ~170MB 字符串
        //   —— 这就是进度刷新时"不跟手"的真凶。现在这行只有几十字节。
        const thumb = window.IMG.thumb(im.imgId) || placeholderSVG(gi * 48);
        // ⭐ 细节补偿档位（2026-09-12）：两个按钮 + 一个角标。
        //   ⚠ 状态【只用角标表达，不换缩略图】—— 120px 的缩略图里
        //     1~2 像素的锐度差异物理上就看不出来，换了也是白换，
        //     还要多付"换 imgId + 释放旧 Blob"的代价。要看效果去 PS 里点眼睛。
        const dt = String(im.detailTier||'');
        // ⭐⭐ 提升纹理的按钮【只在这一张已经传回 PS 之后才出现】（2026-09-13 用户定案）。
        //   补细节是往"那张 AI 图的图层上方"嵌一层，没传回就没有图层可嵌 ——
        //   以前按钮一直显示，点了必然撞到 DETAIL_NO_TARGET 那道阀。
        //   现在从源头堵住：没传回就不给按钮，用户不会点到一个注定失败的东西。
        //   ⚠ 判据用 psLayerByShot（传回成功才写），不是 task.status。
        const layerMap = task.psLayerByShot || {};
        const placedInPS = layerMap[im.index] != null;
        // ⭐⭐ 2026-10-05 用户定：右上角那个位置改成「应用」按钮。
        //   原来右上角是 .pv-badge —— 一个【只读角标】，印的是"这张补过哪一档细节"
        //   （补了"替换"档就印「替换」），跟底部两个按钮的 .on 高亮是重复信息，用户说它是残留。
        //   现在它的意思是：**用滑条/滚轮调好的强度，换掉 PS 里原来那一层**。
        //   ⚠⚠ 底部「替换 / 增益」是【另一个功能】（用原图纹理补细节），一个字都不许动。
        //   ⚠ 只在【已经传回过 PS】时出现（S-Q2）；没传回过那一格底部是「传回」。
        //   ⚠ 用户原话为什么放这里不放大框："预览窗口是完全穿透的…鼠标移到预览窗口才能传回
        //     会拉长用户的操作路径"（推翻了 docs/136 S5 "只放大框里"）。
        const badge = (task.kind==='generation' && !task.migration?.returnBlocked && placedInPS)
          ? '<button type="button" class="pv-apply" data-apply-shot="'+im.index+'"'
            +' title="把调好的强度换进 Photoshop 那一层（只换这一张）">应用</button>' : '';
        const btn=(k)=>'<button type="button" class="pv-dt'+(dt===k?' on':'')+'"'
          +' data-detail-tier="'+k+'" data-shot="'+im.index+'"'
          +' title="'+escapeHtml(DETAIL_TIERS[k].title+'：在这张图上方嵌一层补过细节的图（可随时删掉）')+'">'
          +escapeHtml(DETAIL_TIERS[k].label)+'</button>';
        // ⭐ 没传回的给「传回」按钮（2026-09-13 用户定案：只能手动一张一张传）；
        //   传回之后那一格才换成「替换 / 增益」两个提升纹理的按钮。
        //   —— 同一个位置，按状态切换，用户不会同时看到两组按钮。
        // ⚠ 这一排按钮【只对生成任务成立】：抠像是当场就贴回 PS 的，没有"传回"这一步，
        //   "替换/增益"更是生成专用（往 AI 图上方嵌补细节层）。
        //   不关掉的话抠像任务卡上会挂两三个点了必然失败的按钮。
        const dtbar = task.kind!=='generation'||task.migration?.returnBlocked ? '' : (placedInPS
          ? '<div class="pv-dtbar one">' + btn('replace') + '</div>'
          : '<div class="pv-dtbar one"><button type="button" class="pv-dt send"'
            + ' data-send-shot="' + im.index + '"'
            + ' title="把这一张贴进 Photoshop（贴完才能提升纹理）">传回</button></div>');
        // ⚠ 2026-10-11 a11y：给结果图加 alt。
        //   这几张是任务结果图，给一个"能说清是哪一张"的名字（第几张）；
        //   不留空是因为它不是装饰 —— 用户就是靠它认结果的，且 alt 带序号能区分多张。
        //   ⚠ 注释必须写在【语句外面】：我第一版把 // 插在字符串拼接的换行中间，
        //     下一行还在继续拼 `+ ...`，于是被注释掉、语法直接坏掉。
        cells += '<div class="pv-cell pv-ready" data-shot-index="'+im.index+'"><div class="pv-media"><span class="pv-idx">' + gi + '</span>' +
                 '<img src="' + thumb + '" alt="生成结果第 ' + gi + ' 张" data-img-id="' + escapeHtml(im.imgId) + '" data-idx="' + gi + '" data-original-idx="' + (im.index+1) + '"/>' +
                 badge + dtbar + '</div></div>';
      } else {
        cells += '<div class="pv-cell" data-shot-index="'+im.index+'"><div class="pv-media"><span class="pv-idx">' + gi + '</span>' +
                 '<div class="pv-hourglass">'+(window.ICON?ICON.render('hourglass',30):'')+'</div>' + (im.index===stepsAt ? taskStepsHtml(task) : '') + '</div></div>';
      }
    });
    // ⭐⭐ 2026-10-04 用户定案（原话）：
    //   「统一的变为就是四个缩略图加上有滚动条…四个项目以内的话，剩下的地方就留空吧，
    //     然后滚动条就从一个点就行了。」
    //   ⇒ 预览条【永远】按 4 格宽出，不足 4 张的格子留空（.pv-empty 是透明的，占位不画东西）。
    //   ⇒ 右侧分页条【永远】在：只有 1 页时它就显示一个点。
    //   ⚠ 为什么要这样：以前 ≤4 张走"自然宽"，3 张就 3 张宽、5 张就 4 张宽，
    //     于是**同一个预览框的宽度会随图片张数变来变去**，用户滚动调强度时框忽宽忽窄，很难受。
    //   ⚠ 只影响【显示宽度】。真正翻页的判据仍然是 multiPage（>4 张），没动。
    for (let k = slice.length; k < PER; k++) cells += '<div class="pv-cell pv-empty"></div>';
    let rail = '<div class="pv-rail" aria-label="任务图片分页">' +
      Array.from({length:pages},(_,i)=>'<i class="pv-dot'+(i===task.page?' active':'')+'" data-page="'+i+'"></i>').join('') +
      '</div>';
    // pv-paged: 锁成固定总宽，让右缘和上方三级详情卡的右缘对齐（算式见 CSS）。
    let html = '<div class="pv-strip pv-paged"><div class="pv-track">' + cells + '</div>' + rail + '</div>';
    pv.innerHTML = html;
    // ⭐ 2026-10-19：重画完把每张的状态小标补回去（innerHTML 一刷就没了）
    if (typeof jobView !== 'undefined' && jobView) pv.querySelectorAll('.pv-cell[data-shot-index]').forEach(cell => jobView.paintCell(cell, task));

    // ⭐ 细节补偿按钮。⚠ stopPropagation 必须有 —— 这两个按钮坐在缩略图上，
    //   不拦的话会连带触发缩略图自己的点击（放大看图）和任务卡的拖拽。
    pv.querySelectorAll('[data-detail-tier]').forEach(btn=>{
      btn.addEventListener('mousedown',e=>e.stopPropagation());
      btn.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation();
        applyDetailTier(task, Number(btn.dataset.shot)||0, btn.dataset.detailTier);
      });
    });
    // ⭐ 右上角「应用」（2026-10-05）：用调好的强度换掉 PS 那一层。
    //   ⚠ stopPropagation 同上：坐在缩略图上，不拦会连带触发缩略图点击（开大框）和拖拽。
    //   ⚠ 用 taskById 取最新那份 —— 闭包里的 task 是这次渲染时的快照。
    pv.querySelectorAll('[data-apply-shot]').forEach(btn=>{
      btn.addEventListener('mousedown',e=>e.stopPropagation());
      btn.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation();
        if(window.V7Tween&&typeof V7Tween.applyShot==='function')
          V7Tween.applyShot(taskById(task.id)||task, Number(btn.dataset.applyShot)||0, btn);
      });
    });
    // 单张传回（2026-09-13）
    pv.querySelectorAll('[data-send-shot]').forEach(btn=>{
      btn.addEventListener('mousedown',e=>e.stopPropagation());
      btn.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation();
        aiTransfer(task, [Number(btn.dataset.sendShot)||0]);
      });
    });

    const tip=errorTip();
    pv.querySelectorAll('.pv-cell.pv-error').forEach(cell=>{
      const owner=String(task.id)+'/'+String(cell.dataset.error||'');
      const move=e=>{
        const x=Math.min(Math.max(8,e.clientX+14),Math.max(8,window.innerWidth-228));
        const y=Math.min(Math.max(8,e.clientY+14),Math.max(8,window.innerHeight-88));
        tip.textContent=cell.dataset.error||'任务失败';
        tip.dataset.owner=owner;
        tip.style.left=x+'px'; tip.style.top=y+'px';
      };
      // ⭐ 2026-10-22（docs/263 第 7 条）：停 120ms 才弹，划过一排失败格不闪（hover-delay.js；没加载就照旧立刻弹）
      const hd=tip._hd||(tip._hd=window.V7HoverDelay?V7HoverDelay.create():null);
      cell.addEventListener('mouseenter',e=>{move(e);if(hd)hd.show(()=>{if(cell.isConnected&&tip.dataset.owner===owner)tip.classList.add('show');});else tip.classList.add('show');});
      cell.addEventListener('mousemove',move);
      cell.addEventListener('mouseleave',()=>{const off=()=>{if(tip.dataset.owner===owner)tip.classList.remove('show');};if(hd)hd.hide(off);else off();});
    });

    // ⭐ 2026-10-04：鼠标浮到某一格 → 上方大预览框显示那一张（放大）。
    //   ⚠ 只在框已经开着（= 鼠标在这张任务卡这条链上）时才换图 ——
    //     不然会凭空弹出大框（用户只是路过缩略图）。
    pv.querySelectorAll('.pv-cell.pv-ready').forEach(cell=>{
      const shotImg=cell.querySelector('img[data-img-id]');
      if(!shotImg) return;
      cell.addEventListener('mouseenter',()=>{
        if(!window.V7Tween) return;
        const shot=(task.shots||[])[parseInt(shotImg.dataset.originalIdx,10)-1];
        if(shot) window.V7Tween.hoverThumb(cell,task,shot);
      });
    });

    // 翻页动画: 只让 .pv-track(图格区)上下滑入
    if (dir){
      const strip = pv.querySelector('.pv-strip');
      if (strip){
        strip.classList.add('pv-animating');
        clearTimeout(pv._animTimer);
        pv._animTimer = setTimeout(()=>strip.classList.remove('pv-animating'), 340);
      }
      const track = pv.querySelector('.pv-track');
      if (track){
        const from = dir > 0 ? 40 : -40;         // 下一页从下方进入, 上一页从上方进入
        track.style.transition = 'none';
        track.style.transform = 'translateY(' + from + 'px)';
        track.style.opacity = '0';
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            track.style.transition = 'transform .26s var(--ease-out), opacity .2s var(--ease-soft)';
            track.style.transform = 'translateY(0)';
            track.style.opacity = '1';
          });
        });
      }
    }

    // X = 从任务栏收起。缓存留在硬盘上，以后"生成记录"还能翻到。
    // ⚠ stopPropagation: 不加会连带触发任务卡自己的点击/拖拽。
    const closeBtn = taskEl.querySelector('[data-task-close]');
    if (closeBtn && !closeBtn._bound){
      closeBtn._bound = true;
      closeBtn.addEventListener('click', e => {
        e.preventDefault(); e.stopPropagation();
        cacheSetTaskbar(task, false);
        removeTask(task.id);
      });
    }
    // ⚠⚠ 2026-09-13：「提前结束 / 传回」的绑定【搬去 syncTaskActions 了】，这里不能再绑。
    //   原因：那一行现在会跟着状态重画，重画出来的是新元素，
    //   两边都绑 = 同一个按钮被绑两次 → 点一下发两次传回（用户实测的"多次传回"之一）。
    pv.querySelectorAll('.pv-cell img').forEach(img => {
      // 划到哪张 → PS 里单独显示哪张。
      // ⚠ 用 data-original-idx(图在 shots 里的真实序号)，不能用 data-idx ——
      //   预览是排过序的(成功的排前面)，用显示序号会对错图层。
      const soloThis = () => {
        const originalIdx = parseInt(img.dataset.originalIdx);
        if (Number.isFinite(originalIdx)) generationSoloLayer(task, originalIdx - 1);
      };
      // ⭐ 2026-10-19（docs/250 第 4 条，用户同意）：只认【鼠标真的移过来】的那一下。
      //   滚轮翻任务卡时鼠标没动、是卡片从鼠标底下滑过去 —— 浏览器照样发 mouseenter，原来这样就会把 PS 里藏着的旧图层点亮。
      //   现在那种「滑过来」先不算（记成待定），鼠标在这张图上真动一下再算；判法见 hover-intent.js。双击跳过去不受影响。
      img.addEventListener('mouseenter', e => {
        if (typeof thumbHover !== 'undefined' && thumbHover && !thumbHover.enter(e)) return;
        soloThis();
      });
      img.addEventListener('mousemove', e => {
        if (typeof thumbHover !== 'undefined' && thumbHover && thumbHover.moveOn(e)) soloThis();
      });
      img.addEventListener('mouseleave', () => {
        if (typeof thumbHover !== 'undefined' && thumbHover) thumbHover.leave(img);
      });
      // ⭐⭐ 2026-10-14（用户定）：【双击缩略图】= 跳过去 + 缩放到填满。
      //   原来这是设置里一个开关（soloFocusRegion "联动时聚焦图层位置"）——
      //   用户说"它并不应该是开关，它其实更多可以融入到缩略图的机制当中"，
      //   "双击一下缩略图，它就直接联动过去了……操作成本非常低"。
      //   ⚠ forceFocus=true 走的是同一条 soloOwned 链路，只是把 focusRegion 置真。
      //
      //   ⚠⚠⚠ 双击必须【防抖】—— 用户实测报的：
      //     "双击部分没有做防抖处理，它会让我们的点按出大图，打开之后再收回才能跳转到对应的地方"
      //     真因：click 在第一次按下就派发、立刻开了大预览框；dblclick 要等第二次按下才来。
      //     所以光在 dblclick 里 stopPropagation 没用 —— 那时框已经开出来了。
      //   ⇒ 做法：click 的处理【延后 DBL_MS 再执行】，dblclick 一到就取消那次待执行的 click。
      //     这样双击全程只走"跳过去"这一条路，永远不开大图。
      //   ⚠ 单击因此晚 DBL_MS 才开框（约 220ms）—— 这是"区分单击与双击"的固有代价，
      //     和系统双击判定同一个数量级，用户感觉不到。
      let pendingClick = null;
      const runClick = fn => {
        if (pendingClick) clearTimeout(pendingClick);
        pendingClick = setTimeout(() => { pendingClick = null; fn(); }, DBL_MS);
      };
      img.addEventListener('dblclick', e => {
        e.stopPropagation(); e.preventDefault();
        if (pendingClick) { clearTimeout(pendingClick); pendingClick = null; }
        const originalIdx = parseInt(img.dataset.originalIdx);
        if (Number.isFinite(originalIdx)) generationSoloLayer(task, originalIdx - 1, true);
      });
      img.addEventListener('click', e => {
        e.stopPropagation();
        // ⚠⚠ 整个处理体延后 DBL_MS 执行 —— 见上面 dblclick 那段注释。
        //   双击时第二下会先取消这个待执行的 click，所以双击全程不开大图。
        runClick(() => {
        // ⭐ 2026-10-04 用户定案（docs/132 §三）：不再开独立大图窗口，
        //   改在【上方大预览框】里看（缩放/平移/双击复位都在那儿）。
        //   ⚠ 原来这里读 img.dataset.big 会当场复制一份 21MB 的完整 base64 ——
        //     点开大图卡顿的第一刀砍在这，现在这条路整个没了。
        const shot = (task.shots||[])[parseInt(img.dataset.originalIdx,10)-1];
        // ⚠⚠ 2026-10-05 改（用户实测：「点击缩略图还是会出现一个歪的大图框」「应用按钮没出现」）。
        //   原来这里调的是 attachTo(格子) + showImage(…, 格子) —— 那是【记录卡/参考图】的
        //   "独立看图"：框按被点的格子摆（= 歪），而且框从此不认这个任务（= 没有「应用」、调不了强度）。
        //   ⇒ 任务卡里一律走 openShot：位置只由任务卡 + 预览条决定，跟悬停弹出来的是同一个框。
        //   ⚠ 用 taskById 取【最新】那份：传回 PS 后对照表写在新对象上，闭包里这份是旧的。
        const taskEl = img.closest('.task');
        const liveTask = taskById(task.id) || task;
        const liveShot = (liveTask.shots||[])[parseInt(img.dataset.originalIdx,10)-1] || shot;
        // ⭐⭐ 2026-10-09（docs/191，用户要求）：「再点一下关」。
        //   用户原话：「你刚才那个逻辑忘记补了，就是点一下这个界面它能开，那咋关呢？
        //             总不可能把鼠标移走关吧？那肯定是再点一下再关啊」。
        //
        //   ⚠ 为什么需要它：开关关掉之后，"悬停离开自动收框"那条路也没了
        //     （hoverThumb/悬停那套不再参与）⇒ 用点击开出来的框【没有别的方式收掉】。
        //     所以点击必须是【开/关切换】。
        //
        //   ⚠⚠ 只在【开关关掉时】才切换：
        //     开着的时候保持原样（点一下永远是"打开并切到这一张"），
        //     否则会踩坏用户已经习惯的手感 —— 而他只是没改设置。
        //
        //   ⚠ 判据用 boxState()：框开着**且就是这个任务**才收。
        //     开给别的任务时不能收（那会变成"点 A 收掉 B"，看着像坏了）——
        //     这种情况按原样走 openShot 切过去。
        const clickOnly = (typeof settingsRuntime==='object' && settingsRuntime.hoverOpensPreview===false);
        if (clickOnly && window.V7Tween && typeof V7Tween.boxState==='function'
            && typeof V7Tween.hideBox==='function') {
          const own = V7Tween.boxState();
          if (own && own.open && String(own.taskId) === String(liveTask.id)) {
            // ⭐ 用户只是想【收起大图】—— 预览条要留着（用户 2026-10-09 反馈）。
            //   ⚠ 用时间窗（不是布尔标记）：只让【这一次点击】引起的收起不收条。
            //     写成布尔标记会连"用户之后移开鼠标"那次也一起放过 ⇒ 条再也收不掉
            //     （2026-10-09 实测复现：点两下收大图 → 移开鼠标 → 条still 1、永远不收）。
            window.boxCloseImageOnlyToken = true;   // 一次性：下面那次 hideBox 的回调用掉它
            try {
              V7Tween.hideBox();
            } finally {
              // 立刻收回时间窗？不行 —— 回调是同步跑的，但为了稳妥留一点余量，
              // 由 boxCloseIsImageOnly() 的时间判断自然过期。
            }
            // ⚠⚠ 关键：记一下"刚被用户主动收起"。
            //   不收这个的话，鼠标还停在缩略图上 → 同一次交互里
            //   "悬停就开"立刻又把框弹回来 ⇒ 表现成"点了关不掉"。
            //   （2026-10-09 真窗口实测：点第 2 下确实收了，归属立刻又变回原样。）
            boxDeliberatelyClosedAt = Date.now();
            return;
          }
        }
        if (window.V7Tween && typeof V7Tween.openShot === 'function' && taskEl && liveShot) {
          // ⭐ 用户主动点开 —— 立刻解除"刚收起别自动弹"的闸。
          //   ⚠ 必须在这里清：否则"点一下收、再点一下开"会被自己刚设的闸挡住，
          //     表现成"只能关不能开"（2026-10-09 实测栽过）。
          clearBoxAutoOpenSuppression();
          if (V7Tween.openShot(taskEl, liveTask, liveShot)) return;
          // ⭐⭐ 10-25（用户：三块屏、软件卡了一下以后，预览框之外还在另一块屏上弹出一个独立大图框）：
          //   卡顿时点击排队、晚处理，任务卡已经刷新过 ⇒ 按序号取到的那张对不上最新数据，openShot 认不出返回 false，
          //   原来这里就退回去开【老的独立大图窗口】（盖满一整块屏、永远置顶，落在哪块屏由 Windows 挑）——
          //   10-04 用户就定了任务卡里看图一律走预览框（docs/132 §三）。⇒ 按图片编号在最新数据里再找一次
          const byId = (liveTask.shots||[]).find(s => s && s.imgId && s.imgId === img.dataset.imgId);
          if (byId && V7Tween.openShot(taskEl, liveTask, byId)) return;
        }
        // 还对不上：只在预览框里显示这一张（不认任务，没有「应用」条），也不开老窗口
        if (window.V7Tween && typeof V7Tween.showImage === 'function' && img.dataset.imgId && window.IMG) {
          Promise.resolve(window.IMG.fullBytes(img.dataset.imgId)).then(buf => {
            const bytes = ArrayBuffer.isView(buf) ? new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength) : new Uint8Array(buf);
            V7Tween.showImage(bytes);
          }).catch(err => { try { aiAddLog('[预览] 这张图读不出来：' + String(err && err.message || err), 'warn'); } catch (_) {} });
          return;
        }
        // 只剩「预览框模块整个没加载起来」这一种情况才用老窗口（总比点了没反应强）
        openBig(img.dataset.imgId, task, parseInt(img.dataset.idx), parseInt(img.dataset.originalIdx));
        });   // ← runClick 收尾（延迟执行的那个处理体）
      });
    });
  }
  draw(0);
  // 只有右侧点状分页条消费滚轮；图片区滚轮继续冒泡到全局任务切换逻辑。
  // 使用属性转发到最新 buildPreview 闭包，避免重建内容后监听器引用旧任务状态。
  pv._pageWheelHandler = e => {
    const target = e.target;
    // ⭐ 2026-10-04 新增分支：落在缩略图(.pv-cell)上 → 调改动强度（docs/132 §四）。
    //   ⚠⚠ 必须挂在【这个已有的监听】里，不许另挂一个 wheel 监听 ——
    //     铁律 29：滚轮监听别挂会隐藏的元素；另挂必踩"动一下鼠标才好"那种陈旧命中测试，
    //     而且会跟这里的分页逻辑打架。
    //   ⚠ 落点判定顺序：先判 .pv-cell（它可能在 .pv-strip 里，不在 .pv-rail 里），
    //     分页条那条路一个字不改。
    const cell = target && target.closest ? target.closest('.pv-cell') : null;
    if (cell && pv.contains(cell) && window.V7Tween) {
      const shotImg = cell.querySelector('img[data-img-id]');
      if (shotImg && window.V7Tween.wheelOnCell(cell, e, task, pv)) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
    }
    const rail = target && target.closest ? target.closest('.pv-rail') : null;
    if (!rail || !pv.contains(rail)) return;
    e.preventDefault();
    e.stopPropagation();
    if (!multiPage || pv._pageWheelBusy) return;
    pv._pageWheelDelta = (pv._pageWheelDelta || 0) + e.deltaY;
    if (Math.abs(pv._pageWheelDelta) < 40) return;
    const dir = pv._pageWheelDelta > 0 ? 1 : -1;
    pv._pageWheelDelta = 0;
    const next = Math.max(0, Math.min(pages - 1, task.page + dir));
    if (next === task.page) return;
    task.page = next;
    pv._pageWheelBusy = true;
    draw(dir);
    window.setTimeout(() => { pv._pageWheelBusy = false; }, 280);
  };
  if (!pv._pageWheelBound){
    pv.addEventListener('wheel', e => {
      if (typeof pv._pageWheelHandler === 'function') pv._pageWheelHandler(e);
    }, {passive:false});
    pv._pageWheelBound = true;
  }
}

// 按 id 找任务数据
function taskById(id){ return taskList.find(t => String(t.id)===String(id) || String(t.taskId||'')===String(id)); }

// 测试期的虚拟任务入口已移除；正式任务通过业务调度接口调用 addTask()。
setTasks();

// 初始化: 应用已存的卡片背景(每张卡独立背景)
if(window.BG){
  window.BG.applyAll();
  updateZoneBg(cur);
  updateDetailBg();          // 三级绑定 detail-{主卡}-{分区}(HTML 里写死的 "detail" 要立刻换掉)
  // 背景管理由正式主题入口按需挂载，不在启动时重建详情内容。
}
// 给每个二级卡注入选中光带层(左右向内光带, 无边框锯齿)
document.querySelectorAll('#zones .zone').forEach(z=>{
  if(!z.querySelector('.z-selglow')){
    const g=document.createElement('div'); g.className='z-selglow';
    z.appendChild(g);
  }
  // 注入左缘弹出光(与 .z-selglow 同机制: 真实元素, append 在 .z-body 之后, 不被盖)
  if(!z.querySelector('.zone-glow')){
    const g=document.createElement('div'); g.className='zone-glow';
    z.appendChild(g);
  }
  // 注入亮边线(独立, 不跟光带绑). 默认隐藏, 弹二级时跟光带一起亮/灭.
  if(!z.querySelector('.zone-bright')){
    const b=document.createElement('div'); b.className='zone-bright';
    z.appendChild(b);
  }
  // 注入二级预告光(照一级 edgehint): 鼠标在卡上往右移时右缘实时渐亮, 预告"能拉出三级"
  if(!z.querySelector('.zone-edgehint')){
    const eh=document.createElement('div'); eh.className='zone-edgehint';
    z.appendChild(eh);
  }
});

// 给三级卡注入弹出光(跟二级同机制: 真实元素, 放 .dc-scroll 之后防被合成层盖)
const detailEl=document.getElementById('detail');
if(detailEl){
  if(!detailEl.querySelector('.detail-glow')){
    const g=document.createElement('div'); g.className='detail-glow';
    detailEl.appendChild(g);
  }
  if(!detailEl.querySelector('.detail-bright')){
    const b=document.createElement('div'); b.className='detail-bright';
    detailEl.appendChild(b);
  }
  // ⚠ 标记三级"被真的用过": 点按 / 内部滚动 都算(滚轮在全局 wheel 里另外标记)。
  //   用途见 detailUsed 声明处 —— 没用过就往右移出 → 二级三级一起收。
  detailEl.addEventListener('mousedown', ()=>{ detailUsed=true; });
  // ⭐ 2026-10-21（docs/261 U1）：在框里真的打了字才算「正在编辑」—— 打字的提示词框去 PS 画个选区不收（没打过字的照旧失焦就收）
  detailEl.addEventListener('input', ()=>{ detailUsed=true; detailEditing=true; });
  const dsc = detailEl.querySelector('.dc-scroll');
  if(dsc) dsc.addEventListener('scroll', ()=>{ detailUsed=true; });
}

// ═══ 大图查看器: 滚轮切上下张 / Ctrl+滚轮缩放 / 拖拽移动 / 双击复位 / 适配全屏 ═══
// 大图已经搬进独立的显示器级冻结窗口(viewer-window.html)。
// 主窗口是死的 1020×1100，窗口内的 position:fixed 铺不满屏幕，做不到真全屏冻结，
// 所以照 L4 的做法另开一个盖住整个显示器的窗口。详见 docs/12 六点九节。
//
// 这里只留【业务判断】：哪张能看、跳过没生成完/失败的图、张数怎么排。
// 缩放/拖拽/双击复位那些纯交互留在大图窗口里，不跨进程来传回。
let bigTask=null, bigIdx=1, bigOrder=[]; // 当前大图所属任务 + 预览排序序号(1基)
let viewerOpen=false;                    // 大图窗口是否开着(滚轮/穿透/失焦判断都看它)
let pvPrevFocus=null;                    // 打开大图前的焦点，关闭后还原
// 看完大图回来后，任务预览保持展开，直到鼠标真的放上去才解除。
// 大图是独立窗口，关掉时鼠标停在屏幕中央，不保持的话预览会立刻被收走。
let pvKeepOpen=false;
let pvKeepTaskId=null;                   // 保持的是哪张任务卡的预览

function bigTotal(){
  if(!bigTask) return 0;
  return bigOrder.length||bigTask.shots.length;
}
function bigShotAt(idx){
  if(!bigTask) return null;
  const pos=bigOrder[idx-1];
  return bigTask.shots[pos===undefined?idx-1:pos]||null;
}
// 把原图【二进制】送进大图窗口。
// ⚠ 不传 base64：传 base64 等于在另一个进程里再复制一份 21MB 字符串，
//   还要在那头再解一次码。传 ArrayBuffer 大约只有 8MB，且不用解码。
//   这是"点开大图有滞后"的主要来源。
let bigSendSeq=0;
function bigSendImage(imgId, num, total, reset){
  if(!(window.uiwin&&window.uiwin.viewer)) return;
  const token=++bigSendSeq;
  return Promise.resolve().then(()=>window.IMG.fullBytes(imgId)).then(async buf=>{
    // 用户可能已经连滚了好几张：过期的那次直接丢掉，不然会出现"图乱跳"。
    if(token!==bigSendSeq||!viewerOpen) return;
    const sz=window.IMG.size(imgId);
    const bytes=ArrayBuffer.isView(buf)?new Uint8Array(buf.buffer,buf.byteOffset,buf.byteLength):new Uint8Array(buf);
    const payload={bytes:bytes, mime:'image/png', num:num, total:total, reset:!!reset, w:sz.w, h:sz.h};
    const result=await (reset?window.uiwin.viewer.open(payload):window.uiwin.viewer.update(payload));
    if(token!==bigSendSeq||!viewerOpen) return;
    if(result&&result.ok===false) throw new Error(result.error||'大图窗口打开失败');
    return result;
  }).catch(err=>{
    // 旧请求即使在新窗口成功后才报错，也不能复位新窗口或弹出过期错误。
    if(token!==bigSendSeq||!viewerOpen) return;
    // ⚠ 首次打开就失败时必须把状态放回去。否则 viewerOpen 卡在 true，
    //   窗口又没开，主窗口的滚轮和点击穿透会一起失灵(用户表现为"面板死了")。
    if(reset){ viewerOpen=false; bigTask=null; pvKeepTaskId=null; }
    const why=(err&&err.message)||String(err||'未知原因');
    console.error('[大图] 打开失败:', err);
    ERR.report('VIEWER_OPEN_FAILED',{message:String(why)});
    if(window.UI&&window.UI.toast) window.UI.toast('大图打不开：'+why,'err',4200);
  });
}
// 载入指定序号的图(1基)。只在该图已完成时才有 src。
// ⚠ 切上下张【保留】当前缩放和位移 —— 不带 reset 标记，
//   大图窗口那边的 scale/位移就不会动(用户要求连续看多张不打断视角)。
function loadBigByIdx(idx){
  if(!bigTask) return;
  const total=bigTotal();
  if(idx<1||idx>total) return;
  const shot=bigShotAt(idx);
  if(!shot || !shot.done || !shot.imgId) return;   // 未回真实图片的项不可打开
  bigIdx=idx;
  bigSendImage(shot.imgId, idx, total, false);     // 换图不复位缩放/位移
}
function openBig(imgId, task, idx, originalIdx){
  if(!(window.uiwin&&window.uiwin.viewer)){
    console.warn('[大图] 独立查看窗口接口不可用');
    return;
  }
  pvPrevFocus=document.activeElement;
  // 记住是从哪张任务卡点开的：关掉大图后要保证这张卡的预览还开着。
  pvKeepTaskId=(task&&task.id)||null;
  bigTask=task||null;
  bigOrder=bigTask ? bigTask.shots.map((shot,index)=>({shot,index})).sort((a,b)=>{const rank=x=>x.shot&&x.shot.error?1:(x.shot&&x.shot.done&&x.shot.imgId?0:2);return rank(a)-rank(b)||a.index-b.index;}).map(x=>x.index) : [];
  bigIdx=idx||1;
  viewerOpen=true;
  // reset:true 只在首次打开时带，让新图从 1 倍、居中开始。
  bigSendImage(imgId, bigTask?bigIdx:0, bigTotal(), true);
}
function closeBig(){
  if(!viewerOpen) return;
  if(window.uiwin&&window.uiwin.viewer) window.uiwin.viewer.close();
  // 状态复位统一在 onClosed 里做：不管是这里关的还是用户按 Esc 关的，走同一条路。
}
// 大图窗口没了(Esc / 点空白 / 关闭按钮 / 主窗口销毁) → 复位主窗口状态。
// ⚠ 必须由主进程回调触发，不能只在 closeBig 里复位，
//   否则用户按 Esc 关掉后 viewerOpen 卡在 true，滚轮和点击穿透跟着一起坏。
if(window.uiwin&&window.uiwin.viewer){
  window.uiwin.viewer.onClosed(()=>{
    viewerOpen=false;
    bigTask=null;
    // 预览保持展开，直到鼠标放上去。顺带把它重新点亮：
    // 万一大图开着的这段时间预览被别的路径收掉了，回来也得是开着的。
    if(pvKeepTaskId){
      const pv=document.querySelector('.task-preview[data-preview="'+pvKeepTaskId+'"]');
      if(pv){
        pvKeepOpen=true;
        if(!pv.classList.contains('show')){ pv.classList.add('show'); window.__pv=pv; }
      }
    }
    pvKeepTaskId=null;
    if(pvPrevFocus && typeof pvPrevFocus.focus==='function'){
      try{ pvPrevFocus.focus({preventScroll:true}); }catch(_){ try{ pvPrevFocus.focus(); }catch(__){} }
    }
    pvPrevFocus=null;
  });
  // 大图窗口报"想切上下张"，这里算跳过未完成/失败图之后到底是第几张。
  window.uiwin.viewer.onNav(delta=>{
    if(!viewerOpen||!bigTask) return;
    const dir=Number(delta)>0?1:-1;
    const total=bigTotal();
    let ni=bigIdx+dir;
    while(ni>=1 && ni<=total){const shot=bigShotAt(ni);if(shot&&shot.done&&shot.imgId)break;ni+=dir;}
    if(ni>=1 && ni<=total) loadBigByIdx(ni);
  });
}

// 明确要收预览时(折叠面板 / 滚轮切到别的任务 / 开另一张卡的预览)，
// 顺手解除"看完大图的保持"，否则那个保持会赖在新的预览上。
function clearPreview(){ pvKeepOpen=false; document.querySelectorAll('.task-preview.show').forEach(p=>p.classList.remove('show')); }

// ═══════════════════════════════════════════════════════════
//  悬停触发判定 —— 六条规则(见 docs/12 第五点五节)
//   1 方向性: 向右移动才弹, 向左进入不弹(阈值 3px)
//   2 连通保持: 已弹出且在连通区内, 不论方向一律保持
//   3 斜线容差: 判定区上下各多 20px
//   4 速度过滤: >25px/帧 判定为甩过去, 不触发
//   5 滞回: 进 80 / 出 110
//   6 弹出方向自适应 —— 待做(见文档)
// ═══════════════════════════════════════════════════════════
const EDGE_IN=80, EDGE_OUT=110;   // 滞回: 进/出用不同边界
const PAD_Y=20;                   // 斜线容差: 上下各多留
const DIR_MIN=3;                  // 方向判定最小位移
const SPEED_MAX=25;               // 速度过滤: 超过判定为甩过去

// ⚠ 正在卡面上拖参数条时，横向推进那一套必须停手(2026-09-11)：
//   拖条本来就是往右拉，不拦的话拖到一半二级卡就弹出来了。
//   在 renderGenerationCardFields 里按下置 true，全局 mouseup 复位。
let gcDragging=false;
window.addEventListener('mouseup',()=>{ gcDragging=false; });

let lastMX=null, lastMY=null, lastMoveMs=0;   // lastMoveMs: 上一帧 mousemove 的时间戳(判"中间断过档")
// 推进速度追踪: 用于把"鼠标从左往右推进的速度"映射成二级弹出光的时长。
let pushStartX=null, pushStartT=0;   // 开始往右推的起点X + 时间戳
let pushSpeed=0.7;                   // 推算出的当前推进速度(px/ms), 默认中等
let movingRightPrev=false, lastMXPrevPush=null;   // 上次推进状态(判左移用)

// 给每张主卡插一条右缘光带(触发前的可供性暗示)
cards.forEach(c=>{
  if(!c.querySelector('.edgehint')){
    const h=document.createElement('div'); h.className='edgehint';
    c.appendChild(h);
  }
});

// 取当前 index 对应的任务卡 DOM(任务区是动态增删的)
function topTaskEl(){
  const els = [...tasksEl.querySelectorAll('.task:not(.leaving)')];
  if(!els.length) return null;
  return els[Math.min(tcur, els.length - 1)];
}
// 自由模式展开方向取实际面板位置；普通模式仍沿用既有向右推进规则。
function navigationSide(source,target){
  if(!window.V7FreeMode?.isActive()||!source||!target)return 1;
  const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();
  return b.left+b.width/2<a.left+a.width/2?-1:1;
}
function navigationGapHit(mx,my,source,target){
  if(!window.V7FreeMode?.isActive()||!source||!target)return false;
  const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();
  if(!a.width||!a.height||!b.width||!b.height)return false;
  const left=a.right<=b.left?a.right:b.right<=a.left?b.right:null;
  if(left===null)return false;
  const right=a.right<=b.left?b.left:a.left;
  // 只保留两张关联卡之间有共同高度的走廊，不能把整个空白屏幕接管。
  return mx>=left&&mx<=right&&my>=Math.max(a.top,b.top)-PAD_Y&&my<=Math.min(a.bottom,b.bottom)+PAD_Y;
}
function freeNavigationBridgeHit(mx,my){
  if(!window.V7FreeMode?.isActive())return false;
  if(zones.classList.contains('show')&&navigationGapHit(mx,my,cards[cur],zones))return true;
  if(detail.classList.contains('show')&&navigationGapHit(mx,my,zones,detail))return true;
  const task=topTaskEl(),preview=task?.querySelector('.task-preview.show');
  if(!window.V7WorkspaceStackRail?.isHidden('tasks')&&preview&&navigationGapHit(mx,my,task,preview))return true;
  const error=topErrorEl(),errorDetail=error?._detailEl;
  return !!(!window.V7WorkspaceStackRail?.isHidden('errors')&&errorDetail?.classList.contains('show')&&navigationGapHit(mx,my,error,errorDetail));
}
function navigationHintSide(hint,side){
  if(!hint)return;
  hint.style.left=side<0?'0px':'';hint.style.right=side<0?'auto':'';
  hint.style.transform=side<0?'scaleX(-1)':'';
}
// 判断鼠标是否在"连通区域"(主卡+分区+详情 / 任务卡+预览)内
// ⚠ 用几何矩形判断, 不用 elementFromPoint —— 避免浮层盖住卡片时误判"离开了"
// ⭐ 2026-10-15（用户报）：二级里的下拉框展开后，选项面板是挂在 body 上的浮层（ui-select.js），
//   伸出二级卡外的那一截不在任何卡的矩形里 ⇒ 鼠标移上去被判"离开" ⇒ 二级当场收起。
//   ⇒ 下拉面板开着时，面板自己那块也算连通区（二级、三级的"移出即收"两处都认它）。
function inOpenSelectPanel(mx,my){
  const p=window.UISelect?.isOpen?.()?window.UISelect.panelEl?.():null;
  return !!(p&&hitRect(mx,my,p,0,0));
}
function inConnected(mx,my,kind){
  if(kind==='zones'){
    const c=cards[cur];
    if(c && hitRect(mx,my,c,0,PAD_Y)) return true;
    if(inOpenSelectPanel(mx,my)) return true;
    if(zones.classList.contains('show') && hitRect(mx,my,zones,0,PAD_Y)) return true;
    if(detail.classList.contains('show') && hitRect(mx,my,detail,0,PAD_Y)) return true;
    if(zones.classList.contains('show')&&navigationGapHit(mx,my,c,zones))return true;
    if(detail.classList.contains('show')&&navigationGapHit(mx,my,zones,detail))return true;
    return false;
  }
  const topTask=topTaskEl();
  if(!topTask) return false;
  // ⚠ 2026-10-03 晚：上方那个大预览框也算连通区的一块（用户实测：鼠标移到框上
  //   就被判成"离开"，框当场消失，缩放根本来不及用）。
  //   用户要的规矩：任务卡/预览条 → 大框 → 拉回预览条 = 都算在里面，不许收；
  //   真移出这一整块才一起收。判定在 tween-preview.js 里（它才知道框的矩形）。
  if(window.V7Tween&&typeof V7Tween.boxHit==='function'&&V7Tween.boxHit(mx,my)) return true;
  if(hitRect(mx,my,topTask,0,PAD_Y)) return true;
  // ⚠ 同 overUI: 必须带 .show。隐藏的 .task-preview 依然占着矩形(display:flex 从不置 none)。
  const pv=topTask.querySelector('.task-preview.show');
  return !!(pv && (hitRect(mx,my,pv,0,PAD_Y)||navigationGapHit(mx,my,topTask,pv)));
}

// 自由模式每张一级卡都有自己的屏幕坐标。悬停导航必须按指针实际命中的卡计算，
// 不能沿用普通模式的 cards[cur]，否则非当前卡只有先点击才能触发右滑。
function freeOwnerCard(mx,my,target){
  if(!window.V7FreeMode?.isActive())return null;
  if(target?.closest?.('#tasks,#errors,#zones,#detail'))return null;
  const direct=target?.closest?.('#stack .block-card');
  if(direct&&!direct.hidden&&!direct.matches('.free-group-hidden,.free-pile-buried'))return direct;
  return window.V7FreeMode.cardAtPoint?.(mx,my)||null;
}


window.addEventListener('mousemove',e=>{
  const mx=e.clientX, my=e.clientY;
  if(e.target.closest?.('.v7-floating-bar')||window.V7FloatingBars?.isDragging()){lastMX=mx;lastMY=my;return;}
  if(window.V7FreeMode?.isDragging()||window.V7FreeMode?.isTransitioning()){lastMX=mx;lastMY=my;return;}
  // ⭐ 2026-10-06 晚：悬停手势只被"真正的浮层"拦（见 v7HoverOverlayOpen 的说明）。
  //   报错决定卡（L3）不再冻结右滑；点击/键盘/滚轮仍由 focus-scope 拦着。
  if(v7HoverOverlayOpen()){lastMX=mx;lastMY=my;return;}
  // ⭐⭐ 2026-10-06 晚：只认【看得见】的内嵌工作区来关手势。
  //   hasEmbedded() 只问"dialog 还连着没有" —— 一个挂过又被藏进隐藏详情层的工作区
  //   会让它恒真，全局右滑全部失效（用户实测：标准模式跑一会就不灵，切自由模式正常，
  //   因为自由模式进场会 closeAll→requestCloseAll 把它关掉）。
  //   真开着（看得见）的工作区仍然照旧隔离背景。
  if(window.V7Workspaces?.hasVisibleEmbedded?.()??window.V7Workspaces?.hasEmbedded?.()){lastMX=mx;lastMY=my;return;}
  // 工具工作面开着：底下的卡都让位了，鼠标划过不许再触发"右滑推进/攒光"那套
  if(document.body.classList.contains('v7tw-covering')){lastMX=mx;lastMY=my;return;}
  if(isCollapsed){
    lastMX=mx; lastMY=my;
    return;
  }
  // Tauri resumes a transparent window with a document-targeted mousemove.
  // It starts a new local pointer track; stale coordinates from the previous
  // card must not count as a fast swipe across the whole desktop.
  //
  // ⚠⚠⚠ 2026-10-06：原来这里写的是 `V7FreeMode?.isActive() && e.target===document`
  //   —— 自由模式才复位。自由模式是透明窗口，鼠标划过空地时 target 就是 document，
  //   于是"进入即复位"，永远不携带陈旧 dx；标准模式没有这一条，
  //   而它【正是会被陈旧坐标打中的那个模式】：
  //     点进 PS / 关掉大图窗口 / 切程序回来 → 中间没有任何 mousemove 补上，
  //     lastMX 还停在【上一次离开时的位置】→ 回来的第一帧
  //     dx = 新位置 - 旧位置 可能跨半屏 → speed>25 → tooFast → **第一推被吞**。
  //   这就是"时灵时不灵、再推一下就好"的来源。
  //
  //   ⇒ 改成【按事件间隔判】：连续移动的两帧间隔是 8~16ms，
  //     间隔一大（>200ms）就说明中间断过档（切窗口/失焦/鼠标移出又回来），
  //     这一帧的位移【不算】速度，只当作新的起点。
  //     ⚠ 不能用 `e.target===document` 来判：标准模式下从卡上往右推进时，
  //       指针越过卡右缘后 target 也会变成 document —— 那一帧一复位，
  //       dx 永远到不了 DIR_MIN(3)，手势就被自己判死了。
  const nowMs=e.timeStamp||performance.now();
  const staleGap = lastMoveMs!==0 && (nowMs-lastMoveMs)>200;
  lastMoveMs=nowMs;
  if(staleGap){pushStartX=null;pushStartT=0;movingRightPrev=false;lastMXPrevPush=null;}
  const dx = lastMX===null||staleGap ? 0 : mx-lastMX;
  const dy = lastMY===null||staleGap ? 0 : my-lastMY;
  lastMX=mx; lastMY=my;

  const speed = Math.abs(dx)+Math.abs(dy);
  const movingRight = dx >= DIR_MIN;      // 规则1: 向右
  const tooFast = speed > SPEED_MAX;      // 规则4: 甩过去

  // ── 推进速度追踪(用于二级光时长) ──
  //   ⚠ 鼠标左移就重新计算: 一旦不回右(不往右推), 就重置推进起点, 下次往右推从新起点重算。
  const now = performance.now();
  if(movingRight && !tooFast){
    if(pushStartX===null || lastMXPrevPush === null || !movingRightPrev){ pushStartX=mx; pushStartT=now; }
    else if(mx > pushStartX){
      const dt = now - pushStartT;
      pushSpeed = dt>8 ? (mx - pushStartX)/dt : pushSpeed;   // 平均推进速度, 防 dt 过小除零
    }
  }else{
    // 左移/停 → 重新计算起点
    if(mx < lastMX || !movingRight){ pushStartX=null; }
  }
  movingRightPrev = movingRight; lastMXPrevPush = mx;

  // 正在拖卡面上的参数条 → 横向推进/光效全部停手，否则拖到一半会弹出二级。
  // ⚠⚠ 2026-10-06 晚加自愈：没按着鼠标左键就不可能"还在拖"。
  //   mouseup 若丢在窗口外/被别的东西吃掉，gcDragging 会一直为真，
  //   表现是"右滑整个失效、还不报错"，只有随便点一下鼠标才恢复。
  if(gcDragging && !(e.buttons&1)) gcDragging=false;
  if(gcDragging) return;

  // ⭐⭐⭐ 2026-10-04 用户实测报的「自由模式右滑：一旦弹出的内容触及到别的卡片，
  //   别的卡片会被直接唤醒，我原来拉起的卡片会被挤占掉」。
  //   ⚠⚠ 真因就在下面这两行【以前没有护栏】：
  //     鼠标只要划到另一张自由卡上，就无条件 activateCard(那张) 抢走属主。
  //     而 activateCard → selectCard(next)（raise:false）里第一件事就是
  //     closeAll() —— 于是【刚拉起来的二级被当场收掉】，用户看到的就是"被挤占"。
  //   为什么是"偶发"：要鼠标恰好扫过另一张卡的矩形才触发；
  //     停在原地不动、或者两张卡离得远，就一次都碰不上。
  //   ⇒ 正解（也是那条注释本来就写明的意思——"已经拉起的链路属于它原来的主卡"）：
  //     【链子开着的时候，悬停不许换属主】。要换卡就真点一下（点击那条路径
  //     走 selectCard 会自己 closeAll 并切过去，语义清楚）。
  //   ⚠ 为什么用 zoneOpen 而不是"宽限时间"：这不是时序竞态（用户以为是，
  //     其实是【两个真源不同步】的老毛病，见 docs/137 §十一）。开没开是一个
  //     确定的状态，用状态判断才不会在慢机器上时灵时不灵。
  //   ⚠ 也不能一律禁掉悬停换属主：二级/三级都没开的时候，用户划过一张卡就该
  //     能直接右滑它（自由模式每张卡有自己的屏幕坐标，不能只认 cards[cur]）。
  const chainOpen = zoneOpen || detail.classList.contains('show');
  if(!chainOpen){
    const freeOwner=freeOwnerCard(mx,my,e.target);
    if(freeOwner&&freeOwner!==cards[cur])window.V7FreeMode.activateCard?.(freeOwner);
  }

  // ══ 三级"没用过就走"→ 收起二级三级(2026-08-29 用户方案) ══
  // 条件三个都满足才收: ① 三级开着且【没被操作过】(没点按/滚动/滚轮)
  //   ② 鼠标已移出三级卡的矩形 ③ 移出方向【不是往二级走】(即不是往左)
  // 意图: 误触或只看一眼就往外走 → 自动收干净; 真在用它(动过) → 不收, 安心用。
  // ⚠ 不加缓冲(用户定案): 移出即判定。停留不算操作。
  if(detail.classList.contains('show') && !detailUsed){
    const dr = detail.getBoundingClientRect();
    const outOfDetail = !(mx>=dr.left && mx<=dr.right && my>=dr.top && my<=dr.bottom) && !inOpenSelectPanel(mx,my);
    // 往二级走 = 往左(二级在三级左边)。往右/上/下离开都算"走了"。
    // (路线 A 的提示词框现在是真二级卡 #promptZone, 不再借用 #detail, 这条规则只管三级。)
    const towardZones = window.V7FreeMode?.isActive()
      ? hitRect(mx,my,zones,0,PAD_Y)||navigationGapHit(mx,my,zones,detail)||hitRect(mx,my,cards[cur],0,PAD_Y)||navigationGapHit(mx,my,cards[cur],zones)
      : mx < dr.left;
    if(outOfDetail && !towardZones) closeAll();
  }

  // ── 主卡 → 分区 ──
  if(!detail.classList.contains('show')&&!cards[cur].classList.contains('free-collapsed')){
    const c=cards[cur];
    const r=c.getBoundingClientRect();
    const hint=c.querySelector('.edgehint');
    const side=navigationSide(c,zones),movingToward=dx*side>=DIR_MIN;
    const inY = my>=r.top-PAD_Y && my<=r.bottom+PAD_Y;            // 规则3: 斜线容差
    const distFromEdge = side>0?mx-(r.right-4):r.left+4-mx;
    const inZoneIn  = inY && distFromEdge>=0 && distFromEdge<=EDGE_IN;
    const inZoneOut = inY && distFromEdge>=0 && distFromEdge<=EDGE_OUT;

    // ⭐⭐ 2026-10-06 晚（第二次，按实测路径改）：任务预览链开着时，直接【不许开二级】。
    //   实测复现：标准模式里一级卡就在任务卡正上方、大框左缘又压在它的触发带上，
    //   摸大框的"斜上右"路线会经过一级卡 → 被判成"右推开二级" → 二级一开，
    //   预览整体让位（concedeToMainCards）→ 闪回 / 时灵时不灵。
    //   自由模式不犯：任务堆不在主卡正下方，摸大框不经过主卡。
    //   ⇒ 规则从上一版的"0.4s 内摸过卡才让开"改成"预览链开着就不开"：
    //     要开二级先把预览收掉（鼠标移开 >160ms 它自己会收）。行为可预测，没有误判路径。
    //     ⚠ 真"在卡上往右推"的手感不受影响：那时预览链没开。
    const boxState=(window.V7Tween&&typeof V7Tween.boxState==='function')?V7Tween.boxState():null;
    const taskPreviewOn=!!document.querySelector('.task-preview.show')||!!(boxState&&boxState.open);

    // 光晕: 鼠标在主卡上越靠右、或推到右缘外的触发区, 光晕越强(触发前暗示)
    //   ⚠ 基准用【主卡本身】而不是"画面中心"(主卡在屏幕左, 右缘在中心左边,
    //     以中心为基准会算出负值永远不亮)。进度: 卡片中点→右缘=0~1, 进触发区封顶。
    //   ⚠【只在二级/三级都未开时显示】—— 一旦弹出, 光晕立即归零, 且不再被 mousemove 更新,
    //     否则会停在最高亮残留 + 随鼠标闪烁。离开主卡区也强制归零。
    if(hint){
      navigationHintSide(hint,side);
      const canShow = !zoneOpen && !detail.classList.contains('show') && !taskPreviewOn;
      const inCard = hitRect(mx,my,c,0,PAD_Y) || inZoneOut;   // 鼠标在主卡范围或右缘触发带
      if(canShow && !tooFast && inCard){
        const mid = r.left + r.width/2;
        const rightEdge = r.right;
        const t = Math.min(1, Math.max(0, side*(mx - mid) / (rightEdge - mid)));
        if(inZoneIn){
          hint.style.opacity = '1';
          hint.style.width  = '44px';
        }else if(t > 0){
          const p = Math.pow(t, 1.3);
          hint.style.opacity = String(0.15 + p * 0.75);
          hint.style.width  = String(p * 40) + 'px';
        }else{
          hint.style.opacity = '0';
          hint.style.width  = '0px';
        }
      }else{
        hint.style.opacity = '0';
        hint.style.width  = '0px';
      }
    }

    if(!zoneOpen){
      // 规则1+4: 只有向右移动、且不是甩过去, 才弹
      // ⚠ 2026-10-06 晚：预览链开着 → 不许开（见上面 taskPreviewOn 的实测说明）
      if(inZoneIn && movingToward && !tooFast && !taskPreviewOn){
        // ⚠ 路线 A(预设卡专属, 用户 2026-09-11 定案): 从剪影卡右滑 → 【提示词框直接当二级】。
        //   不弹预设列表(那是点部位才有的路线 B)。提示词框本体就是 #detail，只是挪到二级的位置。
        if(isPresetCard()){
          openPresetZone('prompt', true);
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⚠⚠ 2026-10-03 晚【真凶在这】：单张大二级的那几张卡（外挂能力 / 记录 / 设置），
        //   右滑走到这里【没有分支】→ 直接掉进下面的通用逻辑：
        //     ① fillZonesNow() 只填 `.zone:not(.pzone)`，而这几张卡的二级就是 .pzone
        //        → 它【一个子卡都没填】，而且 syncZoneKind 还顺手把它们全 display:none
        //     ② 于是 #zones 亮起来了、里面却【一个可见子卡都没有】
        //     ③ #zones 自身没有宽高，全靠子卡撑 → 空容器 = 0 宽
        //     ④ 下一个 mousemove：inConnected('zones') 量到 0 宽 → 判定"鼠标不在连通区"
        //        → closeZones() 立刻把它收了
        //   用户看到的就是【右滑打不开二级】（或闪一下就没）。
        //   ⚠ 为什么是"有时候能开"：卡的 state.open 是【粘的】——
        //     从别处（点能力行 / 路由进来）开过一次之后它一直是 true，
        //     engOn 就变真，右滑侥幸能开。这正是用户怀疑的"竞态"的真正来源：
        //     不是时序竞争，是【宿主 zoneOpen 与卡片 state.open 两个真源不同步】。
        //   ⇒ 正解：跟预设卡一个待遇 —— 右滑先让【卡自己】开，
        //     卡开的时候会回调 host.onOpen → enginesOpenZone()，宿主那一半自然就位。
        //     ⚠ 只调 enginesOpenZone() 是不够的：它只露容器，不改卡片 state.open，
        //       而 syncZoneKind 下一步就会把 zone 收回 display:none（这就是原 bug）。
        if(isEnginesCard()){
          if(enginesCard&&typeof enginesCard.open==='function'){
            // ⚠ 默认页从 'engine' 改成 'config'（配置信息）—— 右栏换成了四页导航，
            //   老的 'engine' 这一页已经不存在了，传它会静默落到第一页（行为对、名字错）。
            enginesCard.open(enginesCard.zoneId()||'config','swipe');
          }
          enginesOpenZone();          // 兜底：卡还没建起来时至少把容器露出来
          // ⭐ Phase B：右滑也是一次"卡打开"，刷一次状态出口（docs/150 §4.1 刷新时机）。
          enginesStatusRefresh(false).catch?.(()=>{});
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐⭐⭐ 2026-10-04 用户实测报的「设置卡右滑有时打不开 / 闪一下就没」（docs/137 §十一）
        //   ⚠⚠ 这跟上面外挂卡那条是【同一个 bug、同一处漏网】，只是漏的是另一张卡。
        //   真因（逐条）：
        //     ① 右滑走到这里，设置卡【没有分支】→ 掉进下面的通用逻辑
        //     ② 通用逻辑先调 fillZonesNow()，而它遇到设置卡【直接 return，什么都不填】
        //        （见 fillZonesNow 里 `if(isSettingsCard()){ return; }`）
        //     ③ 而 fillZonesNow 第一行就是 syncZoneKind()，它按
        //        `settingsCard.isOpen()` 决定 display —— 此刻卡还没开 → **把 zone 收成 display:none**
        //     ④ ⇒ #zones 亮起来了、里面一个可见子卡都没有 → 容器 0 宽
        //     ⑤ 下一个 mousemove：量到 0 宽 → 判"鼠标不在连通区" → closeZones() 立刻收掉
        //   ⇒ 用户看到的就是「闪一下就没」。
        //   ⚠ 为什么"有时候能开"：卡的 state.open 是【粘的】——
        //     从路由 / 点正脸状态行进来开过一次之后它一直是 true，
        //     setOn 就变真，右滑侥幸能开。**这就是他怀疑的"偶发静态"的真正来源：
        //     不是时序竞争，是【宿主 zoneOpen 与卡片 state.open 两个真源不同步】。**
        //   ⇒ 正解：跟外挂卡/预设卡一个待遇 —— 右滑先让【卡自己】开，
        //     卡开的时候会回调 host.onOpen → settingsOpenZone()，宿主那一半自然就位。
        if(isSettingsCard()){
          var setCard=settingsCardMount();
          if(setCard&&typeof setCard.open==='function'){
            // ⚠ tab 不传：让它自己按当前存的 state.tab 走。传了会把用户上次看的页踢回第一页。
            setCard.open(null,null);
          }
          settingsOpenZone();         // 兜底 + 宿主那一半（zoneOpen / .show / 清场定时器）
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐ 生成卡（2026-10-15 改成单张大二级）：跟设置卡同一个写法 —— 先让卡自己开，再露宿主那一半。
        //   ⚠ 不写这个分支 = 掉进下面的通用逻辑 = 设置卡 10-04 那个"闪一下就没"的 bug 原样重演。
        if(isGenerationCard()){
          var genCard=generationCardMount();
          if(genCard&&typeof genCard.open==='function') genCard.open(null,null);
          generationOpenZone();
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐ 助手卡（2026-10-17 夏三六）：同生成卡 —— 先让卡自己开，再露宿主那一半（不写这个分支 = 「闪一下就没」）。
        if(isAssistantCard()){
          var asCard=assistantCardMount();
          if(asCard) asCard.open(null);
          assistantOpenZone();
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐ 问题反馈卡（2026-10-18 深夜）：同生成卡 —— 先让卡自己开，再露宿主那一半。
        if(isFeedbackCard()){
          var fbCard=feedbackCardMount();
          if(fbCard) fbCard.open(null,null);
          feedbackOpenZone();
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐ 社区卡（2026-10-20）：同上 —— 先让卡自己开，再露宿主那一半。
        if(isCommunityCard()){
          var ccCard=communityCardMount();
          if(ccCard) ccCard.open(null,null);
          communityOpenZone();
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⭐⭐⭐ 同上：记录卡也是【单张大二级】，右滑同样没有分支（2026-10-04 一并补）
        //   ⚠ 记录卡跟设置卡的区别：它的 open() 需要【一个项目 id】（openProject）。
        //     右滑没有指定项目 → 用第一个项目，跟路由进来时的做法一致
        //     （见 ui.html:13227 `recordsCard.openProject(first.project,'route')`）。
        if(isRecordsCard()){
          var recCard=recordsCardMount();
          if(recCard&&typeof recCard.openProject==='function'){
            var recFirst=null;
            try{ recFirst=(recCard.projectList()||[])[0]||null; }catch(_){}
            if(recFirst&&recFirst.project) recCard.openProject(recFirst.project,'swipe');
          }
          recordsOpenZone();          // 兜底 + 宿主那一半
          if(hint) hint.style.opacity='0';
          return;
        }
        // ⚠ 先按当前 cur 填内容, 再加 .show —— 否则二级会显示上一个主卡的旧内容。
        //   (二级未开时切主卡不会触发 syncZonesToCard, 静态 HTML 没更新)
        // A previous owner's closing animation must not later clear this new chain.
        if(allCloseTimer){clearTimeout(allCloseTimer);allCloseTimer=null;}
        if(zoneCloseTimer){clearTimeout(zoneCloseTimer);zoneCloseTimer=null;}
        fillZonesNow();
        zoneOpen=true; zones.classList.remove('closing'); zones.classList.add('show');
        // 【整条链路统一跟鼠标速度】二级滑入动画的时长 + 光的时长, 都从同一个 pushSpeed 算,
        //   三者(滑入/光带/亮线)同速, 不脱节。快推整体快, 慢推整体慢。
        const pv = Math.max(0.15, Math.min(2.0, pushSpeed));
        const t = (pv - 0.15) / (2.0 - 0.15);                    // 归一化 0~1
        const durS = 0.9 - Math.pow(t, 1.6) * (0.9 - 0.40);      // 幂: 中低速拖长, 快速才短
        // 二级卡滑入动画时长 = durS(覆盖 CSS 的 var(--dur)); opacity 同步
        document.querySelectorAll('#zones .zone').forEach(z=>{
          z.style.transitionDuration = durS + 's, ' + durS + 's, .15s';   // transform, opacity, border-color
        });
        // 光带 + 亮线 一起, 用同一个 durS(同速, 不脱节)
        document.querySelectorAll('#zones .zone .zone-glow').forEach(gl=>{
          gl.style.animationDuration = durS + 's';
          gl.classList.remove('glow');
          void gl.offsetWidth;             // 强制回流, 让连续弹出也能重播动画
          gl.classList.add('glow');
        });
        document.querySelectorAll('#zones .zone .zone-bright').forEach(gl=>{
          gl.style.animationDuration = durS + 's';
          gl.classList.remove('glow');
          void gl.offsetWidth;
          gl.classList.add('glow');
        });
        if(hint) hint.style.opacity='0';
      }
    }else{
      // 规则2: 已弹出 → 在连通区内一律保持, 不看方向
      // 规则5: 滞回 —— 用更大的 EDGE_OUT 判定离开
      // ⚠【二级 → 三级】鼠标在二级上往右推进到二级区右缘触发区 → 弹三级带光.
      //   二级右缘触发区宽度按比例(二级200 vs 一级300, EDGE_IN 80→53); 鼠标Y落在哪个分区就弹哪个.
      // ⚠ 预设卡(路线 B, 列表当二级): 在【某一行】上右滑 = 弹那一行的三级, 跟普通二级卡一样。
      //   不在任何行上(空白/工具条)右滑则什么都不做 —— 不弹空框。(用户 2026-09-11 定案)
      if(!detail.classList.contains('show') && isPresetCard() && presetZoneKind==='list' && presetZoneEl){
        const zr = presetZoneEl.getBoundingClientRect();
        const detailSide=navigationSide(presetZoneEl,detail);
        const zInY = my >= zr.top - PAD_Y && my <= zr.bottom + PAD_Y;
        const zDist = detailSide>0?mx-zr.right:zr.left-mx;
        const edIn = Math.round(EDGE_IN * 200/300);
        if(zInY && zDist >= 0 && zDist <= edIn && dx*detailSide>=DIR_MIN && !tooFast && window.PRESETUI){
          // 右缘触发区里没有行元素可命中，所以按【鼠标 Y】找同一高度上的那一行
          const row=[...presetZoneEl.querySelectorAll('.pz-row')].find(r=>{
            const rr=r.getBoundingClientRect(); return my>=rr.top && my<=rr.bottom;
          });
          if(row) PRESETUI.loadPresetById(row.dataset.presetId, true);
        }
      }
      // ⚠ 记录卡没有三级，不许从这里被推出来（2026-09-30，docs/96 问题一的第 2 条路径）。
      if(!detail.classList.contains('show') && !isPresetCard() && !isRecordsCard()){
        const zr = zones.getBoundingClientRect();
        const detailSide=navigationSide(zones,detail);
        const zInY = my >= zr.top - PAD_Y && my <= zr.bottom + PAD_Y;
        const zDist = detailSide>0?mx-zr.right:zr.left-mx;
        const edIn = Math.round(EDGE_IN * 200/300);        // 按比例缩触发区
        // ── 二级预告光(照一级): 鼠标在某张二级卡上过中线往右移 → 该卡右缘实时渐亮 ──
        // ⚠⚠ 2026-10-08：光要跟着"这张卡到底有没有三级"走。
        //   没有三级的卡（设置/外挂/记录）如果还亮这个光，用户看到的是
        //   "右边有东西能拉出来"——而拉出来什么都没有 ⇒ 比不亮更糟（假承诺）。
        //   守门的判据同 openDetail：V7CardRegistry.hasDetail(当前卡)。
        const hintCardId = (cards[cur] && cards[cur].dataset && cards[cur].dataset.card) || '';
        const hintRegistry = window.V7CardRegistry;
        const hintAllowed = !(hintCardId && hintRegistry && typeof hintRegistry.hasDetail === 'function'
          && !hintRegistry.hasDetail(hintCardId));
        zones.querySelectorAll('.zone:not(.pzone)').forEach(zn=>{
          const eh = zn.querySelector('.zone-edgehint');
          if(!eh) return;
          if(!hintAllowed){ eh.style.opacity='0'; eh.style.width='0px'; return; }
          navigationHintSide(eh,detailSide);
          const zb = zn.getBoundingClientRect();
          const onThis = my >= zb.top - PAD_Y && my <= zb.bottom + PAD_Y;
          const distance=detailSide>0?mx-zb.right:zb.left-mx;
          const inTrig = onThis && distance >= 0 && distance <= edIn;
          if(onThis && !tooFast){
            const mid = zb.left + zb.width/2;
            const tt = Math.min(1, Math.max(0, detailSide*(mx - mid) / (zb.right - mid)));
            if(inTrig){
              eh.style.opacity = '1';
              eh.style.width = '29px';              // 峰值按二级卡宽比例(同弹出光)
            }else if(tt > 0){
              const pp = Math.pow(tt, 1.3);
              eh.style.opacity = String(0.15 + pp * 0.75);
              eh.style.width = String(pp * 26) + 'px';
            }else{
              eh.style.opacity = '0'; eh.style.width = '0px';
            }
          }else{
            eh.style.opacity = '0'; eh.style.width = '0px';
          }
        });
        if(zInY && zDist >= 0 && zDist <= edIn && dx*detailSide>=DIR_MIN && !tooFast){
          // 鼠标 Y 落在哪张分区, 就选哪个分区(用每个 .zone 的矩形判断)
          zones.querySelectorAll('.zone:not(.pzone)').forEach(zn=>{
            const znRect = zn.getBoundingClientRect();
            if(my >= znRect.top - PAD_Y && my <= znRect.bottom + PAD_Y){
              const zIdx = parseInt(zn.dataset.z);
              if(zIdx !== zoneSel) selectZone(zIdx);
            }
          });
          // 弹三级(带光): show + 填充内容 + 触发三级光
          openDetail(true);
        }
      }
      // ⚠ 三级是靠二级当标题的: 三级一开, 二级+三级都常驻, 鼠标移走都不收.
      //   只有明确关闭(Esc/点面板外/失焦)才一起收。三级未开时才按"移出即收二级"。
      if(!detail.classList.contains('show')){
        if(inConnected(mx,my,'zones')) zonesOpenedByNav=0;          // 进来过了：之后照老规矩
        else if(!inZoneOut && !zonesOpenedByNav) closeZones();       // ⭐ 10-19：点按钮跳出来的、鼠标还没进来过 → 不收
      }
    }
  }

  // ── 任务卡 → 预览 ──
  // 【独立于主卡链路】主卡的分区/详情开着时, 任务预览照样能弹, 两条链路互不干扰。
  {
    const topTask=topTaskEl();
    if(topTask){
      const r=topTask.getBoundingClientRect();
      const pv=topTask.querySelector('.task-preview');
      const side=navigationSide(topTask,pv);
      const inY = my>=r.top-PAD_Y && my<=r.bottom+PAD_Y;
      const distFromEdge = side>0?mx-(r.right-4):r.left+4-mx;
      const inZoneIn  = inY && distFromEdge>=0 && distFromEdge<=EDGE_IN;
      const inZoneOut = inY && distFromEdge>=0 && distFromEdge<=EDGE_OUT;
      const pvOpen = pv && pv.classList.contains('show');

      // ⚠⚠⚠ 全文件【只此一处】定义 hoverAutoOpen —— 下面的 else 分支里
      //   原来还有一个同名的局部变量，2026-10-09 实测栽过：
      //   两个同名、不同作用域 ⇒ 改开关只对一半的路生效（看着像「开关没用」）。
      //   ⇒ 已经统一到这里。**以后别再写第二个。**
      //   ⚠ 它管的是「大图会不会【自动】弹出来」：
      //     · 朝预览条方向移动时弹条+弹框（下面第一处）
      //     · 悬停就开（下面第二处）
      //     ✗ 不管「点缩略图」那条 —— 那是用户主动点的，开关关掉之后照样能开。
      //   ⚠ `!== false` 而不是 `=== true`：老存档里没这个键时按【开】处理。
        // ⚠ `!boxAutoOpenSuppressed()`：用户刚手动收起过 —— 1.5 秒内别再自动弹，
      //   否则"点了关不掉"（鼠标还停在上面，同一次交互会立刻弹回来）。
      const hoverAutoOpen=(typeof settingsRuntime!=='object'||settingsRuntime.hoverOpensPreview!==false)
        && !boxAutoOpenSuppressed();

      // ── 任务卡预告光(跟一/二级同款): 鼠标在任务卡上过中线往右移 → 右缘实时渐亮 ──
      const teh = topTask.querySelector('.task-edgehint');
      if(teh){
        navigationHintSide(teh,side);
        const onCard = hitRect(mx,my,topTask,0,PAD_Y);  // ⚠ 只在鼠标真的在卡片上时才显示光效, 不包含触发区
        if(!pvOpen && !tooFast && onCard){
          const mid = r.left + r.width/2;
          const tt = Math.min(1, Math.max(0, side*(mx - mid) / (r.right - mid)));
          if(inZoneIn){
            teh.style.opacity='1'; teh.style.width='44px';    // 峰值同一级(任务卡也300宽)
          }else if(tt > 0){
            const pp = Math.pow(tt, 1.3);
            teh.style.opacity = String(0.15 + pp * 0.75);
            teh.style.width = String(pp * 40) + 'px';
          }else{
            teh.style.opacity='0'; teh.style.width='0px';
          }
        }else{
          teh.style.opacity='0'; teh.style.width='0px';
        }
      }

      if(!pvOpen){
        if(inZoneIn && dx*side>=DIR_MIN && !tooFast && pv){
          clearPreview();                 // 先清别的, 再开自己(顺序不能反, 否则自己关自己)
          pv.classList.add('show');
          window.__pv=pv;                 // 保持标记已在上面的 clearPreview() 里解除
          // ⭐⭐⭐ 2026-10-09（用户报「只出缩略图条、不点大图，移开鼠标条不消失」）：
          //   **条弹出来的这一刻就要认下它归属谁**，跟"弹不弹大图"无关。
          //   ⚠⚠ 为什么必须在这里补：原来"认归属"只发生在 hoverTaskCard 里，
          //     而下面那个 if 被设置项挡着（关掉就不调）⇒
          //     **那个开关顺手把"归属登记"也一起关掉了** ⇒ 收框时 notifyId 是 null
          //     ⇒ 收条通知发不出去 ⇒ 条永远赖着（用户实测）。
          //   ⚠ 这是"收条唯一出口"的前置条件，漏了它整条收尾都断。
          //     以后谁把条弹出来，谁就得顺手登记一下（别再依赖 hoverTaskCard）。
          if(window.V7Tween && typeof V7Tween.setBoxOwner==='function'){
            V7Tween.setBoxOwner(topTask.dataset.task);
          }
          // ⭐ 2026-10-04：预览条弹出的同时，上方弹大预览框（docs/132 §2.2）。
          //   ⚠ 只在这一处调 —— 别在别的地方再调一次，会跟"预览条的开关"脱节。
          // ⭐⭐ 2026-10-09（docs/191）：这一条受设置「鼠标移到缩略图上自动弹出大预览框」管。
          //   ⚠⚠ 追踪器实测抓到的就是这里（栈指向本行）—— 用户说的悬停就弹
          //     其实是「朝预览条方向移动时，条和大图一起弹出来」。
          //   ⚠ 关掉之后【预览条照旧弹】（那是右滑手势，用户 10-04 定的手感，不改），
          //     只是【大图不自动弹】—— 想看大图点一下缩略图（走 openShot）。
          if(hoverAutoOpen && window.V7Tween && taskList.length){
            const curTask=taskById(topTask.dataset.task);
            if(curTask) window.V7Tween.hoverTaskCard(topTask,curTask);
          }
          // 预览弹出 → 任务卡左缘播弹出光(光带+亮线), 速度跟鼠标推进(同二三级)
          const pvv=Math.max(0.15, Math.min(2.0, pushSpeed));
          const tt2=(pvv-0.15)/(2.0-0.15);
          const durT=0.9 - Math.pow(tt2, 1.6)*(0.9-0.40);
          ['.task-glow','.task-bright'].forEach(cls=>{
            const gl=topTask.querySelector(cls);
            if(gl){
              gl.style.animationDuration=durT+'s';
              gl.classList.remove('glow');
              void gl.offsetWidth;
              gl.classList.add('glow');
            }
          });
          if(teh){ teh.style.opacity='0'; teh.style.width='0px'; }   // 预告光让位给弹出光
        }
      }else{
        // ⭐⭐ 2026-10-06 晚：条开着但【框没开】或框指着别的任务时，再推右要把框叫回来。
        //   旧行为是"pvOpen 就什么都不做" —— 一旦进入"条活着、框死了"，
        //   后面每一次右滑都像坏了（用户实测"第一下正常、后面全不正常"）。
        //   门和弹出完全同一套（在触发带内 + 本帧右移≥3 + 不是甩），不会误触；
        //   框已经正常开着、且就是这张任务时【什么都不做】（不打扰缩放/平移）。
        // ⭐⭐ 2026-10-09（docs/191）：这条【也】受「鼠标移到缩略图上自动弹出大预览框」管。
        //   ⚠ 它跟上面 8102 那条是同一类 —— 都是"往预览条方向推一下就把大图叫出来"。
        //     追踪器实测：开关关掉后栈指向本行 ⇒ 说明只关 8102 不够，这里也必须关。
        //     （教训：**"自动弹"有几个入口就要加几道门**。我连漏两次，都是靠栈抓出来的。）
        if(hoverAutoOpen && inZoneIn && dx*side>=DIR_MIN && !tooFast && pv && window.V7Tween && typeof V7Tween.boxState==='function'){
          const owner=V7Tween.boxState();
          const curTask=taskById(topTask.dataset.task);
          if(curTask && (!owner||!owner.open||String(owner.taskId)!==String(topTask.dataset.task))){
            window.V7Tween.hoverTaskCard(topTask,curTask);
          }
        }
        // ⭐⭐⭐ 2026-10-09 修（用户实测：「悬停在已完成的任务上本来会直接打开大图；
        //   但在详情页滚轮切过任务之后，就要点一下才打开」）：
        //
        //   真因：触发大图的门【一直只有"右滑"这一条】——
        //     详情没开 → `if(!pvOpen)` 分支里右滑（dx≥3）才弹；
        //     详情已开 → 上面那个分支，同样要求再右滑一次。
        //   ⇒ 悬停本身从来不是触发器，它是"右滑弹出"的【副产品】。
        //     所以"详情没开、你右滑一次"看起来像"悬停就开"；
        //     而滚轮切过任务之后【详情一直开着】，就只剩"再右滑一次"那条路
        //     ⇒ 表现成"要点一下"（点击有它自己的 openShot 入口，所以点了能开）。
        //
        //   ⇒ 补一条【悬停就开】：详情已经开着、鼠标就在这张任务卡上
        //     （走到这里说明在 inZoneIn 触发带内），就直接把大图叫出来。
        //   ⚠ 只补"详情已开"这一半 —— 详情没开时不能悬停就弹，
        //     那会跟"右滑才弹"打架（用户 10-04 定的手感）。
        //   ⚠ 没有成品图就别叫：hoverTaskCard 自己有 firstReadyShot 那道闸，
        //     这里先判一下是为了【不去占 boxTaskId】（否则会让归错人）。
        //
        // ⭐⭐ 2026-10-09（用户要求）：这一条【悬停就开】现在受设置开关控制。
        //   用户原话：「在设置里面的交互行为里面添加一项，就是默认开启的一项功能，
        //             鼠标选中交互图像时自动弹出预览框，如果说把这个东西关了，
        //             那就只有我点下去之后才会出现大图预览」。
        //   ⚠ 门只加在【这里】—— 上面那个"右滑 ≥3px 才弹"的分支
        //     （inZoneIn && dx*side>=DIR_MIN，用户 10-04 定的手感）【一个字不改】。
        //     理由：关掉开关的语义是"别自动弹"，不是"把右滑也废掉"；
        //     而且右滑本来就需要用户主动推一下，不属于"自动"。
        //   ⚠ 关掉之后点缩略图照样能开（走 buildPreview 里 img 的 click → openShot），
        //     所以这不是"把功能关死"。
        //   ⚠ 读的是 settingsRuntime.hoverOpensPreview，默认 true（保持现在的手感）。
        //     `!== false` 而不是 `=== true`：老存档里没有这个键时按【开】处理，
        //     绝不能让升级后的默认行为变成"悬停不弹了"。
        if(hoverAutoOpen && pv && window.V7Tween && typeof V7Tween.boxState==='function'){
          const hoverTask=taskById(topTask.dataset.task);
          const hasShot=!!(hoverTask && (hoverTask.shots||[]).some(function(s){
            return s && (hoverTask.kind==='generation' ? s.restoreState==='done' : s.done) && s.imgId; }));
          if(hoverTask && hasShot){
            const own=V7Tween.boxState();
            if(!own||!own.open||String(own.taskId)!==String(hoverTask.id)){
              window.V7Tween.hoverTaskCard(topTask,hoverTask);
            }
          }
        }

        if(!inConnected(mx,my,'task') && !inZoneOut){
          // ⚠ 看完大图回来时不收：大图是独立窗口，关掉的瞬间鼠标多半停在屏幕中央，
          //   按正常规则会立刻判定"鼠标不在预览上"把预览收掉，用户就得重新推一次才能看下一张。
          //   保持到用户真的把鼠标放上来为止(下面那个分支解除)。
          if(!pvKeepOpen){
            // ⚠⚠⚠ 2026-10-06：【这里不再自己收！】只把"该收了"这件事交给 V7Tween，
            //   由它【一个判据】把预览条和预览框一起收掉。
            //
            //   为什么绕这一下 —— 这一段我连着改错两次，教训写清楚：
            //
            //   原版（10-05 之前）：这里【立刻】把条收掉，再调 leaveTaskCard()，
            //     而后者 160ms 后【又判一次】stillInPreviewChain（它包含"指针在不在框上"）。
            //     等那一次判断时鼠标多半正停在框上 → 判成"还在" → 框留着。
            //     ⇒ **条没了、框还在** —— 就是用户报的「预览窗口活着，小图标窗口死了」。
            //     根因：一次离开被【两个地方各自判了一次】，两次结论不一致。
            //
            //   我的第一版修法：这里改成"立即把框和条一起收"（hideBoxIfTask）。
            //     条和框倒是同步了，但【丢掉了 160ms 宽限期】——
            //     任何一次瞬时的不连通（框刚弹出、几何还在变）都会立刻双杀，
            //     下一次 mousemove 又满足弹出条件 → 重新弹出。
            //     ⇒ **弹出即闪回**（用户 10-06 报的，标准模式必现、自由模式正常）。
            //
            //   现在：这里【一个字都不动 DOM】，只在离开时喊一声 leaveTaskCard()。
            //     收不收、什么时候收，全由 tween-preview 那【一个】判据说了算：
            //       160ms 内指针回到连通区 → 什么都不发生（宽限）
            //       真走了 → hideBox() → 它反手把预览条也收掉（onBoxClosed 回调）
            //     这样"条和框"必然同生同死，而且保留了防抖。
            if(window.V7Tween&&typeof window.V7Tween.leaveTaskCard==='function'){
              window.V7Tween.leaveTaskCard();
            }else{
              // 兜底：V7Tween 没加载时退回老行为（至少别让条赖着）
              pv.classList.remove('show');
              if(window.__pv===pv) window.__pv=null;
            }
          }
        }else if(pvKeepOpen){
          pvKeepOpen=false;   // 鼠标已经放到预览/连通区上 → 保持解除, 之后按正常规则收
        }
      }
    }
  }

  // ── 报错卡 → 展开 ──
  // 【报错详情层展开】向右推进显示详情层(跟任务预览同款), 带预告光和弹出光
  {
    const topErr=topErrorEl();
    if(topErr && !topErr.classList.contains('ec-l1')){  // L1 胶囊不展开
      const detailEl = topErr._detailEl;  // 获取关联的详情层
      if(detailEl){
        const r=topErr.getBoundingClientRect();
        const side=navigationSide(topErr,detailEl);
        const inY = my>=r.top-PAD_Y && my<=r.bottom+PAD_Y;
        const distFromEdge = side>0?mx-(r.right-4):r.left+4-mx;
        const inZoneIn  = inY && distFromEdge>=0 && distFromEdge<=EDGE_IN;
        const inZoneOut = inY && distFromEdge>=0 && distFromEdge<=EDGE_OUT;
        const detailShown = detailEl.classList.contains('show');

        // ── 报错卡预告光: 鼠标在报错卡上过中线往右移 → 右缘实时渐亮 ──
        const eeh = topErr.querySelector('.error-edgehint');
        if(eeh){
          navigationHintSide(eeh,side);
          const onCard = hitRect(mx,my,topErr,0,PAD_Y);  // ⚠ 只在鼠标真的在卡片上时才显示光效, 不包含触发区
          if(!detailShown && !tooFast && onCard){
            const mid = r.left + r.width/2;
            const tt = Math.min(1, Math.max(0, side*(mx - mid) / (r.right - mid)));
            if(inZoneIn){
              eeh.style.opacity='1'; eeh.style.width='44px';    // 峰值同任务卡(报错卡也300宽)
            }else if(tt > 0){
              const pp = Math.pow(tt, 1.3);
              eeh.style.opacity = String(0.15 + pp * 0.75);
              eeh.style.width = String(pp * 40) + 'px';
            }else{
              eeh.style.opacity='0'; eeh.style.width='0px';
            }
          }else{
            eeh.style.opacity='0'; eeh.style.width='0px';
          }
        }

        if(!detailShown){
          // 向右推进 → 显示详情层 + 播弹出光(光带+亮线)
          if(inZoneIn && dx*side>=DIR_MIN && !tooFast){
            detailEl.classList.add('show');
            window.__errDetail=detailEl;
            // 详情弹出 → 报错卡右缘播弹出光, 速度跟鼠标推进(同任务卡)
            const pvv=Math.max(0.15, Math.min(2.0, pushSpeed));
            const tt2=(pvv-0.15)/(2.0-0.15);
            const durE=0.9 - Math.pow(tt2, 1.6)*(0.9-0.40);
            ['.error-glow','.error-bright'].forEach(cls=>{
              const gl=topErr.querySelector(cls);
              if(gl){
                gl.style.animationDuration=durE+'s';
                gl.classList.remove('glow');
                void gl.offsetWidth;
                gl.classList.add('glow');
              }
            });
            if(eeh){ eeh.style.opacity='0'; eeh.style.width='0px'; }   // 预告光让位给弹出光
          }
        }else{
          // 详情层已显示, 鼠标移出 → 收起
          if(topErr.dataset.v7DirectConfirmation !== '' && !hitRect(mx,my,topErr,0,PAD_Y) && !hitRect(mx,my,detailEl,0,PAD_Y) && !navigationGapHit(mx,my,topErr,detailEl) && !inZoneOut){
            detailEl.classList.remove('show');
            if(window.__errDetail===detailEl) window.__errDetail=null;
          }
        }
      }
    }
  }
});

// ── 滚轮: 按【几何范围】判定归属, 不用 elementFromPoint ──
// 【坑】elementFromPoint 返回最顶层元素, 任务预览被别的层盖住时会误判成"不在任务区",
//   于是滚轮跑去切主卡。且原来的 else 是兜底 —— 鼠标在空白处也会切主卡。
// 正确做法: 用各区域的实际矩形判断归属; 都不命中就什么都不做。
function hitRect(mx,my,el,padX,padY){
  if(!el) return false;
  const r=el.getBoundingClientRect();
  if(r.width===0||r.height===0) return false;
  const px=padX||0, py=padY||0;
  return mx>=r.left-px && mx<=r.right+px && my>=r.top-py && my<=r.bottom+py;
}
function detailWheelScrollTarget(mx,my){
  const outer=detail.querySelector('.dc-scroll');
  if(!outer) return null;
  // 提示词/工作流详情的外层负责裁切，真正可滚动的是内部 .pd-body；
  // 设置、历史等详情则直接滚动 .dc-scroll。按鼠标位置选最深的可滚动层，
  // 避免把 scrollTop 写到 overflow:hidden 的外层而页面看起来不动。
  // .v7tw-params / .v7tw-list：工具工作面（原地展开的大卡）里能滚的两块
  const candidates=[outer,...outer.querySelectorAll('.pd-body,.qz-scroll,.pz-list,.v7tw-params,.v7tw-list')];
  for(let i=candidates.length-1;i>=0;i--){
    const el=candidates[i], style=getComputedStyle(el);
    if(!hitRect(mx,my,el) || !['auto','scroll'].includes(style.overflowY)) continue;
    if(el.scrollHeight>el.clientHeight+1) return el;
  }
  return outer;
}
window.addEventListener('wheel',e=>{
  if(e.target.closest?.('.v7-floating-bar'))return;
  // ⭐ 2026-10-15：公告卡正文长了会在卡里滚。还能往这个方向滚 → 交给原生滚动，不切报错卡；
  //   滚到头了才照旧切卡（跟详情层"滚到头才翻"一个手感）。
  const annBody=e.target.closest?.('.error-card.ec-rich .ec-rich-body');
  if(annBody&&annBody.scrollHeight>annBody.clientHeight+1){
    const canUp=annBody.scrollTop>0, canDown=annBody.scrollTop+annBody.clientHeight<annBody.scrollHeight-1;
    if((e.deltaY<0&&canUp)||(e.deltaY>0&&canDown))return;
  }
  // ⚠ 大图查看器打开时, 滚轮归它; 弹窗锁定时不响应(切卡/滚都锁)
  if(viewerOpen) return;
  if(document.getElementById('popupLock').classList.contains('on')) return;
  if(v7OverlayOpen()) return;   // 任意独立工作面打开 → 滚轮归工作面
  if(window.UISelect && UISelect.isOpen()) return;       // 下拉面板开着 → 滚轮归它
  // ⚠ 2026-10-06 晚：同 mousemove —— 只有【看得见】的内嵌工作区才拦滚轮；
  //   藏在隐藏详情层里的旧工作区不许把滚轮关掉。
  if(window.V7Workspaces?.hasVisibleEmbedded?.()??window.V7Workspaces?.hasEmbedded?.())return;
  if(isCollapsed) return;
  const mx=e.clientX,my=e.clientY;
  const freeMode=window.V7FreeMode?.isActive();
  if(window.V7FreeMode?.isTransitioning())return;
  // 触控板横向滚动使用 deltaX；普通鼠标仍走 deltaY。没有有效轴向时不切卡。
  const axisDelta=Math.abs(e.deltaX||0)>Math.abs(e.deltaY||0)?e.deltaX:e.deltaY;
  if(!axisDelta)return;
  const dir=axisDelta>0?1:-1;
  const freeCard=freeMode?(e.target.closest?.('#stack .block-card')||freeOwnerCard(mx,my,e.target)):null;

  // 【详情优先】鼠标在打开的详情卡上 → 详情内容滚动, 不切主卡/分区(三级内容滚轮浏览)
  if(detail.classList.contains('show') && hitRect(mx,my,detail) && (!window.V7FreeMode?.isActive()||e.target.closest('#detail'))){
    detailUsed=true;                      // ⚠ 在三级上滚轮 = 用过它
    const scroll=detailWheelScrollTarget(mx,my);
    if(scroll){
      // 详情内容由这里统一消费滚轮。全局 wheel 监听必须显式声明
      // passive:false，否则 Chromium 还会执行默认滚动，导致一次滚轮
      // 同时走“手动 scrollTop + 浏览器默认滚动”，实际位移翻倍。
      e.preventDefault();
      const delta = typeof pzNormalizeDelta === 'function'
        ? pzNormalizeDelta(e, scroll.clientHeight)
        : e.deltaY;
      scroll.scrollTop += delta;
    }
    return;
  }

  // 【预设二级】不在这儿处理 —— 它有自己的【非 passive】滚轮监听(见文件末尾 pzWheel)，
  // 那边会 stopPropagation，所以事件根本到不了这里。
  // ⚠ 预设二级仍需单独一套: 它要在自己的内容区内阻止默认滚动并累计翻页阈值，
  //   不能混入详情卡的像素滚动路径。

  // 【报错区】鼠标在报错堆上 → 切换当前报错卡(滚轮切换, 像任务堆)
  const topErr = topErrorEl();
  const overErr = hitRect(mx,my,topErr)&&(!window.V7FreeMode?.isActive()||e.target.closest('#errors'));
  const errCount = errorsEl.querySelectorAll('.error-card').length;

  // 任务区 = 当前任务卡 或 它展开的预览层
  const topTask=topTaskEl();
  const pvEl=topTask&&topTask.querySelector('.task-preview.show');
  const overTaskPreview = hitRect(mx,my,pvEl);
  const overTask = (hitRect(mx,my,topTask) || overTaskPreview)&&(!window.V7FreeMode?.isActive()||e.target.closest('#tasks'));
  const taskCount = tasksEl.querySelectorAll('.task:not(.leaving)').length;   // 动态数量

  // 主卡区 = 当前主卡 / 分区 / 详情
  const curCard=cards[cur];
  const overMain = (freeMode?!!freeCard:hitRect(mx,my,curCard))
                || hitRect(mx,my,zones.classList.contains('show')?zones:null)
                || hitRect(mx,my,detail.classList.contains('show')?detail:null);

  lastDir = dir;
  // 短窗口中报错堆会向上夹取，与任务卡几何重叠；任务卡在视觉上
  // 位于报错卡上方，滚轮也必须先交给可见的任务卡。
  if(overErr && errCount>0 && !overTask){
    ecur=(ecur+dir+errCount)%errCount;
    setErrors();
  }else if(overTask && taskCount<=1){
    // 只有一个任务时，任务主卡和预览区都没有可切换目标。
    // 直接吞掉滚轮，避免 setTasks() 重排 DOM，导致当前详情页被刷新/回到初始状态。
    return;
  }else if(overTask && taskCount>0){
    const wasOpen = !!(pvEl);            // 预览开着 → 跟随过渡, 不关闭
    // ⭐⭐⭐ 2026-10-09 修（用户实测：「从一个有大图到没大图的任务中互相切，
    //   大图会残留」）：
    //   原来这一段只调 followPreview()（它只管【任务卡片详情】，
    //   整个函数里一次都没碰过 V7Tween / 大图）⇒ boxTaskId 还指着旧任务，
    //   大图就留在屏幕上。
    //
    //   ⚠ 为什么"有图→有图"时看着正常：新任务也有成品图 → 下面那段
    //     （条开着、框却指着别的任务）会把框叫回来，于是"大图跟着切了"。
    //     而"有图→无图"时新任务没成品图、开不出新框 ⇒ 旧框【没人管】= 残留。
    //   ⚠ 所以这是"两条路对同一件事各管一半"的老毛病：详情跟着切了，大图没跟。
    const prevTaskId = topTaskEl() ? topTaskEl().dataset.task : null;
    tcur=(tcur+dir+taskCount)%taskCount; // 用动态数量, 不是旧 TN
    setTasks();
    // ① 把【属于旧任务】的大图收掉。⚠ 带归属判断 —— 用户快速划过几张卡时，
    //   框可能已经属于别人了，不能无差别关掉。
    //   ⚠ 必须先取 prevTaskId 再 setTasks()：setTasks 之后 topTaskEl() 已经是新的了。
    if(prevTaskId && window.V7Tween && typeof V7Tween.hideBoxIfTask==='function'){
      V7Tween.hideBoxIfTask(prevTaskId);
    }
    // ② 「看完大图保持展开」那个标记也要清 —— 不清的话它会让收起被抑制，
    //   残留照样在（见 pvKeepOpen 的注释）。
    pvKeepOpen=false;
    if(wasOpen) followPreview(dir);      // 预览内容跟着换(与主卡同一语言)
    else { clearPreview(); window.__pv=null; }
    // 任务卡切换后，详情面板跟着显示该任务自己的状态、进度和结果。
    if(typeof aiRefreshInPlace==='function')aiRefreshInPlace();
  }else if(!freeMode && buriedCardAt(mx,my)>=0){
    // ⭐⭐ 2026-10-01 用户定案：主卡的滚轮行为，【标准模式和自由模式必须一致】。
    //
    //   自由模式下，鼠标放在"卡片叠压露出的那条文字带"上可以直接滚，
    //   不受上方卡片内容的限制（走 freeCard → cycleAtCurrent）。
    //
    //   标准模式原来【没有这一支】，于是那条露出带是个死区：
    //     · 露出带在当前卡的矩形【之外】（实测：当前卡 y 60~460，露出带从 460 往下），
    //       所以上面那三条 capture 监听里的 hitRect(...) 全都不命中 → return；
    //     · 这条全局监听里 overMain 也算不上（它同样按当前卡矩形判）。
    //   → 结果就是"鼠标放在叠压区滚，什么都不发生"。
    //     而且上方卡片那些"先滚内层 / 攒光够数才切"的先期判断，
    //     本来就不该管这块区域（那里根本不是这张卡的内容）。
    //
    //   补齐之后：落在露出带里 = 一步直接切卡，不做任何先期判断。
    //   ⚠ 冻结期照样尊重（cardSwitchFrozenUntil）—— 否则一记猛滚会一路翻穿整摞卡。
    //   ⚠ buriedCardAt() 在自由模式和折叠态自己就返回 -1，所以这里不用再判它们。
    if(performance.now() < cardSwitchFrozenUntil) return;
    e.preventDefault();
    switchMainCard(dir,'叠压带直通');
  }else if(overMain){
    // ⚠ 刚靠"攒光"切过卡 → 冻结一下。
    //   切走之后鼠标就落在普通二级上了，那儿是"滚一下切一张"，
    //   不冻的话一记猛滚的余势会直接把你从预设翻到生成(用户实测提的)。
    if(performance.now() < cardSwitchFrozenUntil) return;
    // ⚠⚠ 鼠标在预设二级上 → 那块有自己的"攒光"规则(见文件末尾的专用监听)，
    //   全局这条"滚一下切一张"【绝不能插手】。
    //   为什么用几何判断而不是靠事件冒泡兜底: 专用监听挂在 #presetZone 上，
    //   而 .zones.show 自己是 pointer-events:auto —— 容器本身也能当事件目标。
    //   只要事件因为任何原因没落在 #presetZone 身上(容器成了 target /
    //   命中了别的层 / .show 状态不同步)，就会漏到这里来一下切一张，
    //   表现就是"列表还没滚到底就翻页了"(2026-09-11 用户实测)。几何判断堵死这个洞。
    if(!freeCard && isPresetCard() && hitRect(mx,my, presetZoneKind==='prompt' ? promptZoneEl : presetZoneEl)) return;
    if(freeMode){e.preventDefault();window.V7FreeMode.cycleAtCurrent(dir,freeCard);}
    else switchMainCard(dir,'全局滚轮');
  }
  // 都不命中(鼠标在空白处) → 什么都不做
},{passive:false});

// ═══ 点被压住的卡的标题 → 连续翻到它（2026-09-14 用户要求）═══
//
// 叠压时下面那几张卡只露出最下面 34px 的标题带（docs/14 §5.5）。用户想点那条标题直接过去。
//
// ⚠ 为什么不能在卡上挂 click：
//   被压住的卡整卡 pointer-events:none（setStack 里按深度设的），
//   子元素还有 `#stack .block-card:not(.is-current) *{pointer-events:none !important}` 护栏 ——
//   两道都是为了"露出来的按钮不能被点到"，不能为了这个功能拆掉。
//   所以点击落在哪张卡上【自己算】：监听挂在 window 上（跟滚轮一个路数），
//   用每张卡的矩形做几何判断。露出带 = 卡的最下面 STEP 像素，且被上一张盖住的部分不算。
//
// ⭐ "连续翻动"而不是"一步跳到"：走 switchMainCard 一张一张翻，每张停 130ms。
//   这样中间那几张卡会依次滑过去，跟滚轮翻的是同一套动作语言（铁律：三层动画统一"整体滚动"）。
//   翻的方向按"哪边近"选：5 张卡里从 0 翻到 4，往上翻一步就到，不绕远。
//
// ⚠ 翻动期间再点/再滚都不接（jumpBusy），免得两条翻动叠在一起把 cur 翻乱。
let jumpBusy=false;
const JUMP_STEP_MS=130;
function jumpToCard(target, why){
  target=Number(target);
  const visible=layoutVisibleIndices();
  if(!Number.isFinite(target)||!visible.includes(target)||target===cur||jumpBusy) return;
  // 最短路：环形距离，正向(dir=1)走几步、反向走几步，取小的
  const from=visible.indexOf(cur),to=visible.indexOf(target),count=visible.length;
  const fwd=(to-from+count)%count, back=(from-to+count)%count;
  const dir=fwd<=back?1:-1;
  let steps=Math.min(fwd,back);
  jumpBusy=true;
  const tick=()=>{
    if(steps<=0||cur===target){ jumpBusy=false; return; }
    switchMainCard(dir, why||'点标题跳卡');
    steps--;
    if(steps>0&&cur!==target) setTimeout(tick, JUMP_STEP_MS);
    else jumpBusy=false;
  };
  tick();
}
// 点在哪张被压住的卡的露出带上。返回卡序号，没命中返回 -1。
// ⚠ 只认【露出带】：卡自身坐标 y ∈ [卡高-STEP, 卡高]，再被上一层盖掉的部分不算。
//   直接用 getBoundingClientRect —— 它已经含了 transform 位移和缩放，不用自己算 d*STEP。
function buriedCardAt(x, y){
  if(window.V7FreeMode?.isActive())return -1;
  if(isCollapsed) return -1;
  // 从浅到深找：浅的盖在深的上面，先命中的就是它
  const visible=layoutVisibleIndices(),currentPos=visible.indexOf(cur),order=[];
  for(let d=1; d<=stackVisibleDepth(visible.length); d++) order.push(visible[(currentPos+d+visible.length)%visible.length]);
  let coverBottom=null;                   // 上一张（更浅的）卡的下沿，它以上的部分被盖住
  const top=cards[cur]&&cards[cur].getBoundingClientRect();
  if(top) coverBottom=top.bottom;
  for(const i of order){
    const c=cards[i]; if(!c) continue;
    const r=c.getBoundingClientRect();
    if(!r.width||!r.height) continue;
    const bandTop=Math.max(r.bottom-STEP*UI_SCALE, coverBottom==null?r.top:coverBottom);
    if(x>=r.left&&x<=r.right&&y>=bandTop&&y<=r.bottom) return i;
    coverBottom=r.bottom;
  }
  return -1;
}
window.addEventListener('click', e=>{
  if(e.target.closest?.('.v7-floating-bar'))return;
  if(e.button!==0||jumpBusy||isCollapsed) return;
  if(v7OverlayOpen()) return;
  if(window.V7Workspaces?.hasEmbedded?.()){
    // A workspace can overlap the exposed bands of the main card pile.
    // Its controls own the click even when the same coordinates hit a buried
    // card. Use the dispatch path because a control may rebuild itself.
    if(e.composedPath().some(node=>node?.matches?.('.detail-card,.zones,.tasks,#errors,.v7-primary-nav,.v7-workspace')))return;
    const destination=buriedCardAt(e.clientX,e.clientY);
    if(destination>=0){e.preventDefault();e.stopImmediatePropagation();navigateCard(cards[destination].dataset.card,0).catch(error=>ERR.report('LAYOUT_FAILED',{message:String(error.message||error)}));}
    return;
  }
  if(document.getElementById('popupLock').classList.contains('on')) return;
  if(viewerOpen) return;
  if(window.UISelect&&UISelect.isOpen()) return;
  // 点在当前卡/二级/三级/任务/报错上的都不管 —— 那些有自己的点击逻辑
  const t=e.target;
  if(t.closest&&(t.closest('.block-card.is-current')||t.closest('.zones')||t.closest('.detail-card')||t.closest('.tasks')||t.closest('#errors')||t.closest('.popup-stack'))) return;
  const i=buriedCardAt(e.clientX, e.clientY);
  if(i<0) return;
  e.preventDefault(); e.stopPropagation();
  jumpToCard(i,'点标题「'+((cards[i]&&cards[i].dataset.bglabel)||i)+'」');
}, true);   // 捕获阶段：抢在 document 那条"点空白就 closeAll" 之前

// 切主卡。抽出来是因为预设二级有自己的滚轮监听(见下面)，两边必须走同一套。
// why = 谁切的。⚠ 只在预设列表可见时打日志 —— "还没滚到底就翻页"这类问题，
//   光看现象分不清是【攒光达标】还是【全局滚轮漏过来】干的，一行日志就分清了。
function switchMainCard(dir, why){
  if(window.V7FreeMode?.isActive()){window.V7FreeMode.cycleAtCurrent(dir);return;}
  const _pl = presetZoneEl && presetZoneEl.querySelector('.pz-list');
  if(_pl && _pl.clientHeight){
    const maxTop = Math.max(0, _pl.scrollHeight - _pl.clientHeight);
    const atEnd = dir>0 ? (_pl.scrollTop >= maxTop-1) : (_pl.scrollTop <= 0);
    const msg='[预设] 切主卡 ← '+(why||'?')+' | 方向'+(dir>0?'下':'上')
      +' 列表位置 '+Math.round(_pl.scrollTop)+'/'+Math.round(maxTop)
      +(atEnd?' 已到头':' ⚠ 没到头');
    console.log(msg);
    if(window.__TAURI__ && window.__TAURI__.core){
      window.__TAURI__.core.invoke('debug_log',{message:msg}).catch(()=>{});
    }
  }
  lastDir = dir;
  const visible=layoutVisibleIndices();
  if(visible.length){const pos=Math.max(0,visible.indexOf(cur));cur=visible[(pos+(dir>0?1:-1)+visible.length)%visible.length];}
  setStack();
  updateZoneBg(cur);                       // 区块切换 → zone 背景跟着换
  updateDetailBg();                        // ⚠ 三级也要跟着换! 漏了这句 → A/B 主卡的三级同色
  // 分区/详情开着 → 跟随过渡(带动画); 都没开 → 静默填内容, 保证下次弹出时是对的
  if(zoneOpen || detail.classList.contains('show')) syncZonesToCard(dir);
  else fillZonesNow();                     // ⚠ 兜底: 不开着也要把内容对上, 防旧内容残留
}

// ── 任务预览跟随切换: 与主卡二级同一套上下错落语言 ──
// 【防闪烁】不做"旧的关+新的开"(两个预览会同时 show, 且位置随任务卡重排而突变),
// 改为【原地换内容】: show 状态全程不变, 只把里面的图翻成新任务的。
function followPreview(dir){
  const newTask = topTaskEl();
  if(!newTask) return;
  const newPv = newTask.querySelector('.task-preview');
  const oldPv = document.querySelector('.task-preview.show');
  if(!newPv) return;

  const out = dir>0 ? -SHIFT_Z : SHIFT_Z;
  const inn = dir>0 ?  SHIFT_Z : -SHIFT_Z;

  // 新预览先无动画就位(不触发弹出动画), 旧的静默下线 —— 全程不闪
  if(oldPv && oldPv!==newPv){
    newPv.style.transition='none';
    newPv.classList.add('show');
    oldPv.classList.remove('show');
    requestAnimationFrame(()=>{ newPv.style.transition=''; });
  }else if(!oldPv){
    newPv.classList.add('show');
  }
  window.__pv=newPv;

  // 内容错落翻转(与主卡二级同一语言)
  // 任务卡自己的预览 DOM 已在数据更新时维护，滚轮切任务时不再整块重建。
  const strip=newPv.querySelector('.pv-strip');
  if(strip){
    strip.classList.add('pv-animating');
    clearTimeout(newPv._animTimer);
    newPv._animTimer=setTimeout(()=>strip.classList.remove('pv-animating'),260);
  }
  const cells=newPv.querySelectorAll('.pv-cell');
  cells.forEach((c,i)=>{
    c.style.transition='none';
    c.style.opacity='0'; c.style.transform='translateY('+inn+'px)';
  });
  requestAnimationFrame(()=>{
    cells.forEach((c,i)=>{
      c.style.transition='opacity .15s var(--ease-soft), transform .15s var(--ease-out)';
      setTimeout(()=>{ c.style.opacity='1'; c.style.transform='translateY(0)'; }, i*18);
    });
  });

  // ⭐⭐ 2026-10-04 用户实测报的 bug（docs/137 §9.2）：切任务卡时大预览框不更新。
  //
  //   真因：大框的"归属"只在【预览条第一次弹出】那一下设定（见上面 6919 那段的
  //     `if(!pvOpen)` 分支里的 hoverTaskCard）。**而切任务卡走的是本函数**，
  //     这里原来一次都没碰过 V7Tween（grep 0 处）。
  //   ⇒ 换了任务卡，大框还指着旧任务 → 缩略图滚不动、框里是旧图、
  //     要等鼠标离开整个连通区才收掉。用户看到的就是"不消失或者更新不及时"。
  //
  //   ⚠ 用 retarget 而不是 hoverTaskCard：
  //     hoverTaskCard 会 yieldMainCard() 去【收二级/三级面板】——
  //     滚一下任务就踹掉用户正在看的二级卡，那是新 bug。
  //     retarget 只改"框指向谁"，框没开就什么都不做。
  const curTask2 = newTask ? taskById(newTask.dataset.task) : null;
  if(curTask2 && window.V7Tween && typeof V7Tween.retarget==='function'){
    window.V7Tween.retarget(newTask, curTask2);
  }
}

// 分区/详情内容跟随当前主卡切换(交叉淡入, 与叠压动画同步)
const LINK_ZONE_SET=[['download','抓取测试','PS → 软件'],['upload','传回测试','软件 → PS'],['sparkles','生成测试','抓取 → 生成 → PS'],['sliders','控制 PS 测试','V6 原子操作']];
// ZONE_SETS 已上移到 zoneSlugOf 之前(2026-09-10) —— 理由见那里的注释。
// 验证期的分区定义保留在运行时层，供正式功能接入时复用；它们不再占用当前主卡。
const LOG_ZONE_SET=[['books','全部日志','所有方向'],['link','桥接日志','UI ↔ UXP'],['broom','清空日志','只清本地记录'],['arrowUpRight','导出日志','复制文本']];
// 2026-10-18：AI_ZONE_SET 跟 fillAiDetail 一起删了（只有它用）。
// ── 二级/三级换内容: 【上下方向】与主卡叠压同一语言, 方向跟滚轮绑定 ──
// 主卡是上下切换的, 所以它的下级也必须上下动 —— 左右动会跟主卡脱节。
// dir: 1=向下滚(主卡向上走) → 内容向上淡出、从下方推入; -1 反之。
const STAGGER=26;        // 错落间隔, 与叠压节奏同源
const SHIFT_Z=12;        // 二级位移量
let lastDir=1;

function linkImageSrc(data){
  if(!data) return '';
  if(typeof data==='string') return data.indexOf('data:')===0 ? data : 'data:image/png;base64,'+data;
  const b64=data.imageBase64||data.base64||'';
  return b64 ? (b64.indexOf('data:')===0 ? b64 : 'data:'+(data.mime||'image/png')+';base64,'+b64) : '';
}
function makeLinkPlaceholder(){
  const canvas=document.createElement('canvas'); canvas.width=256; canvas.height=256;
  const ctx=canvas.getContext('2d');
  const g=ctx.createLinearGradient(0,0,256,256); const 主题=getComputedStyle(document.documentElement); g.addColorStop(0, 主题.getPropertyValue('--accent').trim()||'#5aa9ff'); g.addColorStop(1, 'hsl('+((主题.getPropertyValue('--glow-detail').trim())||'275 100% 76%')+')');
  ctx.fillStyle=g; ctx.fillRect(0,0,256,256);
  ctx.fillStyle='rgba(255,255,255,.88)'; ctx.font='600 24px sans-serif'; ctx.textAlign='center'; ctx.fillText('V8 TEST',128,134);
  const src=canvas.toDataURL('image/png');
  return {imageBase64:src.split(',')[1],mime:'image/png',width:256,height:256};
}
function linkFormValue(id){ const el=document.getElementById(id); return el ? String(el.value||'').trim() : String(linkRuntime.form[id]||''); }
function linkParamsForAction(action){
  const f=linkRuntime.form;
  const ids=String(f.groupIds||'').split(',').map(v=>Number(v.trim())).filter(Number.isFinite);
  if(action==='ps.doc.select'||action==='activateDocument') return {docId:Number(f.docId)};
  if(action==='ps.doc.export') return {path:f.exportPath};
  if(action==='ps.selection.restore'||action==='restoreSelectionFromHistory') return {docId:Number(f.docId)||undefined,selection:linkRuntime.capture&&linkRuntime.capture.selection};
  if(action==='ps.selection.capture'||action==='ps.selection.captureRef'||action==='ps.selection.recaptureRef'||action==='captureRefImage'||action==='recaptureRefImage') return {allowFullCanvas:!!linkRuntime.autoFullCanvas,maxResolution:captureMaxEdge()};
  if(action==='captureForChat'||action==='ps.selection.captureForChat') return {allowFullCanvas:!!linkRuntime.autoFullCanvas,maxResolution:1024};
  if(action==='ps.selection.ops') return {operation:'clear'};
  if(action==='ps.marquee.sync'||action==='syncMarqueeAspect') return {aspect:f.aspect||'1:1'};
  if(action==='ps.layer.select'||action==='ps.layer.delete'||action==='ps.layer.gotoMask'||action==='gotoLayerMask') return {layerId:Number(f.layerId)||undefined,docId:Number(f.docId)||undefined};
  if(action==='ps.layer.create') return {name:f.layerName||'链路验证图层'};
  if(action==='ps.layer.rename') return {layerId:Number(f.layerId)||undefined,name:f.layerName||'链路验证结果'};
  if(action==='ps.layer.visibility') return {layerId:Number(f.layerId)||undefined,visible:!!f.visible};
  if(action==='ps.layer.opacity') return {layerId:Number(f.layerId)||undefined,opacity:Number(f.opacity)||100};
  if(action==='ps.layer.solo'||action==='soloLayer') return {layerId:Number(f.layerId)||undefined};
  if(action==='conversationLayerVisibility') return {mode:'solo',docId:Number(f.docId)||undefined,ownedLayerIds:ids,soloLayerId:Number(f.layerId)||undefined};
  if(action==='ps.layer.place') return {imageBase64:(linkRuntime.generated||linkRuntime.capture||makeLinkPlaceholder()).imageBase64,targetDocId:Number(f.docId)||undefined,targetSelection:linkRuntime.capture&&linkRuntime.capture.selection,layerType:'smartObject'};
  if(action==='ps.layer.placeBatch'){
    const image=linkRuntime.generated||linkRuntime.capture||makeLinkPlaceholder();
    return {targetDocId:Number(f.docId)||undefined,items:[{imageBase64:image.imageBase64,selection:linkRuntime.capture&&linkRuntime.capture.selection,layerType:'smartObject'}]};
  }
  if(action==='ps.group.create') return {layerIds:ids,groupName:f.groupName||'链路验证组'};
  if(action==='ps.mask.feather') return {docId:Number(f.docId)||undefined,layerId:Number(f.layerId)||undefined,selection:linkRuntime.capture&&linkRuntime.capture.selection};
  if(action==='ps.mask.magentaFix') return {groupName:f.groupName||'链路验证组'};
  if(action==='ps.channel.visibility') return {channelId:Number(f.channelId)||undefined,visible:!!f.visible};
  return {};
}
function runLinkCapture(after){
  return linkQueue('ps.selection.capture',{allowFullCanvas:!!linkRuntime.autoFullCanvas,maxResolution:captureMaxEdge()},{testKey:'capture',after});
}

// ═══ 抠像链路（2026-09-14）════════════════════════════════════
//   抓 PS 选区/画布 → 送引擎抠图 → 贴回一个带透明通道的图层
//
// ⚠ 和生成链路的关键不同：抠像【没有本机兜底】。
//   引擎没起、模型没装 —— 一律弹卡说清楚，不能静默什么都不发生（docs/40 规矩5）。
// ⚠ 每一步失败都要说【是哪一步】。"抠像失败"是废话，
//   "没找到选区"和"引擎没响应"是完全不同的下一步动作（铁律 15）。
let mattingBusy = false;

// 抠像的抓图上限。⚠ 故意【不】读设置里那个"抓取分辨率"——
//   那一项写的是"发给 AI 的图"，默认 2048。抠像是给原图加一层透明，
//   缩了就是把用户的原图降质，贴回去还要拉大回选区尺寸（用户报的"分辨率极低"）。
//   0 / 没填 = 原始尺寸不缩。
// ⚠ 不缩的时候必须给一个【很大的数】而不是 0：桥那边是
//   `if (p.maxResolution) settings.maxResolution = ...`，传 0 会让它沿用上一次的值
//   （settings.maxResolution 是个粘住的全局）——那正好又缩回 2048。
const MATTING_NO_LIMIT = 999999;
function mattingMaxEdge(params){
  const v = Number(params && params.res) || 0;
  return v > 0 ? v : MATTING_NO_LIMIT;
}

// 把选区夹进画布范围。⚠ 读不到文档尺寸就原样返回 —— 宁可不夹，也不要拿 0 去夹成空。
function mattingClampSelection(sel, docW, docH){
  if(!sel) return null;
  const dw = Number(docW)||0, dh = Number(docH)||0;
  if(dw<=0 || dh<=0) return sel;
  const left   = Math.max(0,  Math.min(dw, Math.round(Number(sel.left)||0)));
  const top    = Math.max(0,  Math.min(dh, Math.round(Number(sel.top)||0)));
  const right  = Math.max(left+1, Math.min(dw, Math.round(Number(sel.right)|| (left+(Number(sel.width)||0)))));
  const bottom = Math.max(top+1,  Math.min(dh, Math.round(Number(sel.bottom)||(top +(Number(sel.height)||0)))));
  return {left, top, right, bottom, width:right-left, height:bottom-top};
}

// ═══ 抠像的唯一入口（2026-09-14 下半场重做）═════════════════
//
//  ⭐ 和生成一样：先建任务卡，再干活。docs/20 的规矩——
//    "任务卡是用户看到状态的唯一入口"。原来这条链路只往日志里写几行，
//    用户点完屏幕上什么都不变（他报的"抠像没有进入到任务栏"）。
//
//  ⚠ 失败一律走 updateGenerationTask(status:'failed')，
//    报错卡由那个出口统一弹 —— 别在这里自己再 ERR.report 一遍，会弹两张。
// ⭐ 2026-10-15（用户要求「每次使用的时候按需要把这个东西调度起来，然后冷启动」）：
//   抠像 / 人体解析 / 指哪抠哪 点下去时引擎没开着 ⇒ 自己拉起来、等它就绪再往下走，
//   不再报"去外挂能力卡点「启动」"。拉不起来才交给后面的 unusableReason 报错（带原因）。
//   ⚠ 同时点了好几个工具只拉一次（共用同一个启动过程）。
let toolEngineStarting=null;
async function toolEngineReady(id,label){
  // ⭐ 2026-10-18 云端外挂（docs/237）：开着云端就先问云端 —— 能用就不碰本机引擎（不带模型的包本来也没有）；
  //   云端不行时 cloud-tools.js 已经【如实提示过】并决定好退回本机（route='local'，下面照旧拉起本机）还是没路可退（'none'）。
  if(window.V7CloudTools&&V7CloudTools.enabled()){
    const say=sub=>{if(id==null)return;try{updateGenerationTask(id,sub);}catch(_){}};
    say({sub:'正在连云端…',pct:4});
    const r=await V7CloudTools.ensureReady();
    if(r.route==='cloud'){ await MATTINGENGINE.probe(true); return; }
    if(r.route==='none'){ say({sub:(r.why&&r.why.text)||'云端连不上'}); return; }
    say({sub:'云端连不上，改用本机引擎…',pct:4});
  }
  await MATTINGENGINE.probe(true);
  if(MATTINGENGINE.snapshot().available) return;
  if(!(window.uiwin&&uiwin.engine&&uiwin.engine.start)) return;
  const say=sub=>{if(id==null)return;try{updateGenerationTask(id,sub);}catch(_){}};
  say({sub:'正在启动'+label+'引擎（冷启动，第一次要等十几秒）',pct:4});
  aiAddLog('['+label+'] 引擎没开着，自动启动…','info');
  if(!toolEngineStarting){
    toolEngineStarting=engineStartAndWait(m=>say({sub:label+'引擎 · '+m}),'matting')
      .finally(()=>{toolEngineStarting=null;});
  }
  const r=await toolEngineStarting;
  if(r&&!r.ok) aiAddLog('['+label+'] 自动启动没成功：'+r.error,'warn');
  else aiAddLog('['+label+'] 引擎已启动','success');
  await MATTINGENGINE.probe(true);
}
// 给自包含的模块用（改动强度 / 助手语义识别）：没有任务卡可写，只拉引擎
window.V7EngineEnsure=label=>toolEngineReady(null,label||'外挂');
// ⭐ 2026-10-15（用户定：空闲 10 分钟就关闭）：由【引擎自己】看门退出（multi_engine_server.py 的 _idle_watchdog）。
//   ⚠⚠ 界面这边【不许】定时去调 uiwin.engine.stop：两个壳的停止入口都故意弹确认框，
//     第一版就是这么写的 ⇒ 每分钟弹一次「停止抠像引擎」框（用户截图报的），点取消还会接着弹。
//   退出后下次用到，上面的 toolEngineReady 会自动拉起来。
async function startMatting(preset, params){
  if(!window.MATTINGENGINE){
    ERR.report('MATTING_START_FAILED',{message:'matting-engine.js 没加载'});
    return false;
  }
  if(mattingBusy){
    // ⚠ 引擎一次只加载一个模型，两个请求打进去会互相等/爆显存。这里就闸住。
    ERR.report('MATTING_BUSY',{message:'上一次还没跑完，等它完事再按'});
    return false;
  }
  const PU = window.PRESETUI;
  const p = preset || (PU && PU.getToolPreset && PU.getToolPreset()) || null;
  const vals = params || (PU && PU.getToolParams && PU.getToolParams()) || {};
  const label = String((p && p.title) || '抠像');

  const runId = aiNewTaskId('mt');
  const task = addTask(makeMattingTask({taskId:runId, label}));
  const id = task.id;
  const t0 = Date.now();
  mattingBusy = true;

  // ⚠ 第四个参数 true = "上游已经弹过更详细的卡了"，这里只改任务状态别再弹一张。
  // ⚠⚠ 必须把【已经抠出来的那张】保住：updateGenerationTask 在转 failed 时，
  //   如果调用方没给 shots，会把所有没完成的格子刷成错误态、连 imgId 一起清掉。
  //   贴回那一步失败时图其实已经在手上了，清掉等于让用户白跑一趟。
  const fail = (message, stage, code, alreadyReported)=>{
    const live = taskById(id);
    const keep = live && Array.isArray(live.shots) && live.shots.some(s=>s&&s.done&&s.imgId)
      ? {shots:live.shots} : {};
    updateGenerationTask(id, Object.assign({status:'failed', stage, errorCode:code||'MATTING_RUN_FAILED',
      error:String(message||'抠像失败'), _errorReported:!!alreadyReported}, keep));
    aiAddLog('[抠像] 失败（'+(stage||'?')+'）：'+String(message||''),'warn');
  };

  try{
    // ── ① 引擎能不能用。先问，别让用户白等一次抓图 ──
    updateGenerationTask(id,{status:'running', sub:'检查抠像引擎', pct:5});
    await toolEngineReady(id,'抠像');
    const why = MATTINGENGINE.unusableReason();
    if(why){ fail(why,'engine','MATTING_UNUSABLE'); return true; }
    // 用户在面板里挑的档位 ∩ 引擎实际能给的（两边取严，见 matting-engine 的 pickTier）
    const tierNotes = [];
    const useTier = MATTINGENGINE.pickTier(vals.tier, tierNotes);
    updateTask(id,{mattingTierName:MATTINGENGINE.tierName(useTier)});
    // ⚠ 降档了必须说（docs/40 规矩4）：用户选了高清档却跑了标准档，
    //   不说的话他会一直以为"这就是高清档的效果"。
    tierNotes.forEach(n=>aiAddLog('[抠像] '+n,'warn'));

    // ── ② 抓图（原始尺寸，不缩）──
    const maxEdge = mattingMaxEdge(vals);
    updateGenerationTask(id,{sub:'从 Photoshop 抓选区', pct:12});
    aiAddLog('[抠像] 开始 · 正在从 Photoshop 抓图'+(maxEdge===MATTING_NO_LIMIT?'（原始尺寸）':('（上限 '+maxEdge+'）')),'info');
    const cap = await new Promise((res,rej)=>{
      linkQueue('ps.selection.capture',
        {allowFullCanvas:!!settingsRuntime.autoFullCanvas, maxResolution:maxEdge},
        { after:(d)=>res(d),
          // ⚠ 把桥给的诊断现场原样带出来 —— 它知道"文档是16位"这种真正有用的信息
          afterError:(r)=>rej(new Error(linkResultMessage(r))) }
      ).catch(e=>rej(e));
    });
    const b64 = cap && (cap.imageBase64 || cap.inputImageBase64);
    if(!b64){ fail('抓回来的数据里没有图片','capture','PS_CAPTURE_FAILED'); return true; }

    const capW = Number(cap.width)||0, capH = Number(cap.height)||0;
    updateTask(id,{
      sourceDocId:cap.docId, sourceDocName:cap.docName||'',
      sourceSelection:cap.selection||null,
      mattingSize:capW+'×'+capH
    });
    // 任务卡的背景 = 这次抠的那张图。⚠ 必须过图片管家，不能直接把 base64 当背景。
    registerTaskSourceImage(id, b64, cap.mime||'image/png');
    updateGenerationTask(id,{sub:'已抓 '+capW+'×'+capH+' · 正在抠', pct:30});
    aiAddLog('[抠像] 已抓取 '+capW+'×'+capH+' · 正在抠','info');
    // ⚠ 超大图只提醒不拦：拦了用户就没法用原始尺寸，而他明确要的就是原始尺寸。
    if(Math.max(capW,capH) > 6000){
      aiAddLog('[抠像] ⚠ 这张有 '+capW+'×'+capH+'，一来一回的数据量很大，慢是正常的。'
             + '嫌慢就在抠像面板里把「抓图分辨率」调低一档','warn');
    }

    // ── ③ 送引擎 ──
    // ⚠ base64 转二进制再发：引擎那边按二进制读，
    //   直接发 base64 会多 33% 体积还要多解一次码（docs/21 的账）。
    const bin = base64ToBytes(String(b64).replace(/^data:[^,]+,/,''));
    const tier = vals && vals.tier;
    // ⭐ 盖印+蒙版那条路只要 alpha 一个通道（RGB 全黑），实测比整张 RGBA 省 8 倍
    //   （2000×1333 的图：1.77MB → 222KB）。老的"贴透明图层"那条路还是要 RGBA。
    const useMask = String(vals.applyMode || 'mask') === 'mask';
    const qp = [];
    if(tier && tier !== 'auto') qp.push('model=' + encodeURIComponent(MATTINGENGINE.keyForTier(Number(tier), 'matting') || ''));
    if(useMask) qp.push('out=alpha');
    const qs = qp.length ? ('?' + qp.join('&')) : '';
    let resp;
    try{
      resp = await fetch(MATTINGENGINE.base + '/matting' + qs, {
        method:'POST',
        headers:{ 'Content-Type':'image/png',
                  'X-Matting-Params': encodeURIComponent(JSON.stringify(vals||{})) },
        body: bin
      });
    }catch(e){
      fail('引擎没应答：'+String(e&&e.message||e),'matting','MATTING_RUN_FAILED'); return true;
    }
    if(!resp.ok){
      let msg = 'HTTP ' + resp.status, code = 'MATTING_RUN_FAILED';
      try{ const j = await resp.json(); if(j && j.error) msg = j.error; if(j && j.code) code = j.code; }catch(_){}
      fail(msg,'matting',code); return true;
    }
    const buf = await resp.arrayBuffer();
    let info = null;
    try{ info = JSON.parse(decodeURIComponent(resp.headers.get('X-Matting-Info')||'')); }catch(_){}

    // ⚠ 用户开了某项但这台机器做不了 → 必须说（docs/40 规矩4）
    if(info && info.skipped && info.skipped.length){
      aiAddLog('[抠像] ⚠ 这几项没做成（缺 opencv）：'+info.skipped.join('、'),'warn');
    }

    // ── ④ 算贴回的位置 ──
    //
    // ⚠⚠ 这一段是 2026-09-14 那次"回图比例错误"的正解，动之前先读完：
    //
    //   贴回的实现（ps-io.js 的 _placeCoreInModal）是：量一下贴进去那个图层多大，
    //   然后【横竖分别拉伸】到目标框那么大。对生成的图没问题——它不透明，
    //   图层大小就是整张图。
    //   但抠出来的图是【透明】的，Photoshop 报的图层大小是"只框住主体那一块"，
    //   不是整张图。于是"主体那一小块"被硬拉成"整个选区那么大"
    //   —— 比例扭了、位置错了、还被放大好几倍（用户报的那两条症状）。
    //
    //   解法：引擎把图【裁到主体那一块】再回来，同时告诉我们这块在原图里的位置
    //   （info.bbox）。裁完之后"图层大小 == 整张图"重新成立，
    //   原来那套拉伸逻辑就又对了，只要把目标框也换成对应的那一小块。
    //   ⭐ 这个改法不依赖"Photoshop 到底怎么量图层大小"——两种量法结果都对。
    // ⚠ 选区可能框到画布外面去（框选时拖出了边）。Photoshop 抓像素时会把范围
    //   裁回画布内，但报上来的 selection 还是没裁的那个 —— 两者对不上，
    //   拿它换算位置就会整块偏。先按文档尺寸夹一刀（正常选区夹了等于没夹）。
    const sel = mattingClampSelection(cap.selection, cap.docWidth, cap.docHeight);
    let target = sel;
    const bb = info && Array.isArray(info.bbox) && info.bbox.length===4 ? info.bbox : null;
    const iw = (info && info.size && Number(info.size[0])) || capW;
    const ih = (info && info.size && Number(info.size[1])) || capH;
    // ⚠ 夹完还对不上就是还有别的没想到的情况 —— 明着说出来，别静默算一个错位置。
    //   （铁律 17：宁可坏得看得见，也不要安静地不对）
    if(sel && iw>0 && ih>0 && sel.width>0 && sel.height>0){
      const r1 = sel.width/sel.height, r2 = iw/ih;
      if(Math.abs(r1-r2) > 0.02*Math.max(r1,r2)){
        aiAddLog('[抠像] ⚠ 选区('+sel.width+'×'+sel.height+')和抓回来的图('+iw+'×'+ih+')比例对不上，'
               + '贴回的位置可能有偏差。把这句连同选区大小报给开发','warn');
      }
    }
    // ⚠⚠ 上面这整套 bbox 换算【只有"贴透明图层"那条老路才需要】。
    //   走"盖印 + 蒙版"时根本没有"贴到哪、多大"的问题：
    //   alpha 是整张（没裁），目标就是选区本身，蒙版直接盖在盖印层上。
    //   这正是用户那句「直接盖印当前画面然后生成一个蒙版」最值钱的地方 ——
    //   它把坑55 那一整套补丁连根拔掉了。
    if(!useMask && sel && bb && iw>0 && ih>0){
      // 抓图可能被缩过（用户把分辨率调低了），所以是"图片像素 → 文档像素"的换算，
      // 不是直接加 —— 两边尺寸不一样时直接加会整块错位。
      const kx = (Number(sel.width)||iw) / iw;
      const ky = (Number(sel.height)||ih) / ih;
      const left   = Math.round(Number(sel.left) + bb[0]*kx);
      const top    = Math.round(Number(sel.top)  + bb[1]*ky);
      const right  = Math.round(Number(sel.left) + bb[2]*kx);
      const bottom = Math.round(Number(sel.top)  + bb[3]*ky);
      target = { left, top, right, bottom,
                 width: Math.max(1, right-left), height: Math.max(1, bottom-top) };
    }

    // ── ⑤ 结果先进任务卡，再贴回 ──
    // ⚠ 顺序是有讲究的：先登记缩略图，万一贴回失败（比如文档被关了），
    //   用户至少还能在任务卡里看到抠出来的东西，不是白跑一趟。
    const outBytes = new Uint8Array(buf);
    const outB64 = 'data:image/png;base64,' + bytesToBase64(outBytes);
    let outImgId = '';
    try{
      if(window.IMG) outImgId = await window.IMG.putFromBase64(outB64, 'image/png');
    }catch(e){ aiAddLog('[抠像] 缩略图登记失败（不影响贴回）：'+String(e&&e.message||e),'warn'); }
    updateGenerationTask(id,{sub: useMask ? '抠好了 · 正在盖印并加蒙版' : '抠好了 · 正在贴回 Photoshop',
      pct:80, shots:[{done:true, imgId:outImgId}]});

    await new Promise((res,rej)=>{
      const done = { after:()=>res(), afterError:(r)=>rej(new Error(linkResultMessage(r))) };
      if(useMask){
        // ⭐ 盖印当前画面 + 把 alpha 做成图层蒙版（用户 2026-09-14 晚定的新方式）。
        //   ⚠ 位置交给 selection 就够了 —— 不用 bbox，见上面那段注释。
        linkQueue('ps.mask.applyStamp',
          { docId: cap.docId,
            alphaBase64: outB64,
            selection: sel || cap.selection,
            layerName: label },
          done).catch(e=>rej(e));
      }else{
        linkQueue('ps.layer.place',
          { imageBase64: outB64,
            targetDocId: cap.docId,
            targetSelection: target,
            // ⚠ 必须 smartObject：抠出来的图层用户多半还要缩放/变形，
            //   普通像素层缩一次就掉画质
            layerType: 'smartObject' },
          done).catch(e=>rej(e));
      }
    });

    const ms = Date.now()-t0;
    const seg = info && info.ms ? ('推理 '+info.ms.infer+'ms · ') : '';
    const outSize = bb ? ((bb[2]-bb[0])+'×'+(bb[3]-bb[1])) : (capW+'×'+capH);
    // ⚠ 结尾这句话要跟【实际做了什么】对上。两条路产物完全不同，
    //   都写"已贴回"的话，用户去图层面板找那张透明图会找不到（他拿到的是带蒙版的盖印层）。
    const doneWord = useMask ? '已盖印并加好蒙版' : '已贴回';
    updateGenerationTask(id,{status:'done', pct:100,
      sub:outSize+' · '+seg+'共 '+ms+'ms · '+doneWord});
    aiAddLog('[抠像] 完成 · '+outSize+' · 共 '+ms+'ms '+(seg?('（'+seg.replace(/ · $/,'')+'）'):'')+' · '+doneWord
      +(useMask?'（想改边缘就拿画笔在蒙版上涂：白色=露出，黑色=挡住）':''),'success');
  }catch(e){
    // ⚠ 走到这儿的只剩"贴回"那一步抛的（前面几步都自己 fail 过并 return 了）
    fail(String(e&&e.message||e),'transfer','MATTING_PLACE_FAILED');
  }finally{
    mattingBusy = false;
  }
  return true;
}

// ═══════════════════════════════════════════════════════════
//  人体解析 / 指哪抠哪（2026-09-14 深夜）
//
//  ⚠⚠ 这两条链路和抠像【共用同一条路】，照 startMatting 的骨架写的：
//      检查引擎 → 抓选区 → 送引擎 → 结果进任务卡 → 盖印做蒙版
//    共用的东西有：抓图(ps.selection.capture)、抓图分辨率(mattingMaxEdge)、
//    选区夹取(mattingClampSelection)、任务卡渲染、报错卡、盖印蒙版的桥动作。
//    ⚠ 改其中任何一条时先想想另外两条会不会一起受影响。
//
//  ⚠ 三个 busy 闸【分开】：引擎一次只加载一个大模型，但三个功能各跑各的时
//    互相等是对的，而"抠像在跑就不让点分割"会让用户以为界面卡死。
//    真正的串行由引擎那边保证（它自己一次只留一个会话）。
// ═══════════════════════════════════════════════════════════
let segmentBusy = false, sam2Busy = false;

// ⭐ 哪些任务种类属于"工具类"（走外挂引擎、报错现场是同一套）。
//   ⚠ 再加一种外挂能力时【只改这一行】——别去各处补 `kind==='xxx'||...`，
//     那种散落的判断必然漏，而且漏了不报错（铁律 17）。
const TOOL_TASK_KINDS = ['matting','segment','sam2','glow','dlss'];

// 指哪抠哪：三个候选的原始数据先寄存在这儿，用户挑中哪个再取哪个。
// ⚠ 故意【不挂在 task 对象上】：task 会被写进生成记录/缓存，
//   带着三份 base64 进去等于把缓存撑大好几倍（docs/21 那笔账）。
const sam2Pending = new Map();      // taskId -> [{index, alphaBase64}, ...]

function makeToolTask(kind, payload, shotCount){
  const taskId=++taskSeq;
  const n=Math.max(1, Number(shotCount)||1);
  return {
    id:taskId, kind:String(kind), taskId:String(payload&&payload.taskId||''),
    label:String(payload&&payload.label||''),
    presetTitle:String(payload&&payload.label||''),
    icon:'hourglass',
    shots:Array.from({length:n},()=>({done:false})),
    pct:0, status:'queued', sub:'准备开始 · 等 Photoshop 选区',
    page:0, sourceImg:placeholderSVG((taskId*53)%360), sourceImgId:'',
    errorInfo:null, life:0, startedAt:Date.now(),
    outputs:[], errors:[],
    mattingTierName:'', mattingSize:'',
    sourceDocId:null, sourceDocName:'', sourceSelection:null,
    cancelRequested:false, returnState:'idle'
  };
}

// 三条链路共用的"抓选区"。返回 {cap, b64, capW, capH} 或抛错。
async function toolCaptureSelection(id, vals, opts){
  const maxEdge = mattingMaxEdge(vals);
  updateGenerationTask(id,{sub:'从 Photoshop 抓选区', pct:12});
  const cap = await new Promise((res,rej)=>{
    linkQueue('ps.selection.capture',
      { allowFullCanvas: (opts&&opts.allowFullCanvas!==undefined)
          ? !!opts.allowFullCanvas : !!settingsRuntime.autoFullCanvas,
        maxResolution: maxEdge },
      { after:(d)=>res(d),
        // ⚠ 把桥给的诊断现场原样带出来 —— 它知道"文档是16位"这种真正有用的信息
        afterError:(r)=>rej(new Error(linkResultMessage(r))) }
    ).catch(e=>rej(e));
  });
  const b64 = cap && (cap.imageBase64 || cap.inputImageBase64);
  if(!b64) throw Object.assign(new Error('抓回来的数据里没有图片'),{code:'PS_CAPTURE_FAILED',stage:'capture'});
  return { cap, b64, capW:Number(cap.width)||0, capH:Number(cap.height)||0 };
}

// ───────────────────────────────────────────────────────────
//  人体解析：一次认出十几个部位 → 一个组，每个部位一个图层 + 蒙版
//  产物形态是用户定的：「新建一个组 组里是我的多份原图，原图会有蒙版，
//  蒙版就是推理出的部位和范围，图层的名字是部位名字」
// ───────────────────────────────────────────────────────────
async function startSegment(preset, params){
  if(!window.MATTINGENGINE){ ERR.report('SEGMENT_RUN_FAILED',{message:'matting-engine.js 没加载'}); return false; }
  if(segmentBusy){ ERR.report('SEGMENT_BUSY',{message:'上一次还没跑完，等它完事再按'}); return false; }
  const PU = window.PRESETUI;
  const p = preset || (PU && PU.getToolPreset && PU.getToolPreset()) || null;
  const vals = params || (PU && PU.getToolParams && PU.getToolParams()) || {};
  const label = String((p && p.title) || '人体解析');

  const runId = aiNewTaskId('sg');
  const task = addTask(makeToolTask('segment',{taskId:runId, label},1));
  const id = task.id;
  const t0 = Date.now();
  segmentBusy = true;

  const fail = (message, stage, code)=>{
    const live = taskById(id);
    const keep = live && Array.isArray(live.shots) && live.shots.some(s=>s&&s.done&&s.imgId) ? {shots:live.shots} : {};
    updateGenerationTask(id, Object.assign({status:'failed', stage,
      errorCode:code||'SEGMENT_RUN_FAILED', error:String(message||'人体解析失败')}, keep));
    aiAddLog('[人体解析] 失败（'+(stage||'?')+'）：'+String(message||''),'warn');
  };

  try{
    // ── ① 引擎能不能用 ──
    updateGenerationTask(id,{status:'running', sub:'检查人体解析引擎', pct:5});
    await toolEngineReady(id,'人体解析');
    const why = MATTINGENGINE.unusableReason('segment');
    if(why){ fail(why,'engine','SEGMENT_UNUSABLE'); return true; }
    const tierNotes = [];
    const useTier = MATTINGENGINE.pickTier(vals.tier, tierNotes, 'segment');
    updateTask(id,{mattingTierName:MATTINGENGINE.tierName(useTier,'segment')});
    tierNotes.forEach(n=>aiAddLog('[人体解析] '+n,'warn'));

    // ── ② 抓图 ──
    const { cap, b64, capW, capH } = await toolCaptureSelection(id, vals, {});
    updateTask(id,{sourceDocId:cap.docId, sourceDocName:cap.docName||'',
      sourceSelection:cap.selection||null, mattingSize:capW+'×'+capH});
    registerTaskSourceImage(id, b64, cap.mime||'image/png');
    updateGenerationTask(id,{sub:'已抓 '+capW+'×'+capH+' · 正在认部位', pct:30});

    // ── ③ 送引擎 ──
    const bin = base64ToBytes(String(b64).replace(/^data:[^,]+,/,''));
    const qp = [];
    if(vals.tier && vals.tier!=='auto') qp.push('model='+encodeURIComponent(MATTINGENGINE.keyForTier(Number(vals.tier),'segment')||''));
    let resp;
    try{
      resp = await fetch(MATTINGENGINE.base + '/segment' + (qp.length?('?'+qp.join('&')):''), {
        method:'POST',
        headers:{ 'Content-Type':'image/png',
                  'X-Params': encodeURIComponent(JSON.stringify({
                    parts: Array.isArray(vals.parts)?vals.parts:[],
                    minPercent: Number(vals.minPercent)||0.3,
                    masks: true
                  })) },
        body: bin
      });
    }catch(e){ fail('引擎没应答：'+String(e&&e.message||e),'segment','SEGMENT_RUN_FAILED'); return true; }
    if(!resp.ok){
      let msg='HTTP '+resp.status, code='SEGMENT_RUN_FAILED';
      try{ const j=await resp.json(); if(j&&j.error) msg=j.error; if(j&&j.code) code=j.code; }catch(_){}
      fail(msg,'segment',code); return true;
    }
    const data = await resp.json();

    // ── ④ 挑出要做成图层的部位 ──
    // ⚠ 背景(id 0)永远不做 —— 用户要的是主体的部位，把背景做成图层没有意义。
    const want = new Set((Array.isArray(vals.parts)?vals.parts:[]).map(Number));
    const parts = (data.parts||[])
      .filter(x => Number(x.id)!==0 && x.alphaB64)
      .filter(x => !want.size || want.has(Number(x.id)));
    if(!parts.length){
      // ⚠ 分两种情况说，否则用户查不下去：是"这图里没人"还是"你勾的那几个没有"
      if(want.size) fail('你勾的那几个部位，这张图里一个都没认出来','segment','SEGMENT_NO_PICKED_PART');
      else fail('模型在这块区域里没认出人','segment','SEGMENT_EMPTY');
      return true;
    }

    // ── ⑤ 每个部位的预览先进任务卡 ──
    // ⚠ 顺序有讲究：先登记缩略图，万一做进 PS 失败（比如文档被关了），
    //   用户至少还能看到认出了哪些部位，不是白跑一趟。
    const shots=[];
    for(const x of parts){
      let imgId='';
      try{
        if(window.IMG) imgId = await window.IMG.putFromBase64('data:image/png;base64,'+x.alphaB64, 'image/png');
      }catch(e){ aiAddLog('[人体解析] 「'+x.name+'」缩略图登记失败（不影响做图层）：'+String(e&&e.message||e),'warn'); }
      shots.push({done:true, imgId});
    }
    updateGenerationTask(id,{sub:'认出 '+parts.length+' 个部位 · 正在做进 Photoshop', pct:80, shots});
    aiAddLog('[人体解析] 认出 '+parts.length+' 个部位：'+parts.map(x=>x.name+' '+x.percent+'%').join('、'),'info');

    // ── ⑥ 盖印 → 转智能对象 → 复制 N 份各挂一个部位蒙版 → 装进一个组 ──
    const sel = mattingClampSelection(cap.selection, cap.docWidth, cap.docHeight) || cap.selection;
    const applied = await new Promise((res,rej)=>{
      linkQueue('ps.mask.applyGroup',
        { docId: cap.docId,
          selection: sel,
          groupName: String(vals.groupName||'').trim() || label,
          parts: parts.map(x=>({ name:x.name, alphaBase64:'data:image/png;base64,'+x.alphaB64 })) },
        { after:(d)=>res(d), afterError:(r)=>rej(new Error(linkResultMessage(r))) }
      ).catch(e=>rej(e));
    });

    // ⚠⚠ 桥那边【单个部位失败会跳过继续】，所以做成的数可能少于要求的数。
    //   少了必须说 —— 不说就是静默少做（铁律 17）。
    const madeN = (applied && Number(applied.count)) || parts.length;
    if(madeN < parts.length){
      ERR.report('SEGMENT_PARTIAL',{
        message:'要做 '+parts.length+' 个部位，实际做成 '+madeN+' 个',
        stage:'apply', taskId:runId,
        context:{'做成的':(applied&&applied.names||[]).join('、')}
      });
    }
    const ms = Date.now()-t0;
    const seg = data.ms ? ('推理 '+data.ms.infer+'ms · ') : '';
    updateGenerationTask(id,{status:'done', pct:100,
      sub:madeN+' 个部位 · '+seg+'共 '+ms+'ms · 已建组'});
    aiAddLog('[人体解析] 完成 · 组「'+((applied&&applied.groupName)||label)+'」共 '+madeN+' 个图层，'
      +'每个图层都带一个部位蒙版，拿画笔在蒙版上就能改','success');
  }catch(e){
    fail(String(e&&e.message||e), e&&e.stage||'apply', e&&e.code||'SEGMENT_APPLY_FAILED');
  }finally{
    segmentBusy = false;
  }
  return true;
}

// ───────────────────────────────────────────────────────────
//  指哪抠哪（SAM2）：用 PS 选区当框 → 三个候选 → 用户挑一个 → 盖印+蒙版
// ───────────────────────────────────────────────────────────
async function startSAM2(preset, params){
  if(!window.MATTINGENGINE){ ERR.report('SAM2_RUN_FAILED',{message:'matting-engine.js 没加载'}); return false; }
  if(sam2Busy){ ERR.report('SAM2_BUSY',{message:'上一次还没跑完，等它完事再按'}); return false; }
  const PU = window.PRESETUI;
  const p = preset || (PU && PU.getToolPreset && PU.getToolPreset()) || null;
  const vals = params || (PU && PU.getToolParams && PU.getToolParams()) || {};
  const label = String((p && p.title) || '指哪抠哪');

  const runId = aiNewTaskId('sm');
  const task = addTask(makeToolTask('sam2',{taskId:runId, label},1));
  const id = task.id;
  const t0 = Date.now();
  sam2Busy = true;

  const fail = (message, stage, code)=>{
    const live = taskById(id);
    const keep = live && Array.isArray(live.shots) && live.shots.some(s=>s&&s.done&&s.imgId) ? {shots:live.shots} : {};
    updateGenerationTask(id, Object.assign({status:'failed', stage,
      errorCode:code||'SAM2_RUN_FAILED', error:String(message||'指哪抠哪失败')}, keep));
    aiAddLog('[指哪抠哪] 失败（'+(stage||'?')+'）：'+String(message||''),'warn');
  };

  try{
    // ── ① 引擎能不能用 ──
    updateGenerationTask(id,{status:'running', sub:'检查引擎', pct:5});
    await toolEngineReady(id,'指哪抠哪');
    const why = MATTINGENGINE.unusableReason('sam2');
    if(why){ fail(why,'engine','SAM2_UNUSABLE'); return true; }
    const tierNotes = [];
    const useTier = MATTINGENGINE.pickTier(vals.tier, tierNotes, 'sam2');
    updateTask(id,{mattingTierName:MATTINGENGINE.tierName(useTier,'sam2')});
    tierNotes.forEach(n=>aiAddLog('[指哪抠哪] '+n,'warn'));

    // ── ② 抓图 ──
    // ⚠⚠ 这个功能【必须有真选区】—— 它的全部意义就是"你框哪我抠哪"。
    //   allowFullCanvas 关掉：没框就整张画布当框的话，它会去抠"整个画面里最像一个东西的那块"，
    //   结果完全不是用户想要的，而且用户不知道为什么。
    let capRes;
    try{
      capRes = await toolCaptureSelection(id, vals, {allowFullCanvas:false});
    }catch(e){
      fail('先在 Photoshop 里框住你要的东西，再按开始计算。（'+String(e&&e.message||e)+'）','capture','SAM2_NO_BOX');
      return true;
    }
    const { cap, b64, capW, capH } = capRes;
    if(!cap.selection){ fail('没拿到选区','capture','SAM2_NO_BOX'); return true; }
    updateTask(id,{sourceDocId:cap.docId, sourceDocName:cap.docName||'',
      sourceSelection:cap.selection||null, mattingSize:capW+'×'+capH});
    registerTaskSourceImage(id, b64, cap.mime||'image/png');
    updateGenerationTask(id,{sub:'已抓 '+capW+'×'+capH+' · 正在算', pct:30});

    // ── ③ 送引擎 ──
    // ⚠ 抓回来的图【就是选区那一块】，所以在这张图的坐标系里，
    //   用户框的那个框就是"整张图" —— box = [0,0,W,H]。别再去换算一次。
    const bin = base64ToBytes(String(b64).replace(/^data:[^,]+,/,''));
    const qp = [];
    if(vals.tier && vals.tier!=='auto') qp.push('model='+encodeURIComponent(MATTINGENGINE.keyForTier(Number(vals.tier),'sam2')||''));
    let resp;
    try{
      resp = await fetch(MATTINGENGINE.base + '/sam2' + (qp.length?('?'+qp.join('&')):''), {
        method:'POST',
        headers:{ 'Content-Type':'image/png',
                  'X-Params': encodeURIComponent(JSON.stringify({ mode:'box', box:[0,0,capW,capH] })) },
        body: bin
      });
    }catch(e){ fail('引擎没应答：'+String(e&&e.message||e),'sam2','SAM2_RUN_FAILED'); return true; }
    if(!resp.ok){
      let msg='HTTP '+resp.status, code='SAM2_RUN_FAILED';
      try{ const j=await resp.json(); if(j&&j.error) msg=j.error; if(j&&j.code) code=j.code; }catch(_){}
      fail(msg,'sam2',code); return true;
    }
    const data = await resp.json();
    const cands = (data.candidates||[]).filter(c=>c && c.alphaB64);
    if(!cands.length || !cands.some(c=>Number(c.pixels)>0)){
      fail('三个答案都是空的。把框拉得更贴近你要的那个东西再试一次','sam2','SAM2_EMPTY');
      return true;
    }

    // ── ④ 三个候选都登记成缩略图 ──
    const view=[];
    for(const c of cands){
      let imgId='';
      try{
        if(window.IMG) imgId = await window.IMG.putFromBase64('data:image/png;base64,'+c.alphaB64, 'image/png');
      }catch(e){ aiAddLog('[指哪抠哪] 候选缩略图登记失败：'+String(e&&e.message||e),'warn'); }
      view.push({index:Number(c.index), iou:Number(c.iou)||0, pixels:Number(c.pixels)||0, imgId});
    }
    // 原始数据寄存起来（不挂 task，见上面 sam2Pending 的注释）
    sam2Pending.set(id, cands.map(c=>({index:Number(c.index), alphaBase64:'data:image/png;base64,'+c.alphaB64})));

    const best = Number(data.best)||0;
    const ms1 = Date.now()-t0;
    updateTask(id,{sam2Candidates:view, sam2Best:best, sam2Picked:null,
      sam2DocId:cap.docId, sam2Selection:mattingClampSelection(cap.selection, cap.docWidth, cap.docHeight)||cap.selection,
      sam2Label:label});

    // ── ⑤ 自动用最好的那个，还是摆出来让用户挑 ──
    if(String(vals.pick||'ask')==='auto'){
      const bestShot = view.find(v=>v.index===best) || view[0];
      updateGenerationTask(id,{sub:'算好了 · 正在盖印并加蒙版', pct:80,
        shots:[{done:true, imgId:bestShot.imgId}]});
      await applySAM2Candidate(id, bestShot.index);
    }else{
      // ⚠ 状态要停在"等你挑"，不能标成 done —— 标 done 用户会以为已经进 PS 了。
      updateGenerationTask(id,{status:'running', pct:70,
        sub:'算好了（'+ms1+'ms）· 三个答案，点一个',
        shots:[{done:true, imgId:(view.find(v=>v.index===best)||view[0]).imgId}]});
      aiAddLog('[指哪抠哪] 给了三个答案，在任务卡上点一个（把握：'
        +view.map(v=>Math.round(v.iou*100)+'%').join(' / ')+'）','info');
    }
  }catch(e){
    fail(String(e&&e.message||e), e&&e.stage||'apply', e&&e.code||'SAM2_APPLY_FAILED');
  }finally{
    sam2Busy = false;
  }
  return true;
}

// 用户在任务卡上点中了某个候选（或 pick=auto 时自动调）→ 盖印 + 做成蒙版
async function applySAM2Candidate(taskId, index){
  const task = taskById(taskId);
  if(!task) return;
  const list = sam2Pending.get(taskId);
  const hit = Array.isArray(list) ? list.find(x=>Number(x.index)===Number(index)) : null;
  if(!hit){
    ERR.report('SAM2_APPLY_FAILED',{message:'这个答案的数据已经不在了（任务可能过期了）。重新跑一次',stage:'apply'});
    return;
  }
  // ⚠ 先把挑选条收起来再干活：不收的话用户能连点好几下，
  //   每点一次就往 PS 里塞一个图层（"点了没反应就再点"是最常见的用户行为）。
  updateTask(taskId,{sam2Picked:Number(index)});
  updateGenerationTask(taskId,{status:'running', pct:85, sub:'正在盖印并加蒙版'});
  try{
    await new Promise((res,rej)=>{
      linkQueue('ps.mask.applyStamp',
        { docId: task.sam2DocId,
          alphaBase64: hit.alphaBase64,
          selection: task.sam2Selection,
          layerName: String(task.sam2Label||task.label||'指哪抠哪') },
        { after:()=>res(), afterError:(r)=>rej(new Error(linkResultMessage(r))) }
      ).catch(e=>rej(e));
    });
    const v=(task.sam2Candidates||[]).find(x=>Number(x.index)===Number(index));
    updateGenerationTask(taskId,{status:'done', pct:100,
      sub:'已盖印并加好蒙版'+(v?(' · 把握 '+Math.round(v.iou*100)+'%'):'')});
    aiAddLog('[指哪抠哪] 完成 · 已盖印并加好蒙版（想改边缘就拿画笔在蒙版上涂：白色=露出，黑色=挡住）','success');
    sam2Pending.delete(taskId);       // 用完就丢，别占着内存
  }catch(e){
    // ⚠ 失败要把挑选条【放回去】，让用户能换一个再试 —— 否则他就卡死在这儿了
    updateTask(taskId,{sam2Picked:null});
    updateGenerationTask(taskId,{status:'failed', stage:'apply',
      errorCode:'SAM2_APPLY_FAILED', error:String(e&&e.message||e)});
    aiAddLog('[指哪抠哪] 做进 Photoshop 失败：'+String(e&&e.message||e),'warn');
  }
}

// base64 ↔ 二进制。⚠ 大图不要用 atob 一次性转字符串再 split，那会多占一份内存
function base64ToBytes(b64){
  const s = atob(b64);
  const n = s.length;
  const a = new Uint8Array(n);
  for(let i=0;i<n;i++) a[i] = s.charCodeAt(i);
  return a;
}
function bytesToBase64(bytes){
  // ⚠ 分块拼 —— 一次 apply 几 MB 会爆调用栈（4K 图必炸）
  let out = '';
  const CH = 0x8000;
  for(let i=0;i<bytes.length;i+=CH){
    out += String.fromCharCode.apply(null, bytes.subarray(i, i+CH));
  }
  return btoa(out);
}
function runLinkTransfer(){
  const image=linkRuntime.generated||linkRuntime.capture||makeLinkPlaceholder();
  if(!linkRuntime.capture&&!linkRuntime.generated) addLinkLog({direction:'UI',level:'warn',message:'传回测试没有历史图片，使用固定占位图'});
  return linkQueue('ps.layer.place',{imageBase64:image.imageBase64,targetDocId:linkRuntime.capture&&linkRuntime.capture.docId,targetSelection:linkRuntime.capture&&linkRuntime.capture.selection,layerType:'smartObject'},{testKey:'transfer'});
}
function runLinkGenerateAfterCapture(){
  const source=linkRuntime.capture;
  if(!source){setLinkTest('generate','failed','没有可生成的抓取图');return Promise.resolve({ok:false});}
  const image=makeLinkPlaceholder(); linkRuntime.generated=image;
  const taskId='link-gen-'+Date.now().toString(36);
  const task=makeGenerationTask({taskId,provider:'链路验证',model:'占位生成',size:'1K',aspectRatio:'1:1',batch:1,inputImageBase64:source.imageBase64,sourceImageBase64:source.sourceImageBase64||source.imageBase64,captureSnapshot:aiCaptureSnapshot(source,0),prompt:'链路验证占位生成'});
  addTask(task);
  updateGenerationTask(taskId,{status:'running',pct:50,shots:[{done:false}],sub:'占位图已生成 · 等待传回 Photoshop'});
  addLinkLog({direction:'UI',level:'info',message:'固定占位生成图已创建',outputBytes:linkSize(image)});
  return linkQueue('ps.layer.place',{imageBase64:image.imageBase64,targetDocId:source.docId,targetSelection:source.selection,layerType:'smartObject'},{testKey:'generate',after:()=>updateGenerationTask(taskId,{status:'done',pct:100,shots:[{done:true,src:linkImageSrc(image)}],sub:'链路验证完成 · 已传回 Photoshop'}),afterError:result=>updateGenerationTask(taskId,{status:'failed',sub:'传回失败：'+linkResultMessage(result)})});
}
function runLinkGenerate(){
  if(linkRuntime.capture) return runLinkGenerateAfterCapture();
  setLinkTest('generate','queued','等待抓取测试完成');
  return runLinkCapture(()=>runLinkGenerateAfterCapture());
}
function runLinkFull(){
  setLinkTest('capture','queued','完整链路第 1 步');
  setLinkTest('generate','queued','等待完整链路');
  return runLinkCapture(()=>runLinkGenerateAfterCapture());
}
function runLinkPSAction(action){
  const params=linkParamsForAction(action);
  return linkQueue(action,params,{testKey:'control'});
}
function bindLinkDetail(root){
  root.querySelectorAll('[data-link-test]').forEach(btn=>btn.addEventListener('click',e=>{
    e.stopPropagation(); const kind=btn.dataset.linkTest;
    if(kind==='capture') runLinkCapture();
    else if(kind==='transfer') runLinkTransfer();
    else if(kind==='generate') runLinkGenerate();
    else if(kind==='full') runLinkFull();
  }));
  root.querySelectorAll('[data-link-ps-action]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();runLinkPSAction(btn.dataset.linkPsAction);}));
  root.querySelectorAll('[data-link-field]').forEach(input=>input.addEventListener('input',()=>{linkRuntime.form[input.dataset.linkField]=input.value;}));
  const auto=root.querySelector('#linkAutoFullCanvas');
  if(auto) auto.addEventListener('change',()=>{linkRuntime.autoFullCanvas=!!auto.checked; addLinkLog({direction:'UI',level:'info',message:'无选区自动整图：'+(auto.checked?'开':'关')});});
  root.querySelectorAll('[data-link-visible]').forEach(input=>input.addEventListener('change',()=>{linkRuntime.form.visible=!!input.checked;}));
}
// 二级卡【内容层】整体上下滚动换内容。
// 预设卡的二级(列表 / 提示词框)用它，时序和位移量跟普通二级卡的错落换内容一致，
// 只是它只有一张卡、没有错落延迟。
// ⚠ 拿不到内容层就直接写，绝不能因为动画做不了就不换内容 ——
//   那会变成"切了主卡但二级还是上一张的内容"，比没动画糟得多。
// fresh = 这张卡刚从 display:none 冒出来（换了二级种类）。
// ⚠⚠ fresh 时【绝不能走淡出那一段】：它身上是上一次留下的旧内容，
//   淡出旧内容 = 用户先看到一堆不相干的东西闪一下，再等 150ms 才看到新的。
//   2026-09-14 用户实测报的"慢一拍 + 闪烁感"就是这个。
//   正确做法：立刻写新内容，然后只播滑入。
function slideZoneBody(inner, writeAll, dir, fresh){
  if(!inner){ writeAll(); return; }
  const out = dir>0 ? -SLIDE_Z : SLIDE_Z;
  const inn = dir>0 ?  SLIDE_Z : -SLIDE_Z;
  if(fresh){
    writeAll();
    inner.style.transition='none';
    inner.style.transform='translateY('+inn+'px)';
    inner.style.opacity='0';
    requestAnimationFrame(()=>{
      inner.style.transition='transform .18s var(--ease-out), opacity .15s var(--ease-soft)';
      inner.style.transform='translateY(0)';
      inner.style.opacity='1';
      setTimeout(()=>{
        if(inner.style.transform==='translateY(0px)'||inner.style.transform==='translateY(0)'){
          inner.style.transform=''; inner.style.transition='';
        }
      },200);
    });
    return;
  }
  inner.style.transition='transform .15s var(--ease-out), opacity .15s var(--ease-soft)';
  inner.style.transform='translateY('+out+'px)';
  inner.style.opacity='0';
  setTimeout(()=>{
    writeAll();
    inner.style.transition='none';
    inner.style.transform='translateY('+inn+'px)';
    requestAnimationFrame(()=>{
      inner.style.transition='transform .18s var(--ease-out), opacity .15s var(--ease-soft)';
      inner.style.transform='translateY(0)';
      inner.style.opacity='1';
      // ⚠ 播完把内联 transform 清干净。残留的 transform 会让它变成
      //   包含块，里面任何 position:fixed 的东西都会被"关小黑屋"
      //   (记忆里栽过这个坑)。现在下拉面板是挂在 body 下的、不受影响，
      //   但以后要是有人往二级里塞浮层，留着这行残留就是个雷。
      setTimeout(()=>{
        if(inner.style.transform==='translateY(0px)'||inner.style.transform==='translateY(0)'){
          inner.style.transform=''; inner.style.transition='';
        }
      },200);
    });
  },150);
}
let detailFillSeq=0;
function specialDetailFill(writeAll,animate,dir){
  const sequence=++detailFillSeq,route=cur+':'+zoneSel,slide=detail.querySelector('.dc-slide');
  const write=()=>{if(sequence!==detailFillSeq||route!==cur+':'+zoneSel)return false;writeAll();return true;};
  if(!animate||!slide){write();if(slide){slide.style.transition='none';slide.style.transform='translateY(0)';slide.style.opacity='1';}return;}
  const out=dir>0?-SLIDE_D:SLIDE_D,inn=dir>0?SLIDE_D:-SLIDE_D;
  slide.style.transition='transform .2s var(--ease-out), opacity .18s var(--ease-soft)';slide.style.transform='translateY('+out+'px)';slide.style.opacity='0';
  setTimeout(()=>{if(!write())return;slide.style.transition='none';slide.style.transform='translateY('+inn+'px)';requestAnimationFrame(()=>{if(sequence!==detailFillSeq)return;slide.style.transition='transform .2s var(--ease-out), opacity .18s var(--ease-soft)';slide.style.transform='translateY(0)';slide.style.opacity='1';});},190);
}
function fillLinkDetail(animate,dir){
  const set=LINK_ZONE_SET; const item=set[zoneSel]||set[0]; const body=document.getElementById('dcBody'); const nameEl=detail.querySelector('.dc-name'); if(!body||!item)return;
  // 同一分区的状态回执只更新节点，不能重新创建输入框或 action 列表。
  if(!animate && linkPanelForZone(zoneSel)){
    if(nameEl) nameEl.textContent=item[1];
    refreshLinkStatusInPlace();
    refreshLinkDynamicInPlace();
    return;
  }
  const writeAll=()=>{
    if(nameEl) nameEl.textContent=item[1];
    const connected=linkRuntime.connected, status=linkRuntime.tests[zoneSel===0?'capture':zoneSel===1?'transfer':zoneSel===2?'generate':'control'];
    let html='<div class="link-panel" data-link-zone="'+zoneSel+'"><div class="link-state '+(connected?'ok':'')+'"><span class="link-dot"></span><span data-link-connection>'+(connected?'UXP 已连接':'等待 UXP 连接')+'</span><span data-link-test-status>'+linkStatusText(status)+'</span></div>';
    if(zoneSel===0){
      html+='<label class="link-switch"><input id="linkAutoFullCanvas" type="checkbox" '+(linkRuntime.autoFullCanvas?'checked':'')+'>无选区时自动使用整张画布</label>';
      html+='<button class="link-btn" data-link-test="capture">执行抓取测试</button>';
      html+='<div data-link-dynamic>'+linkDynamicHtml(0)+'</div>';
    }else if(zoneSel===1){
      html+='<button class="link-btn" data-link-test="transfer">执行传回测试</button>';
      html+='<div data-link-dynamic>'+linkDynamicHtml(1)+'</div>';
    }else if(zoneSel===2){
      html+='<button class="link-btn" data-link-test="generate">执行生成测试</button><button class="link-btn" data-link-test="full">运行完整链路</button>';
      html+='<div data-link-dynamic>'+linkDynamicHtml(2)+'</div>';
      html+='<div class="devrow"><span>生成器</span><span class="dv-val">固定占位图（未接真实引擎）</span></div>';
    }else{
      html+='<div class="link-fields">'+
        '<input data-link-field="docId" value="'+escapeHtml(linkRuntime.form.docId)+'" placeholder="文档 ID">'+
        '<input data-link-field="layerId" value="'+escapeHtml(linkRuntime.form.layerId)+'" placeholder="图层 ID">'+
        '<input data-link-field="layerName" value="'+escapeHtml(linkRuntime.form.layerName)+'" placeholder="图层名称">'+
        '<input data-link-field="opacity" value="'+escapeHtml(linkRuntime.form.opacity)+'" placeholder="不透明度">'+
        '<input data-link-field="aspect" value="'+escapeHtml(linkRuntime.form.aspect)+'" placeholder="选框比例">'+
        '<input data-link-field="channelId" value="'+escapeHtml(linkRuntime.form.channelId)+'" placeholder="通道 ID">'+
        '<input data-link-field="groupIds" value="'+escapeHtml(linkRuntime.form.groupIds)+'" placeholder="图层 ID（逗号分隔）">'+
         '<input data-link-field="groupName" value="'+escapeHtml(linkRuntime.form.groupName)+'" placeholder="编组名称">'+
         '<input data-link-field="exportPath" value="'+escapeHtml(linkRuntime.form.exportPath)+'" placeholder="导出 file:/ 路径">'+
         '<label class="link-switch"><input data-link-visible type="checkbox" '+(linkRuntime.form.visible?'checked':'')+'>可见</label></div>';
      html+='<div class="link-action-list">'+linkRuntime.actions.map(linkActionRowHtml).join('')+'</div>';
    }
    html+='</div>'; body.innerHTML=html;
    const actionList=body.querySelector('.link-action-list');
    if(actionList) actionList.dataset.signature=linkActionSignature();
    bindLinkDetail(body);
  };
  specialDetailFill(writeAll,animate,dir);
}
async function copyLogText(){
  const text=linkRuntime.logs.map(l=>[l.at,l.direction,l.level,l.action||'',l.requestId||'',l.message].join(' | ')).join('\n');
  if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);
  else{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);try{ta.select();if(!document.execCommand('copy'))throw new Error('复制失败，请检查剪贴板权限。');}finally{ta.remove();}}
  addLinkLog({level:'success',message:'日志文本已复制'});
}
function bindLogDetail(root){
  const clear=root.querySelector('[data-log-clear]'); if(clear) clear.addEventListener('click',e=>{e.stopPropagation();linkRuntime.logs.length=0;addLinkLog({level:'info',message:'日志已清空'});});
  const copy=root.querySelector('[data-log-copy]'); if(copy) copy.addEventListener('click',e=>{e.stopPropagation();copyLogText().catch(error=>ERR.report('LAYOUT_FAILED',{message:String(error.message||error)}));});
}
function fillLogDetail(animate,dir){
  const set=LOG_ZONE_SET; const item=set[zoneSel]||set[0]; const body=document.getElementById('dcBody'); const nameEl=detail.querySelector('.dc-name'); if(!body||!item)return;
  if(!animate && body.querySelector('.link-panel[data-log-zone="'+String(zoneSel)+'"]')){
    if(nameEl) nameEl.textContent=item[1];
    refreshLogDetailInPlace();
    return;
  }
  const writeAll=()=>{
    if(nameEl) nameEl.textContent=item[1];
    const logs=visibleLinkLogs();
    let html='<div class="link-panel" data-log-zone="'+zoneSel+'">';
    if(zoneSel===2){html+='<button class="link-btn" data-log-clear>清空本地日志</button><div class="devrow"><span>当前记录</span><span class="dv-val" data-log-count>'+linkRuntime.logs.length+' 条</span></div>';}else if(zoneSel===3){html+='<button class="link-btn" data-log-copy>复制全部日志</button><div class="devrow"><span>当前记录</span><span class="dv-val" data-log-count>'+linkRuntime.logs.length+' 条</span></div>';}else{
      const entries=logs.length?logs.slice().reverse().map(logEntryHtml).join(''):'<div class="devrow"><span>暂无日志</span><span class="dv-val">等待链路事件</span></div>';
      html+='<div class="log-list" data-log-list>'+entries+'</div>';
    }
    html+='</div>';body.innerHTML=html;bindLogDetail(body);
  };
  specialDetailFill(writeAll,animate,dir);
}

// ── AI 全量验证运行时：状态与输入分离，生成进度只更新节点 ──
// 一次最多生成多少张。⚠ 全项目唯一出处 —— 这个数字原先散在 5 个地方
// (卡面控件、调试面板、aiReadFields 的钳制、两个壳各自的 total 计算)，改一处必漏其余。
// ⚠ 两个壳的后端也要同步(main.js / tauri-adapter.js 里各有一份 AI_BATCH_MAX)，
//   只改界面的话用户看到上限 18、后端照样肯跑更多(铁律 14)。
// ⚠ 必须声明在【所有使用点之前】：const 有暂时性死区，
//   放晚了整个主脚本会当场抛错、后面的初始化全不跑(铁律 17，2026-09-11 连栽两次)。
const AI_BATCH_MAX=18;
const AI_ASPECTS=['1:1','Auto','9:16','16:9','2:3','3:2','3:4','4:3','4:5','5:4','21:9','9:21','2:1','1:2','3:1','1:3'];
const AI_MODELS=[
  ['AJbanana3','香蕉Pro'],['Banana-pro-D','香蕉Pro-D'],['AJbanana2','香蕉2'],['gemini-2.5-flash-image','香蕉1'],['gpt-image-2','GPT-Image-2'],
  ['nano-banana-2','nano-banana-2'],['nano-banana-fast','nano-banana-fast'],['nano-banana','nano-banana'],['nano-banana-pro','nano-banana-pro'],['nano-banana-pro-vip','nano-banana-pro-vip'],['gpt-image-2-vip','GPT-Image-2 VIP']
];
// ═══ 模型名单：先问后台，后台没有就用上面这份（docs/114 第 5 件）═══
//
//  ⚠⚠ 2026-10-02 实装时查到：后台 /v1/models 现在【不能直接替换】上面这份 ——
//     真实库里 aji / momo 两个服务商的模型表是空的，GRS 根本没登记，
//     其余几条是占位名（banana-image 之类，服务商那边根本不存在）。
//     直接替换 = 下拉框里全是选了就失败的模型。
//  → 所以规则是：当前通道（aji / momo / grs）后台【有登记】就用后台的，
//     后台是空的 / 没登录 / 连不上，就用上面写死的这份（方案要求的「离线兜底」）。
//     按现在的数据结果跟改之前一模一样；以后后台给 aji 填上模型，生成卡自动跟上。
//  ⚠ 用户已经选中的模型不在名单里时【保留它】（标「当前」），不悄悄换掉 ——
//     悄悄换模型 = 价格、效果都变了，用户还不知道。
//  ⚠ 「自定义」通道（other）不问后台：那是用户自己接的服务，后台不可能知道它有什么模型。
const aiBackendModels=new Map();   // 通道 → [[id,名字],...]
let aiBackendModelsEpoch=0;
function aiModelSlot(){return String(aiRuntime.connectionSlot||settingsRuntime.provider||'aji');}
/* ⭐ 2026-10-08：阿吉的模型名带分辨率后缀（AJbanana3-2k）。
   用户定："三档浓缩成一个模型选择" ⇒ 界面上显示【基础名】，后缀交给分辨率栏。
   ⚠ 这个工具要放在 aiModelOptions 之前 —— 它是 const 箭头函数，
     放在后面用会撞暂时性死区（那个坑本项目栽过，注释里也写着）。 */
const AI_SIZE_SUFFIX=/-(?:1k|2k|4k)$/i;
const aiModelBase=id=>String(id==null?'':id).replace(AI_SIZE_SUFFIX,'');
const AI_SIZES=['1K','2K','4K'];
const aiSizeOfId=id=>{const m=AI_SIZE_SUFFIX.exec(String(id==null?'':id));return m?m[0].slice(1).toUpperCase():'';};
/* ⭐⭐ 2026-10-07 新增第三层来源（用户要求："从中转站动态拉取模型""筛选掉不必要的字段，只拉取生图模型"）：
   优先级 = ①用户自己中转站探测到的名单 → ②后台账号的模型表 → ③写死的兜底 AI_MODELS。
   ⚠ 为什么①最可信：那是用户自己填的地址和 Key，拉回来的就是他实际能用的模型；
     而②后台（docs/121 实测）当时是空的/占位名，③写死那份里混着中转商自定义别名、换站就失效。
   ⚠ 每一项带"tier"：'image' = 确定像生图（下拉框正常亮度）；'other' = 名字看不出/疑似非生图
     （下拉框灰色，但【仍然可选】—— 中转商爱起自定义名，删掉就是静默失效，绝不许删）。
   ⚠ 当前选中的模型永远保留（沿用原来那条规矩："不悄悄换掉"，换了价格和效果都变）。

   ⚠⚠⚠ 2026-10-08（用户定）：**从没填过 Key 的连接 ⇒ 模型下拉框必须是空的**，
     并在那一行直接引导"请到设置里配置连接 API Key"。
     原话："如果说用户从来都没有在那个地方输入过key的话，那么模型选择那个地方就必然是空的，
     空的那个地方就过去就是没有模型，请到设置里面配置连接API key就OK。"
     ⇒ 理由：没配连接时给他看一串模型名是【假的可用性】——他选了半天，生成时才失败。
       更糟的是原来那份写死的兜底名单里有中转商别名（AJbanana3 这种），
       换个中转站根本不存在。宁可他这一刻看到"没有模型"，也不要他以为能用。
     ⚠ 判定用 connection().url（"这个槽配过地址没有"），不看 apiKey ——
       有的中转站地址填了 Key 还没填，那也是"没配完"，同样不给名单。
     ⚠ 判据不许自己拼字段（去读 V7ProviderConnections），否则以后槽位改名这里就静默失配。 */
function aiConnectionConfigured(){
  try{
    const c=window.V7ProviderConnections?.connection?.(settingsRuntime);
    return !!(c&&String(c.url||'').trim());
  }catch(_){ return false; }
}
// ⭐ 2026-10-21（用户要求，照 V6 算力槽位）：下拉框里露哪些模型、叫什么名字，由设置「渠道名字和露出的模型」决定。
//   ⚠ 只在这一层做（生成卡 / 助手 / 重算 / 记录都走 aiModelOptions），原始名单的生成（aiModelOptionsRaw）一个字没动。
//   ⚠ 只换显示名、只藏不删：真实模型 id 不变；当前选着的模型就算被藏也照样留着（老预设 / 历史重算不丢）。
function aiModelOptions(current){
  const rows=aiModelOptionsRaw(current);
  if(!window.V7ComputeSlots)return rows;
  const cur=current==null?String(aiRuntime.model||''):String(current||'');
  return V7ComputeSlots.applyModels(rows,(settingsRuntime.computeModelPrefs||{})[aiModelSlot()],cur);
}
function aiModelOptionsRaw(current){
  const slot=aiModelSlot();
  if(!aiConnectionConfigured()) return [];              // ⚠ 空就是空，不给兜底名单
  const 中转=window.V7ProviderSettings?.modelsFor?window.V7ProviderSettings.modelsFor(slot):null;
  // ⭐ 2026-10-24（V7待办/02）：阿吉 / 墨墨在我们后台配了【模型目录】（supplier-models.js）⇒ 下拉框以目录为准：
  //   显示名是供应商起的，键是基础请求名（拼不拼 -2K 后缀发请求时 modelForRequest 再按目录拼）。
  //   ⚠ 下面那套「阿吉名单按后缀收敛」只管中转站原始名单，目录的键本来就是基础名，别再过一遍（会被当成「不带后缀直接无视」）。
  //   中转站拉到、目录里没有的模型照旧灰色列在后面（老规矩：中转商爱起自定义名，删掉就是静默失效）。
  const 目录=(slot==='aji'||slot==='momo')&&window.V7SupplierModels?V7SupplierModels.modelsFor(slot):[];
  if(目录.length){
    const 当前=current==null?String(aiRuntime.model||''):String(current||'');
    const out=目录.map(m=>[m.id,m.name,'image']);
    const 见过=new Set(目录.map(m=>m.id.toLowerCase()));
    for(const raw of (中转||[])){
      const id=typeof raw==='string'?raw:String(raw&&(raw.id||raw[0])||'');
      const 基础=aiModelBase(id)||id;
      if(!基础||见过.has(基础.toLowerCase()))continue;
      见过.add(基础.toLowerCase());
      out.push([基础,基础,'other']);
    }
    const 当前基础=aiModelBase(当前)||当前;
    return (当前基础&&!out.some(x=>x[0].toLowerCase()===当前基础.toLowerCase()))?out.concat([[当前基础,当前基础+'（当前）','other']]):out;
  }
  const remote=aiBackendModels.get(slot);
  let list=null, tag=null;
  if(中转&&中转.length){
    const g=(window.V7ProviderModels&&V7ProviderModels.group)?V7ProviderModels.group(中转):{image:中转.slice(),other:[]};
    list=g.image.concat(g.other);
    tag=id=>g.image.includes(id)?'image':'other';
  }else if(remote&&remote.length){
    list=remote;
  }else{
    // ⭐ 2026-10-24（V7待办/04）：写死的 AI_MODELS 是【阿吉的名字】（AJbanana3 = 香蕉Pro …）。
    //   墨墨没拉到自己的清单时原来也退到这里 ⇒ 用户在墨墨下选「香蕉Pro」，发给墨墨的是 AJbanana3。
    //   墨墨 ⇒ 空着（生成卡写「点检查连接」），写死兜底只给阿吉和老路径用。
    list=slot==='momo'?[]:AI_MODELS;
  }
  const cur=current==null?String(aiRuntime.model||''):String(current||'');
  /* ⚠⚠⚠ 2026-10-08 修（用户反复报的"模型显示不正常、只有一个字母"，真因就在这里）：
     `list.map(x=>[x[0],x[1],…])` 这句【假定每一项是 [键,名字] 两元数组】，
     但三个来源的形状根本不一样：
       · AI_MODELS（写死那份）      → [['AJbanana3','香蕉Pro'], …]      两元数组 ✅
       · 后台模型表 aiBackendModels → [['gpt-image-1','gpt-image-1'], …] 两元数组 ✅
       · 中转站名单（中转缓存）      → ['AJbanana3','Banana-pro-D', …]   **纯字符串** ❌
     ⇒ 字符串取 [0]/[1] 就是它的【第 0 个字符和第 1 个字符】：
         'AJbanana3' → 键 'A'、名字 'J'；于是下拉框里出现 A / B / g / g / n / d 这种。
     实测证据（打桩一份真实名单跑出来的）：
        aiModelOptions() = [["A","J","other"],["B","a","other"],["g","e","other"],…]
     这是【形状假设写错】，跟下拉框宽度、跟显示名长短都无关 —— 我前面按"太窄被截断"去修过一轮，
     那是误判（宽度确实也窄，但那不是这个症状的原因）。
     ⇒ 在这里【统一归一化】：不管来源给的是字符串还是两元数组，一律先变成 [键, 显示名]。
     ⚠ 归一化必须在这一层做，不能在各调用方各做一遍（调用方有五处，漏一处就又出现单字母）。
     ⚠ 对象形状（{id,name}）也一并兜住 —— 后台以后可能改成对象。 */
  const 归一=x=>{
    if(typeof x==='string')return [x,x];                    // 中转站名单：字符串就是模型 id
    if(Array.isArray(x))return [String(x[0]),String(x[1]==null?x[0]:x[1])];
    if(x&&typeof x==='object'){const id=String(x.id||x.name||'');return [id,String(x.name||id)];}
    return ['',''];
  };
  let rows=list.map(归一).filter(r=>r[0]);

  /* ⭐⭐ 2026-10-08 阿吉专用：把"分辨率钉在模型名里"的名单收敛成一个模型。
     用户给的规则（原话）："所有不带后缀的直接无视，然后我们那边就只显示，
     就是123K浓缩成一个模型选择，然后我们的分辨率就联动这个模型的后缀，然后一起发出去"

     例：名单里 AJbanana3-1k / AJbanana3-2k / AJbanana3-4k 三条
       ⇒ 当前分辨率 2K 时，下拉框里只留【一条】AJbanana3（显示名不带后缀）。
     例：AJbanana3（不带后缀）⇒ 【直接无视】（用户明确要求）。

     ⚠ 只在"这份名单确实带后缀"时才启用这套规则。判据：列表里存在带 -1k/-2k/-4k 的项，
       且当前连接是阿吉。这样：
         · 别的服务商（默默/自定义）名单里没有这种后缀 ⇒ 一条都不动
         · 阿吉以后改了命名（不带后缀了）⇒ 自动不启用，不会把模型全过滤光
     ⚠ 万一当前分辨率一条都匹配不上（比如只有 -1k/-4k，用户选了 2K），
       不许把下拉框清空（那等于"选不了模型"）—— 退回"把全部基础名去重显示"，
       并且不接后缀（宁可发原样，也不要凭空拼一个 404 的模型名）。 */
  const isAji=isAjiConnection(aiRuntime);
  const 列表原样=rows;
  const 带后缀的=rows.filter(r=>aiSizeOfId(r[0]));
  if(isAji&&带后缀的.length){
    const 档=String(aiRuntime.size||'').toUpperCase();
    const 命中=rows.filter(r=>aiSizeOfId(r[0])===档);
    const 用这份=命中.length?命中:带后缀的;
    const 见过=new Set();const 收敛=[];
    for(const r of 用这份){
      const 基础=aiModelBase(r[0]);
      if(!基础||见过.has(基础))continue;      // 三档收敛成一个名字
      见过.add(基础);
      收敛.push([基础,基础]);
    }
    rows=收敛;
    // ⭐⭐ 2026-10-15 修（用户报：「本地前端似乎把 GPT Image 筛掉了」）：
    //   上面那条"不带后缀的直接无视"，本意是扔掉 AJbanana3 这种【跟分档版本重名的别名】。
    //   但它把【本来就不分档】的生图模型也一起扔了 —— gpt-image-2 / gpt-image-2.5-* / gemini-2.5-flash-image
    //   在阿吉名单里根本没有 -1k/-2k/-4k 版本，扔掉 = 这些模型在阿吉下永远选不到。
    //   ⇒ 只扔"有分档兄弟"的那种；没有分档版本的生图模型照常列出来（发请求时也原名发，见 ajiModelId）。
    //   ⚠ 只补【生图】的（名单分类里判成 image 的）；聊天/文字模型照旧不进下拉框，别把它刷成一长串。
    const 分档基础=new Set(带后缀的.map(r=>aiModelBase(r[0]).toLowerCase()));
    const 见过2=new Set(rows.map(r=>r[0].toLowerCase()));
    for(const r of 列表原样){
      if(aiSizeOfId(r[0]))continue;
      const k=r[0].toLowerCase();
      if(分档基础.has(k)||见过2.has(k))continue;
      if(tag&&tag(r[0])!=='image')continue;
      见过2.add(k);
      rows.push([r[0],r[1]]);
    }
    // ⚠ 当前选中的如果还带着后缀（老预设里存过），也要按基础名比对，否则会被当成"不在名单里"
    const curBase=aiModelBase(cur);
    return (curBase&&!rows.some(x=>x[0]===curBase))?rows.concat([[curBase,curBase+'（当前）','other']]):rows;
  }

  const rows2=rows.map(r=>[r[0],r[1],tag?tag(r[0]):((中转&&中转.length)?'other':'')]);
  return (cur&&!rows2.some(x=>x[0]===cur))?rows2.concat([[cur,cur+'（当前）','other']]):rows2;
}
async function aiRefreshBackendModels(){
  const B=window.V7Backend;
  if(!B||typeof B.models!=='function'||typeof B.state!=='function')return;
  const epoch=++aiBackendModelsEpoch;
  // 没登录（或刚换了账号）→ 清掉，回落到内置名单
  if(!B.state().signedIn){if(aiBackendModels.size){aiBackendModels.clear();renderGenerationCardFields();}return;}
  const slot=aiModelSlot();
  if(!['aji','momo','grs'].includes(slot))return;
  let rows;
  try{
    const r=await B.models(slot);
    rows=(r&&Array.isArray(r.models)?r.models:[]).filter(m=>m&&m.providerId===slot&&m.id).map(m=>[String(m.id),String(m.name||m.id)]);
  }catch(_){return;}   // 连不上就保持原样（兜底），不报错卡 —— 下拉框照常能用
  if(epoch!==aiBackendModelsEpoch)return;   // 期间换了账号/通道，这份作废
  const before=JSON.stringify(aiBackendModels.get(slot)||[]);
  aiBackendModels.set(slot,rows);
  if(before!==JSON.stringify(rows))renderGenerationCardFields();
}
// 什么时候去后台拿：开机一次、登录/换账号时、换通道时（这个通道还没拿过才拿）。
// ⚠ 开机那次要延后：这里比 settingsRuntime / aiRuntime 定义得早，同步调用会撞
//   const 暂时性死区，整个主脚本当场死掉（铁律 17 表里那条，本文件栽过两次）。
// ⚠ 不是每次存设置都去拿 —— 存设置很频繁，只有「这个通道还没拿过」才发请求。
// ⚠ 每一句都先确认有这个能力再挂：有几组测试会把本文件的源码切一段放进精简沙箱跑，
//   沙箱里没有 addEventListener。2026-10-02 不加判断时，ai-task-concurrency 那 4 条
//   【本来就红】的测试改成在这一行崩，把它们原来真正的病因（V7ProviderConnections 未定义）盖住了。
if(window.V7Backend&&typeof window.V7Backend.onChange==='function'){
  window.V7Backend.onChange(()=>{aiBackendModels.clear();aiRefreshBackendModels();});
}
if(typeof window.addEventListener==='function'){
  // ⭐ 2026-10-24（V7待办/02）：供应商模型目录到了 / 变了 ⇒ 生成卡的模型下拉、分辨率、单价跟着重画
  window.addEventListener('wheelchair:supplier-models',()=>{try{renderGenerationCardFields();}catch(_){}});
  window.addEventListener('wheelchair:settings-changed',()=>{if(!aiBackendModels.has(aiModelSlot()))aiRefreshBackendModels();});
  // ⚠⚠ 2026-10-07 新增两条：用户点「检查连接」拉到模型名单 / 刷到余额之后，
  //   生成卡的「模型」下拉框和右边的"约能生成 N 张"必须跟着更新 ——
  //   不接的话，用户检查完连接回到生成卡，看到的还是旧名单（而且不报错 = 静默失效）。
  //   ⚠ 用 try 包住：这个监听可能在宿主还没就位时被触发。
  window.addEventListener('wheelchair:provider-models',()=>{ try{renderGenerationCardFields();}catch(_){} });
  window.addEventListener('wheelchair:provider-balance',()=>{ try{renderGenerationCardFields();}catch(_){} });
}
if(typeof setTimeout==='function')setTimeout(()=>{aiRefreshBackendModels();},0);
