    const exact=ids.find(id=>String(id).toLowerCase()===want);
    if(exact)return String(exact);                       // 用名单里的原样大小写
    const 有分档=ids.some(id=>AJI_SIZE_SUFFIX.test(id)&&String(id).replace(AJI_SIZE_SUFFIX,'').toLowerCase()===小);
